1: import crypto from "crypto";
2: 
3: const ALGORITHM = "aes-256-cbc";
4: 
5: // Use ENCRYPTION_KEY if provided, otherwise derive a stable key from SUPABASE_SERVICE_ROLE_KEY.
6: // This prevents data loss if ENCRYPTION_KEY is forgotten, because the service role key is stable.
7: const fallbackKey = crypto
8:   .createHash("sha256")
9:   .update(process.env.SUPABASE_SERVICE_ROLE_KEY || "default_fallback_secret")
10:   .digest("hex");
11: const ENCRYPTION_KEY = process.env.ENCRYPTION_KEY || fallbackKey;
12: 
13: /**
14:  * Encrypts a text string using AES-256-CBC
15:  */
16: export function encrypt(text: string | null | undefined): string | null {
17:   if (!text) return null;
18:   
19:   const iv = crypto.randomBytes(16);
20:   const cipher = crypto.createCipheriv(
21:     ALGORITHM,
22:     Buffer.from(ENCRYPTION_KEY.substring(0, 64), "hex"),
23:     iv
24:   );
25:   
26:   let encrypted = cipher.update(text, "utf8", "hex");
27:   encrypted += cipher.final("hex");
28:   
29:   return `${iv.toString("hex")}:${encrypted}`;
30: }
31: 
32: /**
33:  * Decrypts a text string encrypted with AES-256-CBC
34:  */
35: export function decrypt(hash: string | null | undefined): string | null {
36:   if (!hash) return null;
37:   
38:   try {
39:     const [ivHex, encryptedText] = hash.split(":");
40:     if (!ivHex || !encryptedText) return hash; // might not be encrypted
41:     
42:     const iv = Buffer.from(ivHex, "hex");
43:     const decipher = crypto.createDecipheriv(
44:       ALGORITHM,
45:       Buffer.from(ENCRYPTION_KEY.substring(0, 64), "hex"),
46:       iv
47:     );
48:     
49:     let decrypted = decipher.update(encryptedText, "hex", "utf8");
50:     decrypted += decipher.final("utf8");
51:     
52:     return decrypted;
53:   } catch (error) {
54:     console.error("Decryption failed:", error);
55:     return "[Encrypted Data Error]";
56:   }
57: }
