let runningReserved = inv.reserved_quantity;

// 4. Iterate and find the first order matching available stock
for (const order of pendingBackorders) {
  const orderQty = order.order_items?.reduce((sum: number, item: any) => sum + item.quantity, 0) || 1;

  if (orderQty <= availableStock) {
    // Reserve stock for this order
    const holdUntil = new Date();
    holdUntil.setDate(holdUntil.getDate() + holdDays);

    // Update order status to 'backorder_held' and set held_until timestamp
    await supabaseAdmin
      .from("orders")
      .update({
        status: "backorder_held",
        admin_notes: `שוריון מלאי עתידי ל-${holdDays} ימים עד ${holdUntil.toLocaleString("he-IL")}`,
      })
      .eq("id", order.id);

    runningReserved += orderQty;

    // Increase reserved inventory
    await supabaseAdmin
      .from("inventory")
      .update({
        reserved_quantity: runningReserved,
        updated_at: new Date().toISOString(),
      })
      .eq("product_id", productId);

    // Update local available stock tracker
    availableStock -= orderQty;
    processedCount++;

