"use server";

import { createClient } from "@supabase/supabase-js";
import { checkSession } from "@/app/actions/adminAuth";

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL || "";
const supabaseServiceKey = process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY || "";
const supabaseAdmin = createClient(supabaseUrl, supabaseServiceKey);

export async function fetchAllExpenses() {
  const isAuth = await checkSession();
  if (!isAuth) {
    console.error("Unauthorized attempt to fetch expenses");
    return [];
  }

  try {
    const { data, error } = await supabaseAdmin
      .from("expenses")
      .select("*")
      .order("expense_date", { ascending: false });

    if (error) {
      console.error("Error fetching expenses:", error);
      return [];
    }
    return data || [];
  } catch (err) {
    console.error("Action error:", err);
    return [];
  }
}

export async function addExpense(expenseData: { expense_date: string; supplier_name: string; description: string; amount: number }) {
  const isAuth = await checkSession();
  if (!isAuth) {
    return { success: false, error: "Unauthorized" };
  }

  try {
    const { error } = await supabaseAdmin
      .from("expenses")
      .insert([expenseData]);

    if (error) {
      console.error("Error adding expense:", error);
      return { success: false, error: error.message };
    }
    return { success: true };
  } catch (err: any) {
    console.error("Action error:", err);
    return { success: false, error: err.message };
  }
}

export async function deleteExpense(id: string) {
  const isAuth = await checkSession();
  if (!isAuth) {
    return { success: false, error: "Unauthorized" };
  }

  try {
    const { error } = await supabaseAdmin
      .from("expenses")
      .delete()
      .eq("id", id);

    if (error) {
      console.error("Error deleting expense:", error);
      return { success: false, error: error.message };
    }
    return { success: true };
  } catch (err: any) {
    console.error("Action error:", err);
    return { success: false, error: err.message };
  }
}

