export async function updateOrderStatus(orderId: string, status: string) {
  const isAuth = await checkSession();
  if (!isAuth) {
    console.error("Unauthorized updateOrderStatus attempt");
    return false;
  }

  const { error } = await supabaseAdmin
    .from("orders")
    .update({ status })
    .eq("id", orderId);

  if (error) {
    console.error("Error updating order status:", error);
    return false;
  }

  // Trigger backorder queue processing in case stock was freed up
  try {
    const { processBackorderQueue } = await import("@/app/actions/backorderQueue");
    await processBackorderQueue();
  } catch (e) {
    console.error("Error processing queue after admin status update:", e);
  }

  return true;
}

export async function updateOrderNotes(orderId: string, notes: string) {
  const isAuth = await checkSession();
  if (!isAuth) {
    console.error("Unauthorized updateOrderNotes attempt");
    return false;
  }

  const { error } = await supabaseAdmin
    .from("orders")
    .update({ admin_notes: notes })
    .eq("id", orderId);

  if (error) {
    console.error("Error updating order notes:", error);
    return false;
  }
  return true;
}

