import { Order, OrderStatus } from '../types/order';
import { getSupabaseClient } from './supabase';
import { safeDecrypt } from './encryption';
import { loadAppSettings } from './storage';
import { logInfo, logWarn, logError } from './logger';
import { DEFAULT_SETTINGS } from '../config/constants';

function getApiHeaders(settings: any) {
  const token = settings.supabaseAnonKey || DEFAULT_SETTINGS.supabaseAnonKey;
  return {
    'Authorization': `Bearer ${token}`,
    'Content-Type': 'application/json',
  };
}

export async function fetchOrders(): Promise<Order[]> {
  const settings = await loadAppSettings();
  logInfo('FETCH_ORDERS', `Starting order fetch. Server URL: ${settings.serverUrl || 'None'}`);

  // 1. Try server API first for fully decrypted real orders
  if (settings.serverUrl) {
    try {
      const apiUrl = `${settings.serverUrl.replace(/\/$/, '')}/api/admin/orders`;
      logInfo('FETCH_ORDERS', `Sending GET to ${apiUrl}`);
      const res = await fetch(apiUrl, { method: 'GET', headers: getApiHeaders(settings) });
      logInfo('FETCH_ORDERS', `Server API response status: ${res.status}`);

