import crypto from "crypto";

const ALGORITHM = "aes-256-cbc";

// Guarantees exactly 32 bytes (256 bits) for aes-256-cbc regardless of ENV key format
function getCipherKey(): Buffer {
  const envKey = process.env.ENCRYPTION_KEY;
  if (envKey) {
    if (/^[0-9a-f]{64}$/i.test(envKey)) {
      return Buffer.from(envKey, "hex");
    }
    return crypto.createHash("sha256").update(envKey).digest();
  }
  // Stable fallback derived from service role key to prevent data loss
  return crypto
    .createHash("sha256")
    .update(process.env.SUPABASE_SERVICE_ROLE_KEY || "default_fallback_secret")
    .digest();
}

/**
 * Encrypts a text string using AES-256-CBC
 */
export function encrypt(text: string | null | undefined): string | null {
  if (!text) return null;

  const iv = crypto.randomBytes(16);
  const cipher = crypto.createCipheriv(
    ALGORITHM,
    getCipherKey(),
    iv
  );

  let encrypted = cipher.update(text, "utf8", "hex");
  encrypted += cipher.final("hex");

  return `${iv.toString("hex")}:${encrypted}`;
}

/**
 * Decrypts a text string encrypted with AES-256-CBC
 */
export function decrypt(hash: string | null | undefined): string | null {
  if (!hash) return null;

  try {
    const [ivHex, encryptedText] = hash.split(":");
    if (!ivHex || !encryptedText) return hash; // might not be encrypted

    const iv = Buffer.from(ivHex, "hex");
    const decipher = crypto.createDecipheriv(
      ALGORITHM,
      getCipherKey(),
      iv
    );

    let decrypted = decipher.update(encryptedText, "hex", "utf8");
    decrypted += decipher.final("utf8");

    return decrypted;
  } catch (error) {
    console.error("Decryption failed:", error);
    return "[Encrypted Data Error]";
  }
}

