"use server";

import { createClient } from "@supabase/supabase-js";
import { checkSession } from "@/app/actions/adminAuth";
import { fetchSetting, updateSetting } from "@/app/actions/settings";
import { decrypt, encrypt } from "@/lib/encryption";

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL || "";
const supabaseServiceKey = process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY || "";
const supabaseAdmin = createClient(supabaseUrl, supabaseServiceKey);

export interface TicketMessage {
  id: string;
  sender_type: "customer" | "admin" | "bot";
  message_text: string;
  created_at: string;
}

export interface SupportTicket {
  id: string;
  ticket_number: number;
  customer_phone: string;
  customer_name: string;
  subject?: string;
  description: string;
  status: "open" | "in_progress" | "resolved" | "closed";
  priority: "low" | "normal" | "urgent";
  related_order_id?: string;
  messages: TicketMessage[];
  created_at: string;
  updated_at: string;
}

const SETTINGS_STORE_KEY = "support_tickets_store";
export const CLOSING_MOTTO = "עבורנו, כל לגימה היא זיכרון וכל בקבוק הוא תרומה. הכנסו לאתר להכיר את הסיפור מאחורי עץ הלימון של מורן, לקרוא ולכתוב ביומן הזיכרונות:\nhttps://www.morancello.com";

/**
 * Helper to fetch all tickets (checks support_tickets table first, falls back to settings store)
 */
async function getTicketsFromStore(): Promise<SupportTicket[]> {
  try {
    // Try Supabase table first
    const { data, error } = await supabaseAdmin
      .from("support_tickets")
      .select("*, ticket_messages(*)")
      .order("created_at", { ascending: false });

    if (!error && data) {
      return data.map((t: any) => ({
        id: t.id,
        ticket_number: t.ticket_number,
        customer_phone: decrypt(t.customer_phone) || t.customer_phone,
        customer_name: decrypt(t.customer_name) || t.customer_name,
        subject: t.subject,
        description: t.description,
        status: t.status,
        priority: t.priority,
        related_order_id: t.related_order_id,
        messages: (t.ticket_messages || []).sort(
          (a: any, b: any) => new Date(a.created_at).getTime() - new Date(b.created_at).getTime()
        ),
        created_at: t.created_at,
        updated_at: t.updated_at,
      }));
    }
  } catch (e) {
    // Table might not exist yet, fallback to settings store
  }

  try {
    const raw = await fetchSetting(SETTINGS_STORE_KEY);
    if (!raw) return [];
    return JSON.parse(raw);
  } catch (e) {
    console.error("Error reading support tickets store:", e);
    return [];
  }
}

/**
 * Helper to save tickets into settings store fallback
 */
async function saveTicketsToStore(tickets: SupportTicket[]): Promise<boolean> {
  try {
    const { error } = await supabaseAdmin
      .from("settings")
      .upsert({ id: SETTINGS_STORE_KEY, value: JSON.stringify(tickets), updated_at: new Date().toISOString() });
    return !error;
  } catch (e) {
    console.error("Error saving support tickets store:", e);
    return false;
  }
}

/**
 * Fetch all support tickets (admin authorized)
 */
export async function fetchSupportTicketsAction(): Promise<SupportTicket[]> {
  const isAuth = await checkSession();
  if (!isAuth) {
    console.warn("Unauthorized attempt to fetch support tickets");
    return [];
  }
  return await getTicketsFromStore();
}

/**
 * Get the manager phone number for WhatsApp ticket forwarding
 */
export async function getSupportForwardPhoneAction(): Promise<string> {
  const val = await fetchSetting("support_forward_phone");
  return val || "0549995655";
}

/**
 * Update the manager phone number for WhatsApp ticket forwarding
 */
export async function updateSupportForwardPhoneAction(phone: string): Promise<{ success: boolean; error?: string }> {
  const isAuth = await checkSession();
  if (!isAuth) return { success: false, error: "Unauthorized" };

  const clean = phone.replace(/\D/g, "");
  if (!clean || clean.length < 9) {
    return { success: false, error: "מספר טלפון לא תקין" };
  }

  await updateSetting("support_forward_phone", clean);
  return { success: true };
}

/**
 * Create a new support ticket (called by WhatsApp bot or customer form)
 */
export async function createSupportTicketAction(data: {
  customerName: string;
  customerPhone: string;
  description: string;
  subject?: string;
  relatedOrderId?: string;
}): Promise<{ success: boolean; ticket?: SupportTicket; error?: string }> {
  try {
    const allTickets = await getTicketsFromStore();
    const nextNumber = allTickets.length > 0 ? Math.max(...allTickets.map((t) => t.ticket_number || 1000)) + 1 : 1001;
    const nowIso = new Date().toISOString();
    const newId = `tkt_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`;

    const initialMessage: TicketMessage = {
      id: `msg_${Date.now()}_1`,
      sender_type: "customer",
      message_text: data.description,
      created_at: nowIso,
    };

    const newTicket: SupportTicket = {
      id: newId,
      ticket_number: nextNumber,
      customer_phone: data.customerPhone.trim(),
      customer_name: data.customerName.trim(),
      subject: data.subject || "פניית שירות לקוחות",
      description: data.description.trim(),
      status: "open",
      priority: "normal",
      related_order_id: data.relatedOrderId,
      messages: [initialMessage],
      created_at: nowIso,
      updated_at: nowIso,
    };

    // Try saving to Supabase table
    let savedToTable = false;
    try {
      const { data: dbTicket, error: tktErr } = await supabaseAdmin
        .from("support_tickets")
        .insert({
          id: newId,
          ticket_number: nextNumber,
          customer_phone: encrypt(data.customerPhone.trim()),
          customer_name: encrypt(data.customerName.trim()),
          subject: newTicket.subject,
          description: newTicket.description,
          status: "open",
          priority: "normal",
          related_order_id: data.relatedOrderId || null,
        })
        .select()
        .single();

      if (!tktErr && dbTicket) {
        savedToTable = true;
        await supabaseAdmin.from("ticket_messages").insert({
          ticket_id: newId,
          sender_type: "customer",
          message_text: data.description,
        });
      }
    } catch (e) {
      // fallback
    }

    if (!savedToTable) {
      allTickets.unshift(newTicket);
      await saveTicketsToStore(allTickets);
    }

    // 1. Forward WhatsApp notification to Manager Phone
    const managerPhone = await getSupportForwardPhoneAction();
    if (managerPhone) {
      try {
        const { sendWhatsAppMessageDirect } = await import("@/lib/whatsappBot");
        const forwardMsg = `🔔 פניית שירות לקוחות חדשה (#T-${newTicket.ticket_number})! 🍋\n\n👤 מאת: ${newTicket.customer_name}\n📱 טלפון: ${newTicket.customer_phone}\n📝 תוכן: "${newTicket.description}"\n\nלצפייה ומענה מהיר באתר הניהול:\nhttps://www.morancello.com/admin?tab=support&id=${newTicket.id}`;
        await sendWhatsAppMessageDirect(managerPhone, forwardMsg);
      } catch (err) {
        console.error("Failed to forward ticket to manager via WhatsApp:", err);
      }
    }

    // 2. Trigger push notification for Mobile Admin App
    try {
      const { sendAdminPushNotification } = await import("@/lib/pushNotifications");
      await sendAdminPushNotification({
        title: `פנייה חדשה (#T-${newTicket.ticket_number}) מאת ${newTicket.customer_name} 💬`,
        body: newTicket.description.substring(0, 80),
        data: { action: "SUPPORT_TICKETS_RELOAD", ticketId: newTicket.id },
      });
    } catch (e) {}

    return { success: true, ticket: newTicket };
  } catch (err: any) {
    console.error("Error creating support ticket:", err);
    return { success: false, error: err.message || "שגיאה ביצירת פנייה" };
  }
}

/**
 * Reply to a support ticket from Admin Dashboard or Mobile App and send WhatsApp to customer
 */
export async function replyToSupportTicketAction(
  ticketId: string,
  replyText: string
): Promise<{ success: boolean; error?: string }> {
  const isAuth = await checkSession();
  if (!isAuth) return { success: false, error: "Unauthorized" };

  if (!replyText || !replyText.trim()) {
    return { success: false, error: "יש להזין תוכן מענה" };
  }

  const allTickets = await getTicketsFromStore();
  const ticket = allTickets.find((t) => t.id === ticketId || t.ticket_number.toString() === ticketId);
  if (!ticket) {
    return { success: false, error: "הפנייה לא נמצאה" };
  }

  const nowIso = new Date().toISOString();
  const adminMsg: TicketMessage = {
    id: `msg_${Date.now()}`,
    sender_type: "admin",
    message_text: replyText.trim(),
    created_at: nowIso,
  };

  // 1. Save to Supabase table or fallback store
  try {
    await supabaseAdmin.from("ticket_messages").insert({
      ticket_id: ticket.id,
      sender_type: "admin",
      message_text: replyText.trim(),
    });
    await supabaseAdmin
      .from("support_tickets")
      .update({ status: "in_progress", updated_at: nowIso })
      .eq("id", ticket.id);
  } catch (e) {}

  ticket.messages.push(adminMsg);
  ticket.status = "in_progress";
  ticket.updated_at = nowIso;
  await saveTicketsToStore(allTickets);

  // 2. Send official WhatsApp message to the customer
  try {
    const { sendWhatsAppMessageDirect } = await import("@/lib/whatsappBot");
    const waText = `שלום ${ticket.customer_name} 🍋,\nמענה מפניות מורנצ׳לו (פנייה #T-${ticket.ticket_number}):\n\n"${replyText.trim()}"\n\n${CLOSING_MOTTO}`;
    await sendWhatsAppMessageDirect(ticket.customer_phone, waText);
  } catch (err) {
    console.error("Error sending WhatsApp reply to customer:", err);
  }

  return { success: true };
}

/**
 * Update support ticket status (e.g. resolve or close)
 */
export async function updateSupportTicketStatusAction(
  ticketId: string,
  status: "open" | "in_progress" | "resolved" | "closed"
): Promise<{ success: boolean; error?: string }> {
  const isAuth = await checkSession();
  if (!isAuth) return { success: false, error: "Unauthorized" };

  const allTickets = await getTicketsFromStore();
  const ticket = allTickets.find((t) => t.id === ticketId || t.ticket_number.toString() === ticketId);
  if (!ticket) return { success: false, error: "הפנייה לא נמצאה" };

  const nowIso = new Date().toISOString();
  ticket.status = status;
  ticket.updated_at = nowIso;

  try {
    await supabaseAdmin
      .from("support_tickets")
      .update({ status, updated_at: nowIso })
      .eq("id", ticket.id);
  } catch (e) {}

  await saveTicketsToStore(allTickets);
  return { success: true };
}

