const http = require("http");
const path = require("path");
const fs = require("fs");
const dotenv = require("dotenv");
const qrcode = require("qrcode");
const pino = require("pino");
const crypto = require("crypto");
const { createClient } = require("@supabase/supabase-js");

// Try loading ../.env.local or .env
const envLocalPath = path.resolve(__dirname, "../.env.local");
if (fs.existsSync(envLocalPath)) {
  dotenv.config({ path: envLocalPath });
} else {
  dotenv.config();
}

// Polyfill native WebSocket if missing (for Supabase JS client)
if (!globalThis.WebSocket) {
  try {
    globalThis.WebSocket = require("ws");
  } catch (e) {}
}

const PORT = process.env.PORT || process.env.WHATSAPP_BOT_PORT || 3006;
const SUPABASE_URL = process.env.NEXT_PUBLIC_SUPABASE_URL;
const SUPABASE_KEY = process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;

if (!SUPABASE_URL || !SUPABASE_KEY) {
  console.warn("WARNING: Supabase URL or Key missing in whatsapp-bot/server.js!");
}

const supabase = createClient(SUPABASE_URL, SUPABASE_KEY);

const {
  default: makeWASocket,
  useMultiFileAuthState,
  DisconnectReason,
  fetchLatestBaileysVersion,
} = require("@whiskeysockets/baileys");

let sock = null;
let currentStatus = "disconnected"; // "connected" | "qr_ready" | "disconnected"
let currentQr = null;
let connectedPhone = null;
const authFolder = path.resolve(__dirname, "auth_info_baileys");

const CLOSING_MOTTO =
  "עבורנו, כל לגימה היא זיכרון וכל בקבוק הוא תרומה. הכנסו לאתר להכיר את הסיפור מאחורי עץ הלימון של מורן, לקרוא ולכתוב ביומן הזיכרונות:\nhttps://www.morancello.com";

// --- Encryption Helpers ---
function getCipherKey() {
  const envKey = process.env.ENCRYPTION_KEY;
  if (envKey) {
    if (/^[0-9a-f]{64}$/i.test(envKey)) {
      return Buffer.from(envKey, "hex");
    }
    return crypto.createHash("sha256").update(envKey).digest();
  }
  return crypto
    .createHash("sha256")
    .update(process.env.SUPABASE_SERVICE_ROLE_KEY || "default_fallback_secret")
    .digest();
}

function decrypt(hash) {
  if (!hash) return null;
  try {
    const [ivHex, encryptedText] = hash.split(":");
    if (!ivHex || !encryptedText) return hash;
    const iv = Buffer.from(ivHex, "hex");
    const decipher = crypto.createDecipheriv("aes-256-cbc", getCipherKey(), iv);
    let decrypted = decipher.update(encryptedText, "hex", "utf8");
    decrypted += decipher.final("utf8");
    return decrypted;
  } catch (e) {
    return hash;
  }
}

function encrypt(text) {
  if (!text) return null;
  const iv = crypto.randomBytes(16);
  const cipher = crypto.createCipheriv("aes-256-cbc", getCipherKey(), iv);
  let encrypted = cipher.update(text, "utf8", "hex");
  encrypted += cipher.final("hex");
  return `${iv.toString("hex")}:${encrypted}`;
}

// --- Sync Status & Heartbeat ---
async function syncStatusToSupabase(status, qr = null, phone = null) {
  currentStatus = status;
  currentQr = qr;
  if (phone) connectedPhone = phone;

  try {
    const payload = {
      status,
      qr,
      phone: connectedPhone,
      updatedAt: new Date().toISOString(),
      lastHeartbeat: Date.now(),
    };
    await supabase.from("settings").upsert(
      {
        id: "whatsapp_bot_status",
        value: JSON.stringify(payload),
      },
      { onConflict: "id" }
    );
    console.log(`[WhatsApp Bot] Synced status to Supabase: ${status} (Phone: ${connectedPhone || "N/A"})`);
  } catch (err) {
    console.error("[WhatsApp Bot] Error syncing status to Supabase:", err.message);
  }

  // Also sync directly to the live website API
  try {
    const siteUrl = (process.env.SITE_URL || "https://www.morancello.com").replace(/\/$/, "");
    await fetch(`${siteUrl}/api/whatsapp/status`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ status, qr, phone: connectedPhone }),
    });
  } catch (err) {
    // quiet
  }
}

// Periodic heartbeat every 20 seconds
setInterval(async () => {
  if (currentStatus !== "disconnected") {
    await syncStatusToSupabase(currentStatus, currentQr, connectedPhone).catch(() => {});
  }
}, 20000);

let isStarting = false;

// --- Session Store (Memory with 4h TTL) ---
const userSessions = new Map();

function getSession(phone) {
  const session = userSessions.get(phone);
  if (!session) return null;
  if (Date.now() - session.lastActive > 4 * 60 * 60 * 1000) {
    userSessions.delete(phone);
    return null;
  }
  return session;
}

function setSession(phone, data) {
  userSessions.set(phone, {
    ...data,
    lastActive: Date.now(),
  });
}

// Format number to international WhatsApp JID
function formatJid(rawPhone) {
  let clean = rawPhone.replace(/\D/g, "");
  if (clean.startsWith("0")) {
    clean = "972" + clean.substring(1);
  } else if (!clean.startsWith("972")) {
    clean = "972" + clean;
  }
  return `${clean}@s.whatsapp.net`;
}

// Send message function
async function sendMessage(toPhone, text) {
  if (!sock || currentStatus !== "connected") {
    throw new Error("WhatsApp bot is not connected");
  }
  const jid = formatJid(toPhone);
  const result = await sock.sendMessage(jid, { text });
  console.log(`[WhatsApp Bot] Message sent to ${jid}: ${text.substring(0, 30)}...`);
  return result;
}

// --- Main Baileys Initializer ---
async function startWhatsApp() {
  if (isStarting) return;
  isStarting = true;

  try {
    if (sock) {
      try {
        sock.ev.removeAllListeners();
        sock.end();
      } catch (e) {}
      sock = null;
    }

    const { state, saveCreds } = await useMultiFileAuthState(authFolder);
    const { version } = await fetchLatestBaileysVersion();

    console.log(`[WhatsApp Bot] Initializing Baileys v${version.join(".")}...`);

    sock = makeWASocket({
      version,
      auth: state,
      logger: pino({ level: "silent" }),
      printQRInTerminal: true,
    });

    sock.ev.on("creds.update", saveCreds);

    sock.ev.on("connection.update", async (update) => {
      const { connection, lastDisconnect, qr } = update;

      if (qr) {
        console.log("[WhatsApp Bot] QR code generated!");
        try {
          const qrDataUrl = await qrcode.toDataURL(qr, { margin: 2, scale: 7 });
          await syncStatusToSupabase("qr_ready", qrDataUrl, null);
        } catch (e) {
          console.error("Error generating QR data URL:", e);
        }
      }

      if (connection === "close") {
        const statusCode = lastDisconnect?.error?.output?.statusCode;
        const isLoggedOut = statusCode === DisconnectReason.loggedOut;
        console.log(`[WhatsApp Bot] Connection closed. StatusCode: ${statusCode}. IsLoggedOut: ${isLoggedOut}`);

        if (isLoggedOut) {
          console.log("[WhatsApp Bot] Device logged out. Resetting session...");
          try {
            fs.rmSync(authFolder, { recursive: true, force: true });
          } catch (e) {}
          connectedPhone = null;
          currentQr = null;
          await syncStatusToSupabase("disconnected", null, null);
          setTimeout(() => {
            startWhatsApp();
          }, 2000);
        } else {
          if (statusCode === 408) {
            console.log("[WhatsApp Bot] QR expired. Refreshing QR...");
          } else {
            await syncStatusToSupabase("disconnected", null, connectedPhone);
          }
          setTimeout(() => {
            startWhatsApp();
          }, 2500);
        }
      } else if (connection === "open") {
        const userJid = sock.user?.id || "";
        let phone = userJid.split(":")[0] || userJid.split("@")[0];
        if (phone.startsWith("972")) {
          phone = "0" + phone.substring(3);
        }
        connectedPhone = phone;
        console.log(`[WhatsApp Bot] Connected successfully! Phone: ${phone}`);
        await syncStatusToSupabase("connected", null, phone);
      }
    });

    // --- Inbound Customer Messages Listener ---
    sock.ev.on("messages.upsert", async ({ messages, type }) => {
      if (type !== "notify") return;
      for (const m of messages) {
        if (!m.message || m.key.fromMe) continue;
        const from = m.key.remoteJid;
        if (!from || from.includes("@g.us") || from.includes("status@broadcast")) continue;

        let senderPhone = from.split("@")[0].split(":")[0];
        if (senderPhone.startsWith("972")) {
          senderPhone = "0" + senderPhone.substring(3);
        }

        let text =
          m.message.conversation ||
          m.message.extendedTextMessage?.text ||
          m.message.imageMessage?.caption ||
          "";

        let location = null;
        if (m.message.locationMessage) {
          location = {
            degreesLatitude: m.message.locationMessage.degreesLatitude,
            degreesLongitude: m.message.locationMessage.degreesLongitude,
            name: m.message.locationMessage.name || m.message.locationMessage.address || "",
          };
        }

        try {
          await handleCustomerMessage(senderPhone, text, location);
        } catch (err) {
          console.error(`[WhatsApp Bot] Error handling message from ${senderPhone}:`, err);
        }
      }
    });
  } catch (err) {
    console.error("[WhatsApp Bot] Error in startWhatsApp:", err);
  } finally {
    isStarting = false;
  }
}

// --- Customer Conversational State Machine ---
async function handleCustomerMessage(phone, rawText, location) {
  const text = (rawText || "").trim();
  let session = getSession(phone);

  // 1. Gatekeeper: 18+ Age Verification
  if (!session || !session.ageVerified) {
    if (text === "1") {
      setSession(phone, { ageVerified: true, step: "MAIN_MENU" });
      await sendMainMenu(phone);
      return;
    } else if (text === "2") {
      userSessions.delete(phone);
      await sendMessage(
        phone,
        "🚫 בהתאם לחוק בישראל, מכירת משקאות אלכוהוליים לקטינים אסורה בהחלט.\nהשיחה הסתיימה. יום נעים!"
      );
      return;
    } else {
      setSession(phone, { ageVerified: false, step: "AGE_CHECK" });
      await sendMessage(
        phone,
        `שלום וברוכים הבאים למורנצ׳לו 🍋\n\n⚠️ אזהרה: צריכה מופרזת של אלכוהול מסכנת חיים ומזיקה לבריאות!\nבהתאם לחוק בישראל, רכישת משקאות אלכוהוליים מותרת מגיל 18 ומעלה בלבד.\n\nהאם הינך בן/בת 18 ומעלה?\n1️⃣ כן, אני מעל גיל 18\n2️⃣ לא, אני מתחת לגיל 18\n\nאנא השב עם הספרה 1 או 2:`
      );
      return;
    }
  }

  // 2. Global Escape to Menu: "0" or "תפריט"
  if (text === "0" || text === "תפריט" || text.toLowerCase() === "menu") {
    setSession(phone, { ageVerified: true, step: "MAIN_MENU" });
    await sendMainMenu(phone);
    return;
  }

  // 3. Dispatch based on current step
  switch (session.step) {
    case "MAIN_MENU":
      await handleMainMenuChoice(phone, text);
      break;
    case "BUY_QTY":
      await handleBuyQtyChoice(phone, text, session);
      break;
    case "BUY_PICKUP":
      await handleBuyPickupChoice(phone, text, session);
      break;
    case "BUY_ADDRESS":
      await handleBuyAddressInput(phone, text, location, session);
      break;
    case "BUY_SHIPPING":
      await handleBuyShippingChoice(phone, text, session);
      break;
    case "LOOKUP_ORDER":
      await handleOrderLookupInput(phone, text);
      break;
    case "CANCEL_CONFIRM":
      await handleCancelConfirm(phone, text, session);
      break;
    case "SUPPORT_NAME":
      await handleSupportName(phone, text, session);
      break;
    case "SUPPORT_DESC":
      await handleSupportDesc(phone, text, session);
      break;
    default:
      setSession(phone, { ageVerified: true, step: "MAIN_MENU" });
      await sendMainMenu(phone);
      break;
  }
}

