async function handleSupportDesc(phone, text, session) {
  if (!text || text.length < 3) {
    await sendMessage(phone, `אנא תאר בקצרה את הפנייה:`);
    return;
  }

  const customerName = session.supportName || "לקוח וואטסאפ";
  const desc = text;

  // 1. Fetch tickets store to determine next ticket number
  let nextNum = 1001;
  let allTickets = [];
  try {
    const { data: stData } = await supabase.from("settings").select("value").eq("id", "support_tickets_store").maybeSingle();
    if (stData?.value) {
      allTickets = JSON.parse(stData.value);
      if (allTickets.length > 0) {
        nextNum = Math.max(...allTickets.map((t) => t.ticket_number || 1000)) + 1;
      }
    }
  } catch (e) {}

  const ticketId = `tkt_${Date.now()}`;
  const nowIso = new Date().toISOString();

  const newTicket = {
    id: ticketId,
    ticket_number: nextNum,
    customer_phone: phone,
    customer_name: customerName,
    subject: "פנייה מוואטסאפ",
    description: desc,
    status: "open",
    priority: "normal",
    messages: [
      {
        id: `msg_${Date.now()}`,
        sender_type: "customer",
        message_text: desc,
        created_at: nowIso,
      },
    ],
    created_at: nowIso,
    updated_at: nowIso,
  };

  allTickets.unshift(newTicket);

  // Save to settings store
  await supabase.from("settings").upsert({
    id: "support_tickets_store",
    value: JSON.stringify(allTickets),
    updated_at: nowIso,
  });

  // Try saving to support_tickets table if exists
  try {
    await supabase.from("support_tickets").insert({
      id: ticketId,
      ticket_number: nextNum,
      customer_phone: encrypt(phone),
      customer_name: encrypt(customerName),
      description: desc,
      status: "open",
    });
    await supabase.from("ticket_messages").insert({
      ticket_id: ticketId,
      sender_type: "customer",
      message_text: desc,
    });
  } catch (e) {}

  // 2. Forward to Manager WhatsApp Phone
  try {
    const { data: phoneSetting } = await supabase.from("settings").select("value").eq("id", "support_forward_phone").maybeSingle();
    const managerPhone = phoneSetting?.value || "0549995655";
    if (managerPhone) {
      const forwardMsg = `🔔 פניית שירות לקוחות חדשה (#T-${nextNum})! 🍋\n\n👤 מאת: ${customerName}\n📱 טלפון: ${phone}\n📝 תוכן: "${desc}"\n\nלצפייה ומענה מהיר באתר הניהול:\nhttps://www.morancello.com/admin?tab=support&id=${ticketId}`;
      await sendMessage(managerPhone, forwardMsg);
    }
  } catch (err) {
    console.error("Failed to forward ticket to manager:", err);
  }

  // 3. Confirm to customer with Closing Motto
  await sendMessage(
    phone,
    `פנייתך התקבלה בהצלחה! 🍋\nמספר פנייה: #T-${nextNum}\n\nהפנייה הועברה לנציג שירות שישיב לך בהקדם ישירות לכאן בוואטסאפ.\n\n${CLOSING_MOTTO}`
  );

  setSession(phone, { ageVerified: true, step: "MAIN_MENU" });
}

// --- Order Matching Helper ---
async function findOrdersByPhone(phone) {
  const { data } = await supabase.from("orders").select("*").order("created_at", { ascending: false }).limit(20);
  if (!data) return [];

  const cleanDigits = phone.replace(/\D/g, "");
  return data.filter((order) => {
    let decPhone = order.customer_phone;
    try {
      decPhone = decrypt(order.customer_phone) || order.customer_phone;
    } catch (e) {}
    const orderPhoneDigits = (decPhone || "").replace(/\D/g, "");
    return cleanDigits.length >= 7 && orderPhoneDigits.endsWith(cleanDigits.slice(-7));
  });
}

function formatStatusHebrew(status) {
  const map = {
    pending: "ממתין לתשלום",
    paid: "שולם - בהכנה",
    processing: "באריזה והכנה למשלוח",
    shipped: "נארז ויצא לדרך עם שליח 🚚",
    delivered: "נמסר בהצלחה ✨",
    cancelled: "מבוטל",
    backorder_pending: "הזמנה עתידית (ממתין למלאי)",
    backorder_held: "מלאי שוריין (ממתין לתשלום)",
  };
  return map[status] || status;
}

// --- Outgoing Messages Queue Processor ---
let isProcessingQueue = false;

async function processOutgoingQueue() {
  if (currentStatus !== "connected" || !sock || isProcessingQueue) return;
  isProcessingQueue = true;

  try {
    const siteUrl = (process.env.SITE_URL || "https://www.morancello.com").replace(/\/$/, "");
    let queue = [];

    // 1. Fetch queue from live site API
    try {
      const res = await fetch(`${siteUrl}/api/whatsapp/queue`, { signal: AbortSignal.timeout(4000) });
      if (res.ok) {
        const data = await res.json();
        if (data.queue && Array.isArray(data.queue)) {
          queue = data.queue;
        }
      }
    } catch (e) {}

    if (queue.length === 0) {
      isProcessingQueue = false;
      return;
    }

    console.log(`[WhatsApp Bot] Found ${queue.length} outgoing messages in queue! Processing...`);

    const processedIds = [];
    for (const item of queue) {
      try {
        console.log(`[WhatsApp Bot] Dispatching message to ${item.phone}: ${item.message.substring(0, 40)}...`);
        await sendMessage(item.phone, item.message);
        processedIds.push(item.id);
        console.log(`[WhatsApp Bot] Successfully sent message ${item.id} to ${item.phone}!`);
      } catch (err) {
        console.error(`[WhatsApp Bot] Failed to send message ${item.id}:`, err.message);
        if (Date.now() - item.createdAt > 600000) {
          processedIds.push(item.id);
        }
      }
    }

    // Acknowledge processed messages back to live site
    if (processedIds.length > 0) {
      try {
        await fetch(`${siteUrl}/api/whatsapp/queue`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ removeIds: processedIds }),
        });
      } catch (e) {
        console.error("[WhatsApp Bot] Error acking queue:", e.message);
      }
    }
  } catch (err) {
    console.error("[WhatsApp Bot] Error in processOutgoingQueue:", err.message);
  } finally {
    isProcessingQueue = false;
  }
}

// Queue polling interval - every 2 seconds
setInterval(processOutgoingQueue, 2000);

// --- HTTP Microservice Server ---
const server = http.createServer(async (req, res) => {
  res.setHeader("Access-Control-Allow-Origin", "*");
  res.setHeader("Access-Control-Allow-Methods", "GET, POST, OPTIONS");
  res.setHeader("Access-Control-Allow-Headers", "Content-Type");

  if (req.method === "OPTIONS") {
    res.writeHead(204);
    return res.end();
  }

  const url = new URL(req.url, `http://${req.headers.host}`);

  if (url.pathname === "/status" && req.method === "GET") {
    res.writeHead(200, { "Content-Type": "application/json" });
    return res.end(
      JSON.stringify({
        status: currentStatus,
        qr: currentQr,
        phone: connectedPhone,
        updatedAt: new Date().toISOString(),
      })
    );
  }

  if (url.pathname === "/send-message" && req.method === "POST") {
    let body = "";
    req.on("data", (chunk) => (body += chunk));
    req.on("end", async () => {
      try {
        const { phone, message } = JSON.parse(body);
        if (!phone || !message) {
          res.writeHead(400, { "Content-Type": "application/json" });
          return res.end(JSON.stringify({ error: "Missing phone or message" }));
        }

        await sendMessage(phone, message);
        res.writeHead(200, { "Content-Type": "application/json" });
        return res.end(JSON.stringify({ success: true }));
      } catch (err) {
        res.writeHead(500, { "Content-Type": "application/json" });
        return res.end(JSON.stringify({ error: err.message }));
      }
    });
    return;
  }

  if (url.pathname === "/disconnect" && req.method === "POST") {
    try {
      if (sock) {
        await sock.logout().catch(() => {});
      }
      try {
        fs.rmSync(authFolder, { recursive: true, force: true });
      } catch (e) {}
      connectedPhone = null;
      await syncStatusToSupabase("disconnected", null, null);
      setTimeout(startWhatsApp, 1500);

      res.writeHead(200, { "Content-Type": "application/json" });
      return res.end(JSON.stringify({ success: true }));
    } catch (err) {
      res.writeHead(500, { "Content-Type": "application/json" });
      return res.end(JSON.stringify({ error: err.message }));
    }
  }

  if (url.pathname === "/connect" && req.method === "POST") {
    try {
      if (currentStatus !== "connected") {
        if (!currentQr) {
          try {
            fs.rmSync(authFolder, { recursive: true, force: true });
          } catch (e) {}
          connectedPhone = null;
        }
        startWhatsApp();
      }
      res.writeHead(200, { "Content-Type": "application/json" });
      return res.end(JSON.stringify({ success: true, status: currentStatus, qr: currentQr }));
    } catch (err) {
      res.writeHead(500, { "Content-Type": "application/json" });
      return res.end(JSON.stringify({ error: err.message }));
    }
  }

  res.writeHead(404, { "Content-Type": "application/json" });
  res.end(JSON.stringify({ error: "Not found" }));
});

server.listen(PORT, "0.0.0.0", () => {
  console.log(`===============================================`);
  console.log(`[WhatsApp Bot] Server listening on port ${PORT}`);
  console.log(`===============================================`);
  startWhatsApp();
});

