if (action === "create_or_update") {
  if (!reminder || (!reminder.orderId && !reminder.ticketId)) {
    return NextResponse.json({ success: false, error: "Missing reminder payload" }, { status: 400 });
  }

  current = current.filter((r) => {
    if (reminder.ticketId && (r.ticketId === reminder.ticketId || r.ticketNumber === reminder.ticketNumber)) {
      return false;
    }
    if (reminder.orderId && (r.orderId === reminder.orderId || r.orderNumber === reminder.orderNumber)) {
      return false;
    }
    return true;
  });

  const isTicket = !!reminder.ticketId;
  const newReminder = {
    id: reminder.id || `rem_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`,
    orderId: reminder.orderId || null,
    orderNumber: reminder.orderNumber || null,
    ticketId: reminder.ticketId || null,
    ticketNumber: reminder.ticketNumber || null,
    targetType: isTicket ? "ticket" : "order",
    customerName: reminder.customerName || "",
    customerPhone: reminder.customerPhone || "",
    reasonType: reminder.reasonType || (isTicket ? "ticket_followup" : "send"),
    customReasonText: reminder.customReasonText || "",
    dueTimestamp: reminder.dueTimestamp,
    isCompleted: false,
    createdAt: new Date().toISOString(),
  };

  current.push(newReminder);
  await saveSharedReminders(current);

  try {
    const { sendAdminPushNotification } = await import("@/lib/pushNotifications");
    const title = isTicket
      ? `תזכורת לפנייה #T-${newReminder.ticketNumber || ""}`
      : `תזכורת להזמנה #${newReminder.orderNumber || ""}`;
    sendAdminPushNotification({
      title,
      body: `${newReminder.customerName ? newReminder.customerName + ": " : ""}${newReminder.customReasonText || "תזכורת טיפול"}`,
      data: { action: "WIDGET_RELOAD" },
    }).catch(() => {});
  } catch (e) {}

  return NextResponse.json({ success: true, reminder: newReminder });
}

if (action === "delete") {
  const { reminderId, orderId, ticketId } = body;
  current = current.filter(
    (r) =>
      r.id !== reminderId &&
      (!orderId || r.orderId !== orderId) &&
      (!ticketId || r.ticketId !== ticketId)
  );
  await saveSharedReminders(current);

  return NextResponse.json({ success: true });
}

