"use client";

import React, { useState, useEffect } from "react";
import {
  MessageSquare,
  Search,
  CheckCircle2,
  Clock,
  Send,
  Phone,
  Calendar,
  AlertCircle,
  RefreshCw,
  Bell,
  Check,
  User,
  Filter,
} from "lucide-react";
import {
  fetchSupportTicketsAction,
  replyToSupportTicketAction,
  updateSupportTicketStatusAction,
  getSupportForwardPhoneAction,
  updateSupportForwardPhoneAction,
  SupportTicket,
} from "@/app/actions/supportTickets";

export default function AdminSupportTickets() {
  const [tickets, setTickets] = useState<SupportTicket[]>([]);
  const [selectedTicketId, setSelectedTicketId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [replyText, setReplyText] = useState("");
  const [sendingReply, setSendingReply] = useState(false);
  const [forwardPhone, setForwardPhone] = useState("");
  const [savingPhone, setSavingPhone] = useState(false);
  const [phoneSaved, setPhoneSaved] = useState(false);

  // Reminder Modal State
  const [showReminderModal, setShowReminderModal] = useState(false);
  const [reminderNote, setReminderNote] = useState("");
  const [reminderMinutes, setReminderMinutes] = useState(60);
  const [settingReminder, setSettingReminder] = useState(false);

  const loadData = async () => {
    try {
      const data = await fetchSupportTicketsAction();
      setTickets(data);
      if (!selectedTicketId && data.length > 0) {
        setSelectedTicketId(data[0].id);
      }
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
    getSupportForwardPhoneAction().then(setForwardPhone);
    const interval = setInterval(loadData, 5000);
    return () => clearInterval(interval);
  }, []);

  const handleSavePhone = async (e: React.FormEvent) => {
    e.preventDefault();
    setSavingPhone(true);
    const res = await updateSupportForwardPhoneAction(forwardPhone);
    setSavingPhone(false);
    if (res.success) {
      setPhoneSaved(true);
      setTimeout(() => setPhoneSaved(false), 3000);
    } else {
      alert(res.error || "שגיאה בשמירת מספר");
    }
  };

  const handleSendReply = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedTicket || !replyText.trim()) return;
    setSendingReply(true);

    const res = await replyToSupportTicketAction(selectedTicket.id, replyText);
    setSendingReply(false);
    if (res.success) {
      setReplyText("");
      await loadData();
    } else {
      alert(res.error || "שגיאה בשליחת מענה");
    }
  };

  const handleStatusChange = async (newStatus: "open" | "in_progress" | "resolved" | "closed") => {
    if (!selectedTicket) return;
    await updateSupportTicketStatusAction(selectedTicket.id, newStatus);
    await loadData();
  };

  const handleSetReminder = async () => {
    if (!selectedTicket) return;
    setSettingReminder(true);
    try {
      const dueTimestamp = Date.now() + reminderMinutes * 60 * 1000;
      await fetch("/api/admin/reminders", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          action: "create_or_update",
          reminder: {
            ticketId: selectedTicket.id,
            ticketNumber: selectedTicket.ticket_number,
            customerName: selectedTicket.customer_name,
            customerPhone: selectedTicket.customer_phone,
            reasonType: "ticket_followup",
            customReasonText: reminderNote || `טיפול בפנייה #T-${selectedTicket.ticket_number}`,
            dueTimestamp,
          },
        }),
      });
      setShowReminderModal(false);
      setReminderNote("");
      alert("התזכורת נשמרה וסונכרנה בהצלחה!");
    } catch (e) {
      console.error(e);
      alert("שגיאה בקביעת תזכורת");
    } finally {
      setSettingReminder(false);
    }
  };

  const filteredTickets = tickets.filter((t) => {
    const matchesStatus = statusFilter === "all" || t.status === statusFilter;
    const s = searchTerm.toLowerCase();
    const matchesSearch =
      !s ||
      t.customer_name.toLowerCase().includes(s) ||
      t.customer_phone.includes(s) ||
      t.ticket_number.toString().includes(s) ||
      (t.description || "").toLowerCase().includes(s);
    return matchesStatus && matchesSearch;
  });

  const selectedTicket = tickets.find((t) => t.id === selectedTicketId) || filteredTickets[0];

  const getStatusBadge = (status: string) => {
    switch (status) {
      case "open":
        return <span className="px-2.5 py-1 rounded-full text-xs font-bold bg-amber-50 text-amber-700 border border-amber-200">פתוחה</span>;
      case "in_progress":
        return <span className="px-2.5 py-1 rounded-full text-xs font-bold bg-blue-50 text-blue-700 border border-blue-200">בטיפול</span>;
      case "resolved":
        return <span className="px-2.5 py-1 rounded-full text-xs font-bold bg-emerald-50 text-emerald-700 border border-emerald-200">נפתרה</span>;
      case "closed":
        return <span className="px-2.5 py-1 rounded-full text-xs font-bold bg-gray-100 text-gray-600 border border-gray-200">סגורה</span>;
      default:
        return null;
    }
  };

  return (
    <div className="space-y-6 text-right">
      {/* Top Card: Manager Forward Phone Setting */}
      <div className="bg-white p-5 rounded-2xl border border-gray-200 shadow-sm flex flex-col md:flex-row items-center justify-between gap-4">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-emerald-50 text-emerald-600 flex items-center justify-center font-bold shrink-0">
            <Phone size={20} />
          </div>
          <div>
            <h4 className="font-bold text-gray-900 text-sm">מספר להעברת פניות בוואטסאפ (WhatsApp)</h4>
            <p className="text-xs text-gray-500">כל פנייה חדשה של לקוח בבוט תישלח ישירות כהודעת WhatsApp למספר זה</p>
          </div>
        </div>

        <form onSubmit={handleSavePhone} className="flex items-center gap-2 w-full md:w-auto">
          <input
            type="text"
            value={forwardPhone}
            onChange={(e) => setForwardPhone(e.target.value)}
            placeholder="050-0000000"
            className="px-3.5 py-2 text-sm rounded-xl border border-gray-300 focus:outline-none focus:ring-2 focus:ring-emerald-500 text-right font-mono w-44"
          />
          <button
            type="submit"
            disabled={savingPhone}
            className="px-4 py-2 bg-emerald-600 hover:bg-emerald-700 disabled:bg-gray-400 text-white text-xs font-bold rounded-xl transition-colors shrink-0 flex items-center gap-1.5 shadow-sm"
          >
            {savingPhone ? <RefreshCw size={14} className="animate-spin" /> : phoneSaved ? <Check size={14} /> : null}
            <span>{phoneSaved ? "נשמר!" : "שמור מספר"}</span>
          </button>
        </form>
      </div>

      {/* Main Grid: Tickets List & Active Chat */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 min-h-[600px]">
        {/* Left/Sidebar: Tickets List (5 cols) */}
        <div className="lg:col-span-5 bg-white rounded-2xl border border-gray-200 shadow-sm p-4 space-y-4 flex flex-col">
          {/* Search & Filter */}
          <div className="space-y-3">
            <div className="relative">
              <input
                type="text"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                placeholder="חיפוש לפי שם, טלפון, מספר פנייה..."
                className="w-full px-4 py-2.5 pl-10 text-sm rounded-xl border border-gray-200 focus:outline-none focus:ring-2 focus:ring-gray-900 text-right bg-gray-50 focus:bg-white transition-all"
              />
              <Search className="absolute left-3.5 top-3 text-gray-400" size={16} />
            </div>

            {/* Filter Pills */}
            <div className="flex gap-1.5 overflow-x-auto pb-1 text-xs">
              {[
                { id: "all", label: "הכל" },
                { id: "open", label: "פתוחות" },
                { id: "in_progress", label: "בטיפול" },
                { id: "resolved", label: "נפתרו" },
              ].map((pill) => (
                <button
                  key={pill.id}
                  onClick={() => setStatusFilter(pill.id)}
                  className={`px-3 py-1.5 rounded-lg font-medium transition-colors shrink-0 ${
                    statusFilter === pill.id
                      ? "bg-gray-900 text-white shadow-sm"
                      : "bg-gray-100 text-gray-600 hover:bg-gray-200"
                  }`}
                >
                  {pill.label}
                </button>
              ))}
            </div>
          </div>

          {/* List Items */}
          <div className="flex-1 overflow-y-auto space-y-2 pr-1 custom-scrollbar">
            {loading ? (
              <div className="p-8 text-center text-gray-400 text-sm">
                <RefreshCw size={20} className="animate-spin mx-auto mb-2" />
                טוען פניות...
              </div>
            ) : filteredTickets.length === 0 ? (
              <div className="p-8 text-center text-gray-400 text-sm">לא נמצאו פניות</div>
            ) : (
              filteredTickets.map((t) => {
                const isSelected = selectedTicket?.id === t.id;
                return (
                  <div
                    key={t.id}
                    onClick={() => setSelectedTicketId(t.id)}
                    className={`p-3.5 rounded-xl border transition-all cursor-pointer text-right space-y-2 ${
                      isSelected
                        ? "bg-emerald-50/50 border-emerald-300 shadow-sm"
                        : "bg-white border-gray-100 hover:border-gray-300 hover:bg-gray-50/60"
                    }`}
                  >
                    <div className="flex items-center justify-between">
                      <span className="font-bold text-gray-900 text-sm flex items-center gap-1.5">
                        <span className="font-mono text-emerald-800">#T-{t.ticket_number}</span>
                        <span>•</span>
                        <span>{t.customer_name}</span>
                      </span>
                      {getStatusBadge(t.status)}
                    </div>

                    <p className="text-xs text-gray-600 line-clamp-2 leading-relaxed">{t.description}</p>

                    <div className="flex items-center justify-between text-[11px] text-gray-400 pt-1 border-t border-gray-100/80">
                      <span className="font-mono text-gray-500">{t.customer_phone}</span>
                      <span>{new Date(t.created_at).toLocaleDateString("he-IL")}</span>
                    </div>
                  </div>
                );
              })
            )}
          </div>
        </div>

        {/* Right: Active Ticket Details & WhatsApp Chat (7 cols) */}
        <div className="lg:col-span-7 bg-white rounded-2xl border border-gray-200 shadow-sm p-6 flex flex-col justify-between space-y-4">
          {selectedTicket ? (
            <>
              {/* Ticket Header & Actions */}
              <div className="border-b border-gray-100 pb-4 space-y-3">
                <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
                  <div>
                    <div className="flex items-center gap-2">
                      <h3 className="text-xl font-bold text-gray-900 font-serif">
                        פנייה #T-{selectedTicket.ticket_number}
                      </h3>
                      {getStatusBadge(selectedTicket.status)}
                    </div>
                    <div className="flex items-center gap-3 text-xs text-gray-500 mt-1 font-mono">
                      <span>{selectedTicket.customer_name}</span>
                      <span>•</span>
                      <span>{selectedTicket.customer_phone}</span>
                      <span>•</span>
                      <span>{new Date(selectedTicket.created_at).toLocaleString("he-IL")}</span>
                    </div>
                  </div>

                  {/* Actions & Call */}
                  <div className="flex items-center gap-2">
                    <button
                      onClick={() => setShowReminderModal(true)}
                      className="p-2 rounded-xl border border-gray-200 hover:bg-gray-100 text-gray-700 transition-colors"
                      title="קבע תזכורת לפנייה"
                    >
                      <Bell size={16} />
                    </button>
                    <a
                      href={`https://wa.me/${selectedTicket.customer_phone.replace(/\D/g, "")}`}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="p-2 rounded-xl border border-emerald-200 bg-emerald-50 text-emerald-700 hover:bg-emerald-100 transition-colors"
                      title="פתח שיחה אישית בוואטסאפ"
                    >
                      <MessageSquare size={16} />
                    </a>
                    <a
                      href={`tel:${selectedTicket.customer_phone}`}
                      className="p-2 rounded-xl border border-blue-200 bg-blue-50 text-blue-700 hover:bg-blue-100 transition-colors"
                      title="חייג ללקוח"
                    >
                      <Phone size={16} />
                    </a>
                  </div>
                </div>

                {/* Status Switcher Buttons */}
                <div className="flex items-center gap-2 pt-1 text-xs">
                  <span className="text-gray-400 text-xs">שנה סטטוס:</span>
                  <button
                    onClick={() => handleStatusChange("open")}
                    className={`px-2.5 py-1 rounded-lg border transition-colors ${
                      selectedTicket.status === "open"
                        ? "bg-amber-100 border-amber-300 text-amber-800 font-bold"
                        : "hover:bg-gray-100 text-gray-600 border-gray-200"
                    }`}
                  >
                    פתוח
                  </button>
                  <button
                    onClick={() => handleStatusChange("in_progress")}
                    className={`px-2.5 py-1 rounded-lg border transition-colors ${
                      selectedTicket.status === "in_progress"
                        ? "bg-blue-100 border-blue-300 text-blue-800 font-bold"
                        : "hover:bg-gray-100 text-gray-600 border-gray-200"
                    }`}
                  >
                    בטיפול
                  </button>
                  <button
                    onClick={() => handleStatusChange("resolved")}
                    className={`px-2.5 py-1 rounded-lg border transition-colors ${
                      selectedTicket.status === "resolved"
                        ? "bg-emerald-100 border-emerald-300 text-emerald-800 font-bold"
                        : "hover:bg-gray-100 text-gray-600 border-gray-200"
                    }`}
                  >
                    נפתר
                  </button>
                  <button
                    onClick={() => handleStatusChange("closed")}
                    className={`px-2.5 py-1 rounded-lg border transition-colors ${
                      selectedTicket.status === "closed"
                        ? "bg-gray-200 border-gray-300 text-gray-800 font-bold"
                        : "hover:bg-gray-100 text-gray-600 border-gray-200"
                    }`}
                  >
                    סגור
                  </button>
                </div>
              </div>

              {/* Chat Message History */}
              <div className="flex-1 overflow-y-auto space-y-3 p-3 bg-gray-50/60 rounded-2xl border border-gray-100 min-h-[300px] max-h-[420px] custom-scrollbar">
                {selectedTicket.messages && selectedTicket.messages.length > 0 ? (
                  selectedTicket.messages.map((m, idx) => {
                    const isAdmin = m.sender_type === "admin";
                    return (
                      <div
                        key={m.id || idx}
                        className={`flex flex-col ${isAdmin ? "items-end" : "items-start"}`}
                      >
                        <div
                          className={`max-w-[85%] p-3.5 rounded-2xl text-sm leading-relaxed ${
                            isAdmin
                              ? "bg-emerald-600 text-white rounded-br-none shadow-sm"
                              : "bg-white text-gray-800 border border-gray-200 rounded-bl-none shadow-sm"
                          }`}
                        >
                          <div className="text-[11px] opacity-75 font-semibold mb-1">
                            {isAdmin ? "מנהל מערכת" : selectedTicket.customer_name}
                          </div>
                          <div className="whitespace-pre-wrap">{m.message_text}</div>
                        </div>
                        <span className="text-[10px] text-gray-400 mt-1 px-1">
                          {new Date(m.created_at).toLocaleTimeString("he-IL", { hour: "2-digit", minute: "2-digit" })}
                        </span>
                      </div>
                    );
                  })
                ) : (
                  <div className="p-4 text-center text-gray-400 text-xs">{selectedTicket.description}</div>
                )}
              </div>

              {/* Direct WhatsApp Reply Form */}
              <form onSubmit={handleSendReply} className="space-y-2 pt-2">
                <div className="flex items-center gap-2">
                  <input
                    type="text"
                    value={replyText}
                    onChange={(e) => setReplyText(e.target.value)}
                    placeholder="הקלד מענה שיישלח ישירות לוואטסאפ של הלקוח..."
                    className="flex-1 px-4 py-3 text-sm rounded-xl border border-gray-300 focus:outline-none focus:ring-2 focus:ring-emerald-500 text-right bg-white"
                  />
                  <button
                    type="submit"
                    disabled={sendingReply || !replyText.trim()}
                    className="px-5 py-3 bg-emerald-600 hover:bg-emerald-700 disabled:bg-gray-300 text-white text-sm font-bold rounded-xl transition-all flex items-center gap-2 shadow-sm shrink-0"
                  >
                    {sendingReply ? <RefreshCw size={16} className="animate-spin" /> : <Send size={16} />}
                    <span>השב בוואטסאפ</span>
                  </button>
                </div>
                <p className="text-[11px] text-gray-400 text-right">
                  התשובה תועבר מיידית ל-WhatsApp של הלקוח יחד עם משפט ההנצחה והקישור לאתר מורנצ׳לו.
                </p>
              </form>
            </>
          ) : (
            <div className="flex-1 flex flex-col items-center justify-center text-gray-400 text-sm">
              <MessageSquare size={36} className="mb-2 opacity-50" />
              בחר פנייה מהרשימה לצפייה ומענה
            </div>
          )}
        </div>
      </div>

      {/* Reminder Modal */}
      {showReminderModal && selectedTicket && (
        <div className="fixed inset-0 z-50 bg-black/40 backdrop-blur-xs flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl p-6 max-w-sm w-full space-y-4 shadow-xl text-right animate-in fade-in duration-200 border border-gray-100">
            <h4 className="text-lg font-bold text-gray-900 font-serif">
              קבע תזכורת לפנייה #T-{selectedTicket.ticket_number}
            </h4>

            <div>
              <label className="text-xs text-gray-500 block mb-1">הערת תזכורת:</label>
              <input
                type="text"
                value={reminderNote}
                onChange={(e) => setReminderNote(e.target.value)}
                placeholder="למשל: לחזור ללקוח לוודא שקיבל..."
                className="w-full px-3.5 py-2 text-sm rounded-xl border border-gray-300 focus:ring-2 focus:ring-gray-900 outline-none text-right"
              />
            </div>

            <div>
              <label className="text-xs text-gray-500 block mb-1">התראה בעוד:</label>
              <div className="grid grid-cols-3 gap-2 text-xs">
                {[
                  { label: "שעה", mins: 60 },
                  { label: "3 שעות", mins: 180 },
                  { label: "מחר", mins: 1440 },
                ].map((opt) => (
                  <button
                    key={opt.mins}
                    type="button"
                    onClick={() => setReminderMinutes(opt.mins)}
                    className={`py-2 rounded-xl border font-bold transition-all ${
                      reminderMinutes === opt.mins
                        ? "bg-gray-900 text-white border-gray-900"
                        : "bg-gray-50 text-gray-700 border-gray-200 hover:bg-gray-100"
                    }`}
                  >
                    {opt.label}
                  </button>
                ))}
              </div>
            </div>

            <div className="flex gap-2 pt-2">
              <button
                type="button"
                onClick={handleSetReminder}
                disabled={settingReminder}
                className="flex-1 py-2.5 bg-gray-900 hover:bg-black text-white text-xs font-bold rounded-xl transition-colors"
              >
                {settingReminder ? "שומר..." : "שמור תזכורת"}
              </button>
              <button
                type="button"
                onClick={() => setShowReminderModal(false)}
                className="px-4 py-2.5 bg-gray-100 hover:bg-gray-200 text-gray-700 text-xs font-bold rounded-xl transition-colors"
              >
                ביטול
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

