import { NextResponse } from "next/server";
import { createClient } from "@supabase/supabase-js";
import { decrypt, encrypt } from "@/lib/encryption";
import { CLOSING_MOTTO } from "@/app/actions/supportTickets";

export const dynamic = "force-dynamic";
export const revalidate = 0;

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL || "";
const supabaseServiceKey = process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY || "";
const supabaseAdmin = createClient(supabaseUrl, supabaseServiceKey);

const SETTINGS_STORE_KEY = "support_tickets_store";

async function verifyAdminAuth(req: Request): Promise<boolean> {
  try {
    const { checkSession } = await import("@/app/actions/adminAuth");
    if (await checkSession()) return true;
  } catch (e) {}

  const authHeader = req.headers.get("Authorization") || req.headers.get("x-admin-key") || "";
  const token = authHeader.replace(/^Bearer\s+/i, "").trim();

  const validKeys = [
    process.env.ADMIN_API_KEY,
    process.env.SUPABASE_SERVICE_ROLE_KEY,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY,
  ].filter(Boolean);

  return Boolean(token && validKeys.includes(token));
}

async function getTicketsFromStore(): Promise<any[]> {
  try {
    const { data, error } = await supabaseAdmin
      .from("support_tickets")
      .select("*, ticket_messages(*)")
      .order("created_at", { ascending: false });

    if (!error && data) {
      return data.map((t: any) => ({
        id: t.id,
        ticket_number: t.ticket_number,
        customer_phone: decrypt(t.customer_phone) || t.customer_phone,
        customer_name: decrypt(t.customer_name) || t.customer_name,
        subject: t.subject,
        description: t.description,
        status: t.status,
        priority: t.priority,
        related_order_id: t.related_order_id,
        messages: (t.ticket_messages || []).sort(
          (a: any, b: any) => new Date(a.created_at).getTime() - new Date(b.created_at).getTime()
        ),
        created_at: t.created_at,
        updated_at: t.updated_at,
      }));
    }
  } catch (e) {}

  try {
    const { data } = await supabaseAdmin
      .from("settings")
      .select("value")
      .eq("id", SETTINGS_STORE_KEY)
      .maybeSingle();

    if (!data?.value) return [];
    return JSON.parse(data.value);
  } catch (e) {
    console.error("Error reading support tickets store in API:", e);
    return [];
  }
}

async function saveTicketsToStore(tickets: any[]): Promise<boolean> {
  try {
    const { error } = await supabaseAdmin
      .from("settings")
      .upsert({ id: SETTINGS_STORE_KEY, value: JSON.stringify(tickets), updated_at: new Date().toISOString() });
    return !error;
  } catch (e) {
    console.error("Error saving support tickets store:", e);
    return false;
  }
}

export async function GET(req: Request) {
  if (!(await verifyAdminAuth(req))) {
    return NextResponse.json({ success: false, error: "Unauthorized" }, { status: 401 });
  }

  try {
    const tickets = await getTicketsFromStore();
    return NextResponse.json({ success: true, tickets });
  } catch (err: any) {
    return NextResponse.json({ success: false, error: err.message }, { status: 500 });
  }
}

export async function POST(req: Request) {
  if (!(await verifyAdminAuth(req))) {
    return NextResponse.json({ success: false, error: "Unauthorized" }, { status: 401 });
  }

  try {
    const body = await req.json();
    const { action } = body;

    if (action === "reply") {
      const { ticketId, replyText } = body;
      if (!ticketId || !replyText?.trim()) {
        return NextResponse.json({ success: false, error: "Missing ticketId or replyText" }, { status: 400 });
      }

      const allTickets = await getTicketsFromStore();
      const ticket = allTickets.find((t) => t.id === ticketId || String(t.ticket_number) === String(ticketId));
      if (!ticket) {
        return NextResponse.json({ success: false, error: "Ticket not found" }, { status: 404 });
      }

      const nowIso = new Date().toISOString();
      const adminMsg = {
        id: `msg_${Date.now()}`,
        sender_type: "admin",
        message_text: replyText.trim(),
        created_at: nowIso,
      };

      try {
        await supabaseAdmin.from("ticket_messages").insert({
          ticket_id: ticket.id,
          sender_type: "admin",
          message_text: replyText.trim(),
        });
        await supabaseAdmin
          .from("support_tickets")
          .update({ status: "in_progress", updated_at: nowIso })
          .eq("id", ticket.id);
      } catch (e) {}

      if (!ticket.messages) ticket.messages = [];
      ticket.messages.push(adminMsg);
      ticket.status = "in_progress";
      ticket.updated_at = nowIso;
      await saveTicketsToStore(allTickets);

      // Send WhatsApp message to customer
      try {
        const { sendWhatsAppMessageDirect } = await import("@/lib/whatsappBot");
        const waText = `שלום ${ticket.customer_name} 🍋,\nמענה מפניות מורנצ׳לו (פנייה #T-${ticket.ticket_number}):\n\n"${replyText.trim()}"\n\n${CLOSING_MOTTO}`;
        await sendWhatsAppMessageDirect(ticket.customer_phone, waText);
      } catch (err) {
        console.error("Error sending WhatsApp reply:", err);
      }

      return NextResponse.json({ success: true, ticket });
    }

    if (action === "update_status") {
      const { ticketId, status } = body;
      const allTickets = await getTicketsFromStore();
      const ticket = allTickets.find((t) => t.id === ticketId || String(t.ticket_number) === String(ticketId));
      if (!ticket) {
        return NextResponse.json({ success: false, error: "Ticket not found" }, { status: 404 });
      }

      const nowIso = new Date().toISOString();
      ticket.status = status;
      ticket.updated_at = nowIso;

      try {
        await supabaseAdmin
          .from("support_tickets")
          .update({ status, updated_at: nowIso })
          .eq("id", ticket.id);
      } catch (e) {}

      await saveTicketsToStore(allTickets);
      return NextResponse.json({ success: true, ticket });
    }

    return NextResponse.json({ success: false, error: "Unknown action" }, { status: 400 });
  } catch (err: any) {
    return NextResponse.json({ success: false, error: err.message }, { status: 500 });
  }
}

