export function syncAlarmsForReminders(reminders: OrderReminder[]): void {
  const now = Date.now();
  for (const rem of reminders) {
    if (rem.isCompleted) {
      cancelAndDismissNotification(rem.id).catch(() => {});
      if (Platform.OS === 'android' && ReminderAlarmModule?.cancelAlarm) {
        ReminderAlarmModule.cancelAlarm(rem.id).catch(() => {});
      }
      continue;
    }
    const title = rem.ticketNumber
      ? `תזכורת לפנייה #T-${rem.ticketNumber}`
      : `תזכורת להזמנה #${rem.orderNumber || ''}`;
    const body = `${rem.customerName ? rem.customerName + ': ' : ''}${getReasonLabel(rem.reasonType, rem.customReasonText)}`;
    const secondsFromNow = Math.max(1, Math.round((rem.dueTimestamp - now) / 1000));

    scheduleLocalNotification(title, body, secondsFromNow, undefined, rem.id);

    if (Platform.OS === 'android' && ReminderAlarmModule?.scheduleExactAlarm) {
      ReminderAlarmModule.scheduleExactAlarm(rem.id, title, body, rem.dueTimestamp).catch(() => {});
    }
  }
}

