export function isSameOrder(reminder: OrderReminder, orderId: string, orderNumber?: string | number): boolean {
  const cleanId = orderId && orderId !== 'undefined' && orderId !== 'null' && orderId !== '' ? String(orderId) : null;
  const remId = reminder.orderId && reminder.orderId !== 'undefined' && reminder.orderId !== 'null' && reminder.orderId !== '' ? String(reminder.orderId) : null;

  if (cleanId && remId && cleanId === remId) {
    return true;
  }

  const cleanNum = orderNumber !== undefined && orderNumber !== null && String(orderNumber) !== 'undefined' && String(orderNumber) !== 'null' && String(orderNumber) !== '' ? String(orderNumber) : null;
  const remNum = reminder.orderNumber !== undefined && reminder.orderNumber !== null && String(reminder.orderNumber) !== 'undefined' && String(reminder.orderNumber) !== 'null' && String(reminder.orderNumber) !== '' ? String(reminder.orderNumber) : null;

  if (cleanNum && remNum && cleanNum === remNum) {
    return true;
  }

  return false;
}

export async function createOrderReminder(data: {
  orderId: string;
  orderNumber?: number | string;
  customerName?: string;
  customerPhone?: string;
  reasonType: QuickReminderReason;
  customReasonText?: string;
  dueTimestamp: number;
}): Promise<OrderReminder> {
  const all = await loadAllReminders();

  // Cancel any existing uncompleted reminder for this specific order
  const existingForOrder = all.filter((r) => !r.isCompleted && isSameOrder(r, data.orderId, data.orderNumber));
  for (const rem of existingForOrder) {
    if (Platform.OS === 'android' && ReminderAlarmModule?.cancelAlarm) {
      ReminderAlarmModule.cancelAlarm(rem.id).catch(() => {});
    }
  }

  const newReminder: OrderReminder = {
    id: `rem_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`,
    orderId: String(data.orderId),
    orderNumber: data.orderNumber,
    customerName: data.customerName,
    customerPhone: data.customerPhone,
    reasonType: data.reasonType,
    customReasonText: data.customReasonText,
    dueTimestamp: data.dueTimestamp,
    createdAt: Date.now(),
    isCompleted: false,
  };

  // Filter out any previous uncompleted reminder for this order, then add new
  const filtered = all.filter((r) => !(!r.isCompleted && isSameOrder(r, data.orderId, data.orderNumber)));
  const updated = [newReminder, ...filtered];
  await saveAllReminders(updated);

  // Schedule local push notification
  const title = `תזכורת להזמנה #${data.orderNumber || ''}`;
  const body = `${data.customerName ? data.customerName + ': ' : ''}${getReasonLabel(data.reasonType, data.customReasonText)}`;

  const secondsFromNow = Math.max(1, Math.round((data.dueTimestamp - Date.now()) / 1000));
  scheduleLocalNotification(title, body, secondsFromNow);

  // Schedule native exact wake alarm
  if (Platform.OS === 'android' && ReminderAlarmModule?.scheduleExactAlarm) {
    ReminderAlarmModule.scheduleExactAlarm(newReminder.id, title, body, data.dueTimestamp).catch(() => {});
  }

  logInfo('REMINDERS', `Created reminder for order #${data.orderNumber}`, newReminder);
  return newReminder;
}

