import { loadAppSettings } from './storage';
import { logInfo, logWarn, logError } from './logger';
import { DEFAULT_SETTINGS } from '../config/constants';
import { createOrderReminder } from './reminders';

export interface TicketMessage {
  id: string;
  sender_type: 'customer' | 'admin' | 'bot';
  message_text: string;
  created_at: string;
}

export interface SupportTicket {
  id: string;
  ticket_number: number;
  customer_phone: string;
  customer_name: string;
  subject?: string;
  description: string;
  status: 'open' | 'in_progress' | 'resolved' | 'closed';
  priority: 'low' | 'normal' | 'urgent';
  related_order_id?: string;
  messages: TicketMessage[];
  created_at: string;
  updated_at: string;
}

function getApiHeaders(settings: any) {
  const token = settings.supabaseAnonKey || DEFAULT_SETTINGS.supabaseAnonKey;
  return {
    Authorization: `Bearer ${token}`,
    'Content-Type': 'application/json',
  };
}

export async function fetchSupportTickets(): Promise<SupportTicket[]> {
  try {
    const settings = await loadAppSettings();
    const serverUrl = settings.serverUrl || 'https://www.morancello.com';
    const apiUrl = `${serverUrl.replace(/\/$/, '')}/api/admin/tickets`;

    const res = await fetch(apiUrl, {
      method: 'GET',
      headers: getApiHeaders(settings),
    });

    if (res.ok) {
      const data = await res.json();
      if (data.success && Array.isArray(data.tickets)) {
        return data.tickets;
      }
    }
  } catch (e: any) {
    logError('SUPPORT_TICKETS', 'Failed to fetch support tickets', e);
  }
  return [];
}

export async function replyToSupportTicket(
  ticketId: string,
  replyText: string
): Promise<{ success: boolean; error?: string }> {
  try {
    const settings = await loadAppSettings();
    const serverUrl = settings.serverUrl || 'https://www.morancello.com';
    const apiUrl = `${serverUrl.replace(/\/$/, '')}/api/admin/tickets`;

    const res = await fetch(apiUrl, {
      method: 'POST',
      headers: getApiHeaders(settings),
      body: JSON.stringify({
        action: 'reply',
        ticketId,
        replyText,
      }),
    });

    const data = await res.json();
    return data;
  } catch (e: any) {
    logError('SUPPORT_TICKETS', 'Failed to reply to ticket', e);
    return { success: false, error: e?.message || 'שגיאה בשליחת מענה' };
  }
}

export async function updateSupportTicketStatus(
  ticketId: string,
  status: 'open' | 'in_progress' | 'resolved' | 'closed'
): Promise<{ success: boolean; error?: string }> {
  try {
    const settings = await loadAppSettings();
    const serverUrl = settings.serverUrl || 'https://www.morancello.com';
    const apiUrl = `${serverUrl.replace(/\/$/, '')}/api/admin/tickets`;

    const res = await fetch(apiUrl, {
      method: 'POST',
      headers: getApiHeaders(settings),
      body: JSON.stringify({
        action: 'update_status',
        ticketId,
        status,
      }),
    });

    const data = await res.json();
    return data;
  } catch (e: any) {
    logError('SUPPORT_TICKETS', 'Failed to update ticket status', e);
    return { success: false, error: e?.message || 'שגיאה בעדכון סטטוס' };
  }
}

export async function createTicketReminder(data: {
  ticketId: string;
  ticketNumber: number | string;
  customerName?: string;
  customerPhone?: string;
  dueTimestamp: number;
  customReasonText?: string;
}) {
  return await createOrderReminder({
    ticketId: data.ticketId,
    ticketNumber: data.ticketNumber,
    targetType: 'ticket',
    customerName: data.customerName,
    customerPhone: data.customerPhone,
    reasonType: 'ticket_followup',
    customReasonText: data.customReasonText || `מענה לפנייה #T-${data.ticketNumber}`,
    dueTimestamp: data.dueTimestamp,
  });
}

