import React, { useState, useEffect } from 'react';
import {
  View,
  Text,
  StyleSheet,
  TextInput,
  FlatList,
  RefreshControl,
  TouchableOpacity,
  Alert,
  Modal,
  ScrollView,
  Linking,
  KeyboardAvoidingView,
  Platform,
} from 'react-native';
import { Ionicons, FontAwesome5 } from '@expo/vector-icons';
import {
  SupportTicket,
  fetchSupportTickets,
  replyToSupportTicket,
  updateSupportTicketStatus,
  createTicketReminder,
} from '../services/supportTickets';
import { openWhatsAppDirectChat } from '../services/whatsapp';
import { OrderReminder } from '../types/reminder';

interface SupportTicketsScreenProps {
  remindersMap?: Record<string, OrderReminder>;
  refreshTrigger?: number;
}

export const SupportTicketsScreen: React.FC<SupportTicketsScreenProps> = ({
  remindersMap = {},
  refreshTrigger,
}) => {
  const [tickets, setTickets] = useState<SupportTicket[]>([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedStatusFilter, setSelectedStatusFilter] = useState<'all' | 'open' | 'in_progress' | 'resolved'>('all');
  const [refreshing, setRefreshing] = useState(false);
  const [selectedTicket, setSelectedTicket] = useState<SupportTicket | null>(null);
  const [replyText, setReplyText] = useState('');
  const [sendingReply, setSendingReply] = useState(false);

  const loadTicketsData = async () => {
    setRefreshing(true);
    const data = await fetchSupportTickets();
    setTickets(data);
    setRefreshing(false);
  };

  useEffect(() => {
    loadTicketsData();
  }, [refreshTrigger]);

  const filteredTickets = tickets.filter((t) => {
    if (selectedStatusFilter !== 'all' && t.status !== selectedStatusFilter) {
      return false;
    }
    if (!searchQuery.trim()) return true;

    const query = searchQuery.toLowerCase();
    const phone = (t.customer_phone || '').toLowerCase();
    const name = (t.customer_name || '').toLowerCase();
    const num = String(t.ticket_number || '');
    const desc = (t.description || '').toLowerCase();

    return (
      phone.includes(query) ||
      name.includes(query) ||
      num.includes(query) ||
      desc.includes(query)
    );
  });

  const handleCall = (phone: string) => {
    if (!phone) return;
    const clean = phone.replace(/[^0-9+]/g, '');
    Linking.openURL(`tel:${clean}`).catch(() => {
      Alert.alert('שגיאה', 'לא ניתן לבצע שיחה ממכשיר זה');
    });
  };

  const handleWhatsAppChat = (phone: string, name: string, num: number) => {
    if (!phone) return;
    openWhatsAppDirectChat(phone, `שלום ${name || ''}, לגבי פנייתך #T-${num}:`);
  };

  const handleSendReply = async () => {
    if (!selectedTicket || !replyText.trim()) return;

    setSendingReply(true);
    const res = await replyToSupportTicket(selectedTicket.id, replyText.trim());
    setSendingReply(false);

    if (res.success) {
      Alert.alert('מענה נשלח בהצלחה 🍋', 'ההודעה נשלחה ישירות לוואטסאפ של הלקוח');
      setReplyText('');
      await loadTicketsData();
      // Update selected ticket in view
      const updated = tickets.find((t) => t.id === selectedTicket.id);
      if (updated) setSelectedTicket(updated);
      else setSelectedTicket(null);
    } else {
      Alert.alert('שגיאה בשליחת מענה', res.error || 'נסה שוב');
    }
  };

  const handleStatusChange = async (ticket: SupportTicket, newStatus: 'open' | 'in_progress' | 'resolved' | 'closed') => {
    const res = await updateSupportTicketStatus(ticket.id, newStatus);
    if (res.success) {
      await loadTicketsData();
      if (selectedTicket?.id === ticket.id) {
        setSelectedTicket({ ...selectedTicket, status: newStatus });
      }
    } else {
      Alert.alert('שגיאה', res.error || 'לא ניתן לעדכן סטטוס');
    }
  };

  const handleSetReminder = async (ticket: SupportTicket) => {
    Alert.alert(
      'קביעת תזכורת למענה 🔔',
      `קבע תזכורת לפנייה #T-${ticket.ticket_number}`,
      [
        { text: 'ביטול', style: 'cancel' },
        {
          text: 'בעוד שעה (1 שעה)',
          onPress: async () => {
            await createTicketReminder({
              ticketId: ticket.id,
              ticketNumber: ticket.ticket_number,
              customerName: ticket.customer_name,
              customerPhone: ticket.customer_phone,
              dueTimestamp: Date.now() + 3600 * 1000,
            });
            Alert.alert('תזכורת נקבעה בהצלחה ⏰', 'האפליקציה תזכיר לך בעוד שעה');
          },
        },
        {
          text: 'מחר בבוקר (24 שעות)',
          onPress: async () => {
            await createTicketReminder({
              ticketId: ticket.id,
              ticketNumber: ticket.ticket_number,
              customerName: ticket.customer_name,
              customerPhone: ticket.customer_phone,
              dueTimestamp: Date.now() + 24 * 3600 * 1000,
            });
            Alert.alert('תזכורת נקבעה בהצלחה ⏰', 'האפליקציה תזכיר לך מחר');
          },
        },
      ]
    );
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'open':
        return { label: 'חדש / ממתין', bg: '#FEF3C7', color: '#B45309' };
      case 'in_progress':
        return { label: 'בטיפול', bg: '#DBEAFE', color: '#1D4ED8' };
      case 'resolved':
        return { label: 'נפתר', bg: '#D1FAE5', color: '#047857' };
      case 'closed':
        return { label: 'סגור', bg: '#F3F4F6', color: '#4B5563' };
      default:
        return { label: status, bg: '#F3F4F6', color: '#4B5563' };
    }
  };

  return (
    <View style={styles.container}>
      {/* Search Header */}
      <View style={styles.searchContainer}>
        <View style={styles.searchBar}>
          <Ionicons name="search" size={20} color="#9CA3AF" />
          <TextInput
            style={styles.searchInput}
            placeholder="חיפוש לפי שם, טלפון, מספר פנייה..."
            placeholderTextColor="#9CA3AF"
            value={searchQuery}
            onChangeText={setSearchQuery}
            textAlign="right"
          />
          {searchQuery.length > 0 && (
            <TouchableOpacity onPress={() => setSearchQuery('')}>
              <Ionicons name="close-circle" size={18} color="#9CA3AF" />
            </TouchableOpacity>
          )}
        </View>
      </View>

      {/* Filter Tabs */}
      <View style={styles.filterRow}>
        {(
          [
            { id: 'all', label: 'הכל' },
            { id: 'open', label: 'ממתינים' },
            { id: 'in_progress', label: 'בטיפול' },
            { id: 'resolved', label: 'נפתרו' },
          ] as const
        ).map((tab) => (
          <TouchableOpacity
            key={tab.id}
            style={[
              styles.filterTab,
              selectedStatusFilter === tab.id && styles.filterTabActive,
            ]}
            onPress={() => setSelectedStatusFilter(tab.id)}
          >
            <Text
              style={[
                styles.filterTabText,
                selectedStatusFilter === tab.id && styles.filterTabTextActive,
              ]}
            >
              {tab.label}
            </Text>
          </TouchableOpacity>
        ))}
      </View>

      {/* Tickets List */}
      <FlatList
        data={filteredTickets}
        keyExtractor={(item) => item.id}
        refreshControl={
          <RefreshControl refreshing={refreshing} onRefresh={loadTicketsData} colors={['#D97706']} />
        }
        contentContainerStyle={styles.listContent}
        ListEmptyComponent={
          <View style={styles.emptyContainer}>
            <Ionicons name="chatbubbles-outline" size={48} color="#D1D5DB" />
            <Text style={styles.emptyText}>לא נמצאו פניות שירות</Text>
          </View>
        }
        renderItem={({ item }) => {
          const badge = getStatusBadge(item.status);
          const hasReminder = Boolean(
            remindersMap[`ticket_${item.id}`] || remindersMap[`ticket_num_${item.ticket_number}`]
          );

          return (
            <TouchableOpacity
              style={styles.ticketCard}
              activeOpacity={0.9}
              onPress={() => setSelectedTicket(item)}
            >
              <View style={styles.cardHeader}>
                <View style={[styles.statusBadge, { backgroundColor: badge.bg }]}>
                  <Text style={[styles.statusBadgeText, { color: badge.color }]}>{badge.label}</Text>
                </View>
                <View style={styles.cardTitleGroup}>
                  <Text style={styles.ticketNumText}>#T-{item.ticket_number}</Text>
                  {hasReminder && (
                    <Ionicons name="alarm" size={16} color="#D97706" style={{ marginRight: 4 }} />
                  )}
                </View>
              </View>

              <View style={styles.customerRow}>
                <Text style={styles.customerName}>{item.customer_name || 'לקוח וואטסאפ'}</Text>
                <Text style={styles.customerPhone}>{item.customer_phone}</Text>
              </View>

              <Text style={styles.ticketDesc} numberOfLines={2}>
                {item.description}
              </Text>

              <View style={styles.cardFooter}>
                <Text style={styles.dateText}>
                  {new Date(item.created_at).toLocaleDateString('he-IL', {
                    day: 'numeric',
                    month: 'numeric',
                    hour: '2-digit',
                    minute: '2-digit',
                  })}
                </Text>

                <View style={styles.cardActions}>
                  <TouchableOpacity
                    style={styles.iconActionBtn}
                    onPress={() => handleCall(item.customer_phone)}
                  >
                    <Ionicons name="call" size={14} color="#059669" />
                  </TouchableOpacity>

                  <TouchableOpacity
                    style={styles.iconActionBtn}
                    onPress={() => handleWhatsAppChat(item.customer_phone, item.customer_name, item.ticket_number)}
                  >
                    <FontAwesome5 name="whatsapp" size={14} color="#25D366" />
                  </TouchableOpacity>

                  <TouchableOpacity
                    style={styles.iconActionBtn}
                    onPress={() => handleSetReminder(item)}
                  >
                    <Ionicons name="notifications-outline" size={15} color="#D97706" />
                  </TouchableOpacity>

                  <TouchableOpacity
                    style={styles.replyButton}
                    onPress={() => setSelectedTicket(item)}
                  >
                    <Ionicons name="arrow-back" size={14} color="#FFFFFF" />
                    <Text style={styles.replyButtonText}>היסטוריה ומענה</Text>
                  </TouchableOpacity>
                </View>
              </View>
            </TouchableOpacity>
          );
        }}
      />

      {/* Ticket Chat & Reply Modal */}
      {selectedTicket && (
        <Modal
          visible={true}
          animationType="slide"
          onRequestClose={() => setSelectedTicket(null)}
        >
          <KeyboardAvoidingView
            style={styles.modalContainer}
            behavior={Platform.OS === 'ios' ? 'padding' : undefined}
          >
            {/* Modal Header */}
            <View style={styles.modalHeader}>
              <TouchableOpacity
                style={styles.closeBtn}
                onPress={() => setSelectedTicket(null)}
              >
                <Ionicons name="close" size={24} color="#374151" />
              </TouchableOpacity>

              <View style={styles.modalHeaderTitleGroup}>
                <Text style={styles.modalHeaderTitle}>
                  פנייה #T-{selectedTicket.ticket_number}
                </Text>
                <Text style={styles.modalHeaderSub}>
                  {selectedTicket.customer_name} ({selectedTicket.customer_phone})
                </Text>
              </View>

              <TouchableOpacity
                style={styles.headerReminderBtn}
                onPress={() => handleSetReminder(selectedTicket)}
              >
                <Ionicons name="alarm-outline" size={22} color="#D97706" />
              </TouchableOpacity>
            </View>

            {/* Quick Status Bar */}
            <View style={styles.statusBarRow}>
              <Text style={styles.statusLabel}>סטטוס פנייה:</Text>
              <View style={styles.statusBtnsGroup}>
                <TouchableOpacity
                  style={[
                    styles.statusOptionBtn,
                    selectedTicket.status === 'open' && styles.statusOptionBtnActive,
                  ]}
                  onPress={() => handleStatusChange(selectedTicket, 'open')}
                >
                  <Text
                    style={[
                      styles.statusOptionText,
                      selectedTicket.status === 'open' && styles.statusOptionTextActive,
                    ]}
                  >
                    ממתין
                  </Text>
                </TouchableOpacity>

                <TouchableOpacity
                  style={[
                    styles.statusOptionBtn,
                    selectedTicket.status === 'in_progress' && styles.statusOptionBtnActive,
                  ]}
                  onPress={() => handleStatusChange(selectedTicket, 'in_progress')}
                >
                  <Text
                    style={[
                      styles.statusOptionText,
                      selectedTicket.status === 'in_progress' && styles.statusOptionTextActive,
                    ]}
                  >
                    בטיפול
                  </Text>
                </TouchableOpacity>

                <TouchableOpacity
                  style={[
                    styles.statusOptionBtn,
                    selectedTicket.status === 'resolved' && styles.statusOptionBtnActiveResolved,
                  ]}
                  onPress={() => handleStatusChange(selectedTicket, 'resolved')}
                >
                  <Text
                    style={[
                      styles.statusOptionText,
                      selectedTicket.status === 'resolved' && styles.statusOptionTextActive,
                    ]}
                  >
                    נפתר ✨
                  </Text>
                </TouchableOpacity>
              </View>
            </View>

            {/* Chat Thread */}
            <ScrollView style={styles.chatScroll} contentContainerStyle={styles.chatContent}>
              {(selectedTicket.messages || []).map((msg, idx) => {
                const isAdmin = msg.sender_type === 'admin';
                return (
                  <View
                    key={msg.id || idx}
                    style={[
                      styles.messageBubble,
                      isAdmin ? styles.messageAdmin : styles.messageCustomer,
                    ]}
                  >
                    <View style={styles.messageHeader}>
                      <Text style={styles.messageSender}>
                        {isAdmin ? 'נציג מורנצ׳לו 🍋' : selectedTicket.customer_name}
                      </Text>
                      <Text style={styles.messageTime}>
                        {new Date(msg.created_at).toLocaleTimeString('he-IL', {
                          hour: '2-digit',
                          minute: '2-digit',
                        })}
                      </Text>
                    </View>
                    <Text style={isAdmin ? styles.messageTextAdmin : styles.messageTextCustomer}>
                      {msg.message_text}
                    </Text>
                  </View>
                );
              })}
            </ScrollView>

            {/* Reply Input Bar */}
            <View style={styles.replyBar}>
              <TouchableOpacity
                style={[
                  styles.sendReplyBtn,
                  (!replyText.trim() || sendingReply) && styles.sendReplyBtnDisabled,
                ]}
                disabled={!replyText.trim() || sendingReply}
                onPress={handleSendReply}
              >
                <FontAwesome5 name="whatsapp" size={16} color="#FFFFFF" />
                <Text style={styles.sendReplyBtnText}>
                  {sendingReply ? 'שולח...' : 'השב בוואטסאפ'}
                </Text>
              </TouchableOpacity>

              <TextInput
                style={styles.replyInput}
                placeholder="הקלד תשובה שתישלח ישירות בוואטסאפ..."
                placeholderTextColor="#9CA3AF"
                value={replyText}
                onChangeText={setReplyText}
                multiline
                textAlign="right"
              />
            </View>
          </KeyboardAvoidingView>
        </Modal>
      )}
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#F9FAFB',
  },
  searchContainer: {
    paddingHorizontal: 16,
    paddingTop: 12,
    paddingBottom: 8,
    backgroundColor: '#FFFFFF',
  },
  searchBar: {
    flexDirection: 'row-reverse',
    alignItems: 'center',
    backgroundColor: '#F3F4F6',
    borderRadius: 12,
    paddingHorizontal: 12,
    height: 44,
  },
  searchInput: {
