interface HeaderProps {
  title: string;
  subtitle?: string;
  activeTab: 'home' | 'orders' | 'support' | 'settings';
  onTabChange: (tab: 'home' | 'orders' | 'support' | 'settings') => void;
  onRefresh?: () => void;
  dueRemindersCount?: number;
  onOpenRemindersModal?: () => void;
}

export const Header: React.FC<HeaderProps> = ({
  title,
  subtitle,
  activeTab,
  onTabChange,
  onRefresh,
  dueRemindersCount = 0,
  onOpenRemindersModal,
}) => {
  return (
    <View style={styles.container}>
      <View style={styles.topRow}>
        <View style={styles.titleContainer}>
          <Text style={styles.brandTitle}>מורנצ׳לו 🍋</Text>
          <Text style={styles.subtitle}>{subtitle || 'אפליקציית ניהול מובייל'}</Text>
        </View>

        <View style={styles.topActionsRow}>
          {onOpenRemindersModal && (
            <TouchableOpacity onPress={onOpenRemindersModal} style={styles.bellButton}>
              <Ionicons
                name={dueRemindersCount > 0 ? 'notifications' : 'notifications-outline'}
                size={20}
                color={dueRemindersCount > 0 ? '#EF4444' : '#D97706'}
              />
              {dueRemindersCount > 0 && (
                <View style={styles.headerBadge}>
                  <Text style={styles.headerBadgeText}>
                    {dueRemindersCount > 9 ? '9+' : dueRemindersCount}
                  </Text>
                </View>
              )}
            </TouchableOpacity>
          )}

          {onRefresh && (
            <TouchableOpacity onPress={onRefresh} style={styles.refreshButton}>
              <Ionicons name="refresh-outline" size={20} color="#D97706" />
            </TouchableOpacity>
          )}
        </View>
      </View>

      <View style={styles.navRow}>
        <TouchableOpacity
          style={[styles.tabButton, activeTab === 'home' && styles.tabButtonActive]}
          onPress={() => onTabChange('home')}
        >
          <Ionicons
            name={activeTab === 'home' ? 'grid' : 'grid-outline'}
            size={16}
            color={activeTab === 'home' ? '#FFFFFF' : '#4B5563'}
          />
          <Text style={[styles.tabText, activeTab === 'home' && styles.tabTextActive]}>
            דאשבורד
          </Text>
        </TouchableOpacity>

        <TouchableOpacity
          style={[styles.tabButton, activeTab === 'orders' && styles.tabButtonActive]}
          onPress={() => onTabChange('orders')}
        >
          <Ionicons
            name={activeTab === 'orders' ? 'list' : 'list-outline'}
            size={16}
            color={activeTab === 'orders' ? '#FFFFFF' : '#4B5563'}
          />
          <Text style={[styles.tabText, activeTab === 'orders' && styles.tabTextActive]}>
            הזמנות
          </Text>
        </TouchableOpacity>

        <TouchableOpacity
          style={[styles.tabButton, activeTab === 'support' && styles.tabButtonActive]}
          onPress={() => onTabChange('support')}
        >
          <Ionicons
            name={activeTab === 'support' ? 'chatbubbles' : 'chatbubbles-outline'}
            size={16}
            color={activeTab === 'support' ? '#FFFFFF' : '#4B5563'}
          />
          <Text style={[styles.tabText, activeTab === 'support' && styles.tabTextActive]}>
            פניות
          </Text>
        </TouchableOpacity>

        <TouchableOpacity
          style={[styles.tabButton, activeTab === 'settings' && styles.tabButtonActive]}
          onPress={() => onTabChange('settings')}
        >
          <Ionicons
            name={activeTab === 'settings' ? 'settings' : 'settings-outline'}
            size={16}
            color={activeTab === 'settings' ? '#FFFFFF' : '#4B5563'}
          />
          <Text style={[styles.tabText, activeTab === 'settings' && styles.tabTextActive]}>
            הגדרות
          </Text>
        </TouchableOpacity>
      </View>
    </View>
  );
};

