function setSession(phone, data) {
  const existing = userSessions.get(phone) || {};
  userSessions.set(phone, {
    ...existing,
    ...data,
    lastActive: Date.now(),
  });
}

// Format number to international WhatsApp JID
function formatJid(target) {
  if (!target || typeof target !== "string") return "";
  if (target.includes("@")) return target;
  let clean = target.replace(/\D/g, "");
  if (clean.startsWith("0")) {
    clean = "972" + clean.substring(1);
  } else if (!clean.startsWith("972") && clean.length <= 10) {
    clean = "972" + clean;
  }
  return `${clean}@s.whatsapp.net`;
}

// Send message function with replyJid smart routing
async function sendMessage(toPhone, text) {
  if (!sock || currentStatus !== "connected") {
    throw new Error("WhatsApp bot is not connected");
  }
  let targetJid = toPhone;
  if (!targetJid.includes("@")) {
    const session = getSession(toPhone);
    if (session && session.replyJid) {
      targetJid = session.replyJid;
    } else {
      targetJid = formatJid(toPhone);
    }
  }
  const result = await sock.sendMessage(targetJid, { text });
  console.log(`[WhatsApp Bot] Message sent to ${targetJid}: ${text.substring(0, 30)}...`);
  return result;
}

// Helpers for robust message content unpacking (ephemeral, viewOnce, interactive buttons)
function extractMessageText(message) {
  if (!message) return "";
  let msg = message;
  while (msg.ephemeralMessage || msg.viewOnceMessage || msg.viewOnceMessageV2 || msg.documentWithCaptionMessage) {
    msg =
      msg.ephemeralMessage?.message ||
      msg.viewOnceMessage?.message ||
      msg.viewOnceMessageV2?.message ||
      msg.documentWithCaptionMessage?.message;
    if (!msg) break;
  }
  if (!msg) return "";

  return (
    msg.conversation ||
    msg.extendedTextMessage?.text ||
    msg.imageMessage?.caption ||
    msg.videoMessage?.caption ||
    msg.buttonsResponseMessage?.selectedButtonId ||
    msg.buttonsResponseMessage?.selectedDisplayText ||
    msg.templateButtonReplyMessage?.selectedId ||
    msg.listResponseMessage?.singleSelectReply?.selectedRowId ||
    msg.interactiveResponseMessage?.body?.text ||
    ""
  );
}

function extractMessageLocation(message) {
  if (!message) return null;
  let msg = message;
  while (msg.ephemeralMessage || msg.viewOnceMessage || msg.viewOnceMessageV2) {
