const { createClient } = require("@supabase/supabase-js");
require("dotenv").config({ path: ".env.local" });
const supabase = createClient(process.env.NEXT_PUBLIC_SUPABASE_URL, process.env.SUPABASE_SERVICE_ROLE_KEY);

const crypto = require("crypto");
function getCipherKey() {
  const envKey = process.env.ENCRYPTION_KEY;
  if (envKey) {
    if (/^[0-9a-f]{64}$/i.test(envKey)) return Buffer.from(envKey, "hex");
    return crypto.createHash("sha256").update(envKey).digest();
  }
  return crypto.createHash("sha256").update(process.env.SUPABASE_SERVICE_ROLE_KEY || "default_fallback_secret").digest();
}
function decrypt(hash) {
  if (!hash) return null;
  try {
    const [ivHex, encryptedText] = hash.split(":");
    if (!ivHex || !encryptedText) return hash;
    const iv = Buffer.from(ivHex, "hex");
    const decipher = crypto.createDecipheriv("aes-256-cbc", getCipherKey(), iv);
    let decrypted = decipher.update(encryptedText, "hex", "utf8");
    decrypted += decipher.final("utf8");
    return decrypted;
  } catch (e) {
    return hash;
  }
}

async function run() {
  const { data: orders, error } = await supabase.from("orders").select("id, order_number, customer_name, customer_phone, created_at, status").order("created_at", { ascending: false }).limit(10);
  console.log("=== Recent Orders ===");
  orders.forEach(o => {
    console.log(`Order #${o.order_number}: phone=${decrypt(o.customer_phone)} status=${o.status} name=${decrypt(o.customer_name)} created=${o.created_at}`);
  });

  const { data: tickets } = await supabase.from("settings").select("value").eq("id", "support_tickets_store").maybeSingle();
  if (tickets?.value) {
    console.log("=== Support Tickets ===");
    console.log(tickets.value);
  }
}
run();
'

