require("dotenv").config({ path: ".env.local" });
const crypto = require("crypto");
const { createClient } = require("@supabase/supabase-js");
const supabase = createClient(process.env.NEXT_PUBLIC_SUPABASE_URL, process.env.SUPABASE_SERVICE_ROLE_KEY);

function getCipherKey() {
  const envKey = process.env.ENCRYPTION_KEY;
  if (envKey) {
    if (/^[0-9a-f]{64}$/i.test(envKey)) {
      return Buffer.from(envKey, "hex");
    }
    return crypto.createHash("sha256").update(envKey).digest();
  }
  return crypto.createHash("sha256").update(process.env.SUPABASE_SERVICE_ROLE_KEY || "default_fallback_secret").digest();
}

supabase.from("orders").select("*").then(({data}) => {
  data.forEach(o => {
    try {
      const [ivHex, enc] = o.customer_phone.split(":");
      const iv = Buffer.from(ivHex, "hex");
      const d = crypto.createDecipheriv("aes-256-cbc", getCipherKey(), iv);
      let dec = d.update(enc, "hex", "utf8") + d.final("utf8");
      console.log("Success with primary key:", dec);
    } catch (e) {
      console.log("Failed with primary key:", e.message);
      // Try fallback key (without ENCRYPTION_KEY)
      try {
        const fallbackKey = crypto.createHash("sha256").update(process.env.SUPABASE_SERVICE_ROLE_KEY).digest();
        const [ivHex, enc] = o.customer_phone.split(":");
        const iv = Buffer.from(ivHex, "hex");
        const d = crypto.createDecipheriv("aes-256-cbc", fallbackKey, iv);
        let dec = d.update(enc, "hex", "utf8") + d.final("utf8");
        console.log("Success with fallback key:", dec);
      } catch (e2) {
        console.log("Failed with fallback key:", e2.message);
      }
    }
  });
});
'

