// --- Encryption Helpers ---
const KNOWN_ENCRYPTION_KEY = "e89bb3a5981d221b1a8f7e64d4bdf6eb1401aad983a7acb611e92ef9168cd61c";

function getCipherKeys() {
  const keys = [];
  const primary = process.env.ENCRYPTION_KEY || KNOWN_ENCRYPTION_KEY;
  if (primary) {
    if (/^[0-9a-f]{64}$/i.test(primary)) {
      keys.push(Buffer.from(primary, "hex"));
    } else {
      keys.push(crypto.createHash("sha256").update(primary).digest());
    }
  }
  if (process.env.SUPABASE_SERVICE_ROLE_KEY) {
    keys.push(crypto.createHash("sha256").update(process.env.SUPABASE_SERVICE_ROLE_KEY).digest());
  }
  return keys;
}

function getPrimaryCipherKey() {
  const keys = getCipherKeys();
  return keys[0];
}

function decrypt(hash) {
  if (!hash) return null;
  try {
    const [ivHex, encryptedText] = hash.split(":");
    if (!ivHex || !encryptedText) return hash;
    const iv = Buffer.from(ivHex, "hex");
    for (const key of getCipherKeys()) {
      try {
        const decipher = crypto.createDecipheriv("aes-256-cbc", key, iv);
        let decrypted = decipher.update(encryptedText, "hex", "utf8");
        decrypted += decipher.final("utf8");
        if (decrypted) return decrypted;
      } catch (e) {}
    }
    return hash;
  } catch (e) {
    return hash;
  }
}

function encrypt(text) {
  if (!text) return null;
  const iv = crypto.randomBytes(16);
  const cipher = crypto.createCipheriv("aes-256-cbc", getPrimaryCipherKey(), iv);
  let encrypted = cipher.update(text, "utf8", "hex");
  encrypted += cipher.final("hex");
  return `${iv.toString("hex")}:${encrypted}`;
}

