// --- Order Matching Helper ---
async function findOrdersByPhone(phone) {
  if (!phone) return [];
  const cleanDigits = phone.replace(/\D/g, "");
  // Ignore WhatsApp internal LIDs (15-digit internal IDs not starting with 05 or 972)
  if (cleanDigits.length > 11 && !cleanDigits.startsWith("972") && !cleanDigits.startsWith("0")) {
    return [];
  }
  if (cleanDigits.length < 7) return [];

  const { data } = await supabase
    .from("orders")
    .select("*")
    .order("created_at", { ascending: false })
    .limit(200);

  if (!data) return [];

  return data.filter((order) => {
    let decPhone = "";
    try {
      decPhone = decrypt(order.customer_phone) || order.customer_phone || "";
    } catch (e) {
      decPhone = order.customer_phone || "";
    }
    const orderPhoneDigits = decPhone.replace(/\D/g, "");
    if (!orderPhoneDigits) return false;

    if (orderPhoneDigits === cleanDigits) return true;
    if (cleanDigits.length >= 7 && orderPhoneDigits.endsWith(cleanDigits.slice(-7))) return true;
    if (orderPhoneDigits.length >= 7 && cleanDigits.endsWith(orderPhoneDigits.slice(-7))) return true;
    return false;
  });
}

