// Resolve actual customer phone number from message metadata and LID mapping
async function extractSenderPhoneNumber(m) {
  const key = m.key || {};
  const candidates = [
    key.remoteJidAlt,
    key.participantAlt,
    m.participant,
    key.participant,
    key.remoteJid,
  ].filter(Boolean);

  // 1. Direct phone number JID (@s.whatsapp.net)
  for (const jid of candidates) {
    if (typeof jid === "string" && jid.endsWith("@s.whatsapp.net")) {
      let num = jid.split("@")[0].split(":")[0];
      if (num.startsWith("972")) {
        num = "0" + num.substring(3);
      }
      if (num.length >= 7 && !num.includes("@")) {
        return num;
      }
    }
  }

  // 2. Query Baileys signalRepository LID-to-PN cache
  for (const jid of candidates) {
    if (typeof jid === "string" && jid.endsWith("@lid") && sock?.signalRepository?.lidMapping?.getPNForLID) {
      try {
        const pn = await sock.signalRepository.lidMapping.getPNForLID(jid);
        if (pn && typeof pn === "string" && pn.includes("@s.whatsapp.net")) {
          let num = pn.split("@")[0].split(":")[0];
          if (num.startsWith("972")) {
            num = "0" + num.substring(3);
          }
          if (num.length >= 7) {
            return num;
          }
        }
      } catch (e) {}
    }
  }

  // 3. Fallback
  const rawId = (key.remoteJid || "").split("@")[0].split(":")[0];
  if (rawId.startsWith("972")) {
    return "0" + rawId.substring(3);
  }
  return rawId;
}

