// --- Order Matching Helpers & Cache ---
let cachedOrders = null;
let lastOrdersFetch = 0;

async function fetchAdminOrders(forceFresh = false) {
  if (!forceFresh && cachedOrders && Date.now() - lastOrdersFetch < 30000) {
    return cachedOrders;
  }

  const siteUrl = (process.env.SITE_URL || "https://www.morancello.com").replace(/\/$/, "");
  const token =
    process.env.SUPABASE_SERVICE_ROLE_KEY ||
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY ||
    "[REDACTED_SUPABASE_ANON_KEY]";

  // 1. Authoritative Next.js server API (bypasses RLS with full decryption)
  try {
    const res = await fetch(`${siteUrl}/api/admin/orders`, {
      method: "GET",
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json",
      },
    });
    if (res.ok) {
      const json = await res.json();
      if (json.success && Array.isArray(json.orders)) {
        cachedOrders = json.orders;
        lastOrdersFetch = Date.now();
        console.log(`[WhatsApp Bot] Successfully fetched ${cachedOrders.length} orders from server API`);
        return cachedOrders;
      }
    }
  } catch (err) {
    console.error("[WhatsApp Bot] Error fetching orders from server API:", err.message);
  }

  // 2. Direct Supabase fallback
  try {
    const { data } = await supabase
      .from("orders")
      .select("*")
      .order("created_at", { ascending: false })
      .limit(200);

    if (data && data.length > 0) {
      const decrypted = data.map((order) => {
        let decPhone = "";
        let decName = "";
        try {
          decPhone = decrypt(order.customer_phone) || order.customer_phone || "";
          decName = decrypt(order.customer_name) || order.customer_name || "";
        } catch (e) {
          decPhone = order.customer_phone || "";
          decName = order.customer_name || "";
        }
        return {
          ...order,
          customer_phone: decPhone,
          customer_name: decName,
        };
      });
      cachedOrders = decrypted;
      lastOrdersFetch = Date.now();
      return cachedOrders;
    }
  } catch (e) {}

  return cachedOrders || [];
}

async function findOrderByNumber(orderNum) {
  const num = parseInt(String(orderNum).replace(/\D/g, ""), 10);
  if (!num) return null;

  const orders = await fetchAdminOrders(true);
  if (orders && orders.length > 0) {
    const match = orders.find((o) => o.order_number === num);
    if (match) return match;
  }

  // Direct Supabase fallback
  try {
    const { data: order } = await supabase
      .from("orders")
      .select("id, order_number, status, total_price, pickup_method, customer_phone")
      .eq("order_number", num)
      .maybeSingle();
    return order || null;
  } catch (e) {
    return null;
  }
}

async function findOrdersByPhone(phone, pushName = null) {
  if (!phone && !pushName) return [];
  const cleanDigits = (phone || "").replace(/\D/g, "");

  const orders = await fetchAdminOrders();
  if (!orders || orders.length === 0) return [];

  const matched = orders.filter((order) => {
    const orderPhoneDigits = (order.customer_phone || "").replace(/\D/g, "");
    if (cleanDigits.length >= 7 && orderPhoneDigits) {
      if (orderPhoneDigits === cleanDigits) return true;
      if (orderPhoneDigits.endsWith(cleanDigits.slice(-7))) return true;
      if (cleanDigits.endsWith(orderPhoneDigits.slice(-7))) return true;
    }
    // Match by pushName if phone wasn't matched
    if (pushName && typeof pushName === "string" && pushName.trim().length >= 3) {
      const ordName = (order.customer_name || "").trim().toLowerCase();
      const pName = pushName.trim().toLowerCase();
      if (ordName === pName || ordName.includes(pName) || pName.includes(ordName)) {
        return true;
      }
    }
    return false;
  });

  return matched;
}

