    );
    setSession(phone, { ageVerified: true, step: "MAIN_MENU" });
    return;
  }

  if (targetOrder.status === "cancelled") {
    await sendMessage(phone, `הזמנה #${targetOrder.order_number} כבר מבוטלת.\nהקש 0 לחזרה לתפריט.`);
    setSession(phone, { ageVerified: true, step: "MAIN_MENU" });
    return;
  }

  setSession(phone, {
    ageVerified: true,
