export async function getWhatsAppBotSession(): Promise<Record<string, string> | null> {
  try {
    const supabaseAdmin = getSupabaseAdmin();
    if (!supabaseAdmin) return null;

    const { data, error } = await supabaseAdmin
      .from("settings")
      .select("value")
      .eq("id", "whatsapp_bot_session")
      .maybeSingle();

    if (error || !data || !data.value) return null;
    return JSON.parse(data.value);
  } catch (err) {
    console.error("Error fetching whatsapp_bot_session:", err);
    return null;
  }
}

/**
 * Save persistent WhatsApp bot auth session bundle to Supabase
 */
export async function saveWhatsAppBotSession(sessionData: Record<string, string>): Promise<boolean> {
  try {
    const supabaseAdmin = getSupabaseAdmin();
    if (!supabaseAdmin) return false;

    const { error } = await supabaseAdmin
      .from("settings")
      .upsert(
        {
          id: "whatsapp_bot_session",
          value: JSON.stringify(sessionData),
        },
        { onConflict: "id" }
      );

    if (error) {
      console.error("Error saving whatsapp_bot_session:", error);
      return false;
    }
    return true;
  } catch (err) {
    console.error("Error in saveWhatsAppBotSession:", err);
    return false;
  }
}

/**
 * Delete persistent WhatsApp bot auth session bundle
 */
export async function deleteWhatsAppBotSession(): Promise<boolean> {
  try {
    const supabaseAdmin = getSupabaseAdmin();
    if (!supabaseAdmin) return false;

    const { error } = await supabaseAdmin
      .from("settings")
      .delete()
      .eq("id", "whatsapp_bot_session");

    return !error;
  } catch (err) {
    console.error("Error deleting whatsapp_bot_session:", err);
    return false;
  }
}

