import { NextResponse } from "next/server";
import {
  getWhatsAppBotSession,
  saveWhatsAppBotSession,
  deleteWhatsAppBotSession,
} from "@/lib/whatsappBot";

export const dynamic = "force-dynamic";
export const revalidate = 0;

export async function GET() {
  try {
    const session = await getWhatsAppBotSession();
    if (!session) {
      return NextResponse.json({ success: false, session: null }, { status: 404 });
    }
    return NextResponse.json({ success: true, session });
  } catch (err: any) {
    console.error("API GET /api/whatsapp/session error:", err);
    return NextResponse.json({ success: false, error: err.message }, { status: 500 });
  }
}

export async function POST(req: Request) {
  try {
    const body = await req.json();
    const { session } = body;
    if (!session || typeof session !== "object") {
      return NextResponse.json({ success: false, error: "Missing session payload" }, { status: 400 });
    }

    const ok = await saveWhatsAppBotSession(session);
    if (!ok) {
      return NextResponse.json({ success: false, error: "Failed to persist session" }, { status: 500 });
    }

    return NextResponse.json({ success: true });
  } catch (err: any) {
    console.error("API POST /api/whatsapp/session error:", err);
    return NextResponse.json({ success: false, error: err.message }, { status: 500 });
  }
}

export async function DELETE() {
  try {
    const ok = await deleteWhatsAppBotSession();
    return NextResponse.json({ success: ok });
  } catch (err: any) {
    console.error("API DELETE /api/whatsapp/session error:", err);
    return NextResponse.json({ success: false, error: err.message }, { status: 500 });
  }
}

