// --- Cloud Session Persistence (Survives Ephemeral Container Restarts) ---
let saveSessionTimeout = null;

async function saveAuthStateToCloud() {
  if (saveSessionTimeout) clearTimeout(saveSessionTimeout);
  saveSessionTimeout = setTimeout(async () => {
    try {
      if (!fs.existsSync(authFolder)) return;
      const files = fs.readdirSync(authFolder);
      if (files.length === 0) return;

      const sessionBundle = {};
      for (const file of files) {
        if (file.endsWith(".json")) {
          const filePath = path.join(authFolder, file);
          sessionBundle[file] = fs.readFileSync(filePath, "utf-8");
        }
      }

      if (Object.keys(sessionBundle).length === 0) return;

      const siteUrl = (process.env.SITE_URL || "https://www.morancello.com").replace(/\/$/, "");
      const res = await fetch(`${siteUrl}/api/whatsapp/session`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ session: sessionBundle }),
      });
      if (res.ok) {
        console.log(`[WhatsApp Bot] Synced ${Object.keys(sessionBundle).length} auth files to Supabase cloud!`);
      }
    } catch (e) {
      console.error("[WhatsApp Bot] Error saving auth session to cloud:", e.message);
    }
  }, 2500);
}

async function restoreAuthStateFromCloud() {
  try {
    const credsPath = path.join(authFolder, "creds.json");
    if (fs.existsSync(credsPath)) {
      return true; // Already exists locally
    }

    const siteUrl = (process.env.SITE_URL || "https://www.morancello.com").replace(/\/$/, "");
    const res = await fetch(`${siteUrl}/api/whatsapp/session`, { signal: AbortSignal.timeout(6000) });
    if (res.ok) {
      const json = await res.json();
      if (json.success && json.session && typeof json.session === "object") {
        if (!fs.existsSync(authFolder)) {
          fs.mkdirSync(authFolder, { recursive: true });
        }
        for (const [filename, content] of Object.entries(json.session)) {
          fs.writeFileSync(path.join(authFolder, filename), content, "utf-8");
        }
        console.log(`[WhatsApp Bot] Successfully restored ${Object.keys(json.session).length} auth files from Supabase cloud!`);
        return true;
      }
    }
  } catch (e) {
    console.error("[WhatsApp Bot] Error restoring auth session from cloud:", e.message);
  }
  return false;
}

async function clearAuthStateFromCloud() {
  try {
    const siteUrl = (process.env.SITE_URL || "https://www.morancello.com").replace(/\/$/, "");
    await fetch(`${siteUrl}/api/whatsapp/session`, { method: "DELETE" });
    console.log("[WhatsApp Bot] Cleared session from Supabase cloud.");
  } catch (e) {}
}

// --- Main Baileys Initializer ---
async function startWhatsApp() {
  if (isStarting) return;
  isStarting = true;

  try {
    if (sock) {
      try {
        sock.ev.removeAllListeners();
        sock.end();
      } catch (e) {}
      sock = null;
    }

    // 1. Restore persistent session from Supabase cloud if missing locally
    await restoreAuthStateFromCloud();

    const logger = pino({ level: "silent" });
    const { state, saveCreds } = await useMultiFileAuthState(authFolder);
    const { version } = await fetchLatestBaileysVersion();

    console.log(`[WhatsApp Bot] Initializing Baileys v${version.join(".")}...`);

    sock = makeWASocket({
      version,
      auth: {
        creds: state.creds,
        keys: makeCacheableSignalKeyStore(state.keys, logger),
      },
      logger,
      browser: Browsers.macOS("Desktop"),
      syncFullHistory: false,
      markOnlineOnConnect: true,
      printQRInTerminal: false,
      connectTimeoutMs: 60000,
      defaultQueryTimeoutMs: 60000,
      keepAliveIntervalMs: 25000,
      retryRequestDelayMs: 250,
    });

    sock.ev.on("creds.update", async () => {
      await saveCreds();
      saveAuthStateToCloud();
    });

    sock.ev.on("connection.update", async (update) => {
      const { connection, lastDisconnect, qr } = update;

      if (qr) {
        console.log("[WhatsApp Bot] QR code generated!");
        try {
          const qrDataUrl = await qrcode.toDataURL(qr, { margin: 2, scale: 7 });
          await syncStatusToSupabase("qr_ready", qrDataUrl, null);
        } catch (e) {
          console.error("Error generating QR data URL:", e);
        }
      }

      if (connection === "close") {
        const statusCode = lastDisconnect?.error?.output?.statusCode;
        const isLoggedOut = statusCode === DisconnectReason.loggedOut;
        console.log(`[WhatsApp Bot] Connection closed. StatusCode: ${statusCode}. IsLoggedOut: ${isLoggedOut}`);

        if (isLoggedOut) {
          console.log("[WhatsApp Bot] Device logged out. Resetting session...");
          try {
            fs.rmSync(authFolder, { recursive: true, force: true });
          } catch (e) {}
          await clearAuthStateFromCloud();
          connectedPhone = null;
          currentQr = null;
          await syncStatusToSupabase("disconnected", null, null);
          setTimeout(() => {
            startWhatsApp();
          }, 3000);
        } else {
          if (statusCode === 408) {
            console.log("[WhatsApp Bot] QR expired. Refreshing QR...");
          } else {
            console.log(`[WhatsApp Bot] Transient disconnect (${statusCode}). Reconnecting in 3s with existing session...`);
          }
          setTimeout(() => {
            startWhatsApp();
          }, 3000);
        }
      } else if (connection === "open") {
        const userJid = sock.user?.id || "";
        let phone = userJid.split(":")[0] || userJid.split("@")[0];
        if (phone.startsWith("972")) {
          phone = "0" + phone.substring(3);
        }
        connectedPhone = phone;
        console.log(`[WhatsApp Bot] Connected successfully! Phone: ${phone}`);
        await syncStatusToSupabase("connected", null, phone);
        saveAuthStateToCloud();
      }
    });

