185: export async function createAndSaveWhatsAppOTP(rawPhone: string): Promise<{ success: boolean; code?: string; cleanPhone?: string; error?: string }> {
186:   try {
187:     const supabaseAdmin = getSupabaseAdmin();
188:     if (!supabaseAdmin) return { success: false, error: "Database client unavailable" };
189: 
190:     const cleanPhone = normalizePhoneNumber(rawPhone);
191:     if (!cleanPhone || cleanPhone.length < 9) {
192:       return { success: false, error: "מספר טלפון לא תקין" };
193:     }
194: 
195:     // Generate random 6-digit code
196:     const code = Math.floor(100000 + Math.random() * 900000).toString();
197:     const expiresAt = Date.now() + 5 * 60 * 1000; // 5 minutes
198: 
199:     const payload = JSON.stringify({
200:       code,
201:       expiresAt,
202:       attempts: 0,
203:       createdAt: Date.now(),
204:     });
205: 
206:     const key = `otp_wa_${cleanPhone}`;
207:     const { error } = await supabaseAdmin
208:       .from("settings")
209:       .upsert({ id: key, value: payload }, { onConflict: "id" });
210: 
211:     if (error) {
212:       console.error("Failed to save OTP:", error);
213:       return { success: false, error: "שגיאה ביצירת קוד האימות" };
214:     }
215: 
216:     return { success: true, code, cleanPhone };
217:   } catch (err: any) {
218:     console.error("Error in createAndSaveWhatsAppOTP:", err);
219:     return { success: false, error: err.message || "שגיאה ביצירת קוד האימות" };
220:   }
221: }
