226: export async function verifyWhatsAppOTP(rawPhone: string, inputCode: string): Promise<{ success: boolean; error?: string }> {
227:   try {
228:     const supabaseAdmin = getSupabaseAdmin();
229:     if (!supabaseAdmin) return { success: false, error: "Database client unavailable" };
230: 
231:     const cleanPhone = normalizePhoneNumber(rawPhone);
232:     const key = `otp_wa_${cleanPhone}`;
233: 
234:     const { data, error } = await supabaseAdmin
235:       .from("settings")
236:       .select("value")
237:       .eq("id", key)
238:       .maybeSingle();
239: 
240:     if (error || !data || !data.value) {
241:       return { success: false, error: "לא נמצא קוד אימות פעיל או שפג תוקפו" };
242:     }
243: 
244:     const record = JSON.parse(data.value);
245:     if (Date.now() > record.expiresAt) {
246:       // expired, delete it
247:       await supabaseAdmin.from("settings").delete().eq("id", key);
248:       return { success: false, error: "פג תוקף קוד האימות. אנא בקש קוד חדש." };
249:     }
250: 
251:     if (record.code !== inputCode.trim()) {
252:       record.attempts = (record.attempts || 0) + 1;
253:       if (record.attempts >= 5) {
254:         await supabaseAdmin.from("settings").delete().eq("id", key);
255:         return { success: false, error: "מספר נסיונות שגויים רב מדי. אנא בקש קוד חדש." };
256:       }
257:       await supabaseAdmin
258:         .from("settings")
259:         .upsert({ id: key, value: JSON.stringify(record) }, { onConflict: "id" });
260:       return { success: false, error: "קוד אימות שגוי. נסה שוב." };
261:     }
262: 
263:     // Success - clean up OTP
264:     await supabaseAdmin.from("settings").delete().eq("id", key);
265:     return { success: true };
266:   } catch (err: any) {
267:     console.error("Error in verifyWhatsAppOTP:", err);
268:     return { success: false, error: err.message || "שגיאה באימות הקוד" };
269:   }
270: }
