export async function POST(req: Request) {
  if (!isAuthorized(req)) {
    return NextResponse.json({ success: false, error: "Unauthorized" }, { status: 401 });
  }
  try {
    const body = await req.json();
    const { session } = body;
    if (!session || typeof session !== "object") {
      return NextResponse.json({ success: false, error: "Missing session payload" }, { status: 400 });
    }

    const ok = await saveWhatsAppBotSession(session);
    if (!ok) {
      return NextResponse.json({ success: false, error: "Failed to persist session" }, { status: 500 });
    }

    return NextResponse.json({ success: true });
  } catch (err: any) {
    console.error("API POST /api/whatsapp/session error:", err);
    return NextResponse.json({ success: false, error: err.message }, { status: 500 });
  }
}

export async function DELETE(req: Request) {
  if (!isAuthorized(req)) {
    return NextResponse.json({ success: false, error: "Unauthorized" }, { status: 401 });
  }
  try {
    const ok = await deleteWhatsAppBotSession();
    return NextResponse.json({ success: ok });
  } catch (err: any) {
    console.error("API DELETE /api/whatsapp/session error:", err);
    return NextResponse.json({ success: false, error: err.message }, { status: 500 });
  }
}

