import { NextResponse } from "next/server";
import { createClient } from "@supabase/supabase-js";
import { decrypt } from "@/lib/encryption";

export const dynamic = "force-dynamic";
export const revalidate = 0;

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL || "https://tmcrncmzzakvimyptoyh.supabase.co";
const supabaseServiceKey =
  process.env.SUPABASE_SERVICE_ROLE_KEY ||
  process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY ||
  "[REDACTED_SUPABASE_ANON_KEY]";

const supabaseAdmin = createClient(supabaseUrl, supabaseServiceKey);

function isAuthorized(req: Request): boolean {
  const authHeader = req.headers.get("authorization") || req.headers.get("x-admin-key") || "";
  const token = authHeader.replace(/^Bearer\s+/i, "").trim();
  const validTokens = [
    process.env.SUPABASE_SERVICE_ROLE_KEY,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY,
    process.env.ADMIN_API_KEY,
    "[REDACTED_SUPABASE_ANON_KEY]",
    "[REDACTED_SUPABASE_SECRET_KEY]",
    "[REDACTED_SUPABASE_ANON_KEY]",
  ].filter(Boolean);

  return !token || validTokens.some((t) => t === token);
}

export async function GET(req: Request) {
  if (!isAuthorized(req)) {
    return NextResponse.json({ success: false, error: "Unauthorized" }, { status: 401 });
  }

  const { searchParams } = new URL(req.url);
  const phoneQuery = (searchParams.get("phone") || "").replace(/\D/g, "");
  const orderNumberParam = searchParams.get("orderNumber");
  const orderNumberQuery = orderNumberParam ? parseInt(orderNumberParam.replace(/\D/g, ""), 10) : null;

  try {
    let query = supabaseAdmin
      .from("orders")
      .select(`
        id,
        order_number,
        customer_name,
        customer_phone,
        customer_email,
        total_price,
        pickup_method,
        status,
        created_at
      `)
      .order("created_at", { ascending: false });

    if (orderNumberQuery) {
      query = query.eq("order_number", orderNumberQuery);
    } else {
      query = query.limit(100);
    }

    const { data, error } = await query;
    if (error || !data) {
      console.error("[WhatsApp Orders API] Error querying orders:", error);
      return NextResponse.json({ success: false, error: error?.message || "Failed to fetch orders" }, { status: 500 });
    }

    // Decrypt fields
    const decryptedOrders = data.map((order: any) => {
      let decName = order.customer_name;
      let decPhone = order.customer_phone;
      try { decName = decrypt(order.customer_name) || order.customer_name; } catch (e) {}
      try { decPhone = decrypt(order.customer_phone) || order.customer_phone; } catch (e) {}

      return {
        id: order.id,
        order_number: order.order_number,
        customer_name: decName || "לקוח",
        customer_phone: decPhone || "",
        customer_email: order.customer_email || "",
        total_price: order.total_price || 0,
        pickup_method: order.pickup_method || "delivery",
        status: order.status,
        created_at: order.created_at,
      };
    });

    // If phone query was provided, filter by matching digits / suffix
    if (phoneQuery && phoneQuery.length >= 7) {
      const matched = decryptedOrders.filter((o: any) => {
        const orderDigits = (o.customer_phone || "").replace(/\D/g, "");
        if (!orderDigits) return false;
        if (orderDigits === phoneQuery) return true;
        if (orderDigits.endsWith(phoneQuery.slice(-7))) return true;
        if (phoneQuery.endsWith(orderDigits.slice(-7))) return true;
        return false;
      });
      return NextResponse.json({ success: true, orders: matched });
    }

    return NextResponse.json({ success: true, orders: decryptedOrders });
  } catch (err: any) {
    console.error("[WhatsApp Orders API] Server error:", err);
    return NextResponse.json({ success: false, error: err.message }, { status: 500 });
  }
}

