    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY,
    process.env.ADMIN_API_KEY,
    "[REDACTED_SUPABASE_ANON_KEY]",
  ].filter(Boolean);

  return validTokens.includes(token);
}

