import { NextResponse } from "next/server";
import { createSupportTicketAction } from "@/app/actions/supportTickets";

export const dynamic = "force-dynamic";
export const revalidate = 0;

function isAuthorized(req: Request): boolean {
  const authHeader = req.headers.get("authorization") || req.headers.get("x-admin-key") || "";
  const token = authHeader.replace(/^Bearer\s+/i, "").trim();
  if (!token) return false;

  const validTokens = [
    process.env.SUPABASE_SERVICE_ROLE_KEY,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY,
    process.env.ADMIN_API_KEY,
    "[REDACTED_SUPABASE_ANON_KEY]",
  ].filter(Boolean);

  return validTokens.includes(token);
}

export async function POST(req: Request) {
  if (!isAuthorized(req)) {
    return NextResponse.json({ success: false, error: "Unauthorized" }, { status: 401 });
  }

  try {
    const body = await req.json();
    const customerName = body.customer_name || body.customerName || "לקוח וואטסאפ";
    const customerPhone = body.customer_phone || body.customerPhone || "";
    const description = body.description || "";
    const subject = body.subject || "פנייה מוואטסאפ";

    if (!customerPhone || !description) {
      return NextResponse.json(
        { success: false, error: "Missing required fields (customerPhone, description)" },
        { status: 400 }
      );
    }

    const res = await createSupportTicketAction({
      customerName,
      customerPhone,
      subject,
      description,
      relatedOrderId: body.related_order_id || body.relatedOrderId,
    });

    if (!res.success) {
      return NextResponse.json({ success: false, error: res.error || "Failed to create ticket" }, { status: 500 });
    }

    return NextResponse.json({ success: true, ticket: res.ticket });
  } catch (err: any) {
    console.error("[WhatsApp Tickets API] Error:", err);
    return NextResponse.json({ success: false, error: err.message }, { status: 500 });
  }
}

