async function handleSupportDesc(phone, text, session) {
  if (!text || text.length < 3) {
    await sendMessage(phone, `אנא תאר בקצרה את הפנייה:`);
    return;
  }

  const customerName = session.supportName || "לקוח וואטסאפ";
  const desc = text;
  const siteUrl = (process.env.SITE_URL || "https://www.morancello.com").replace(/\/$/, "");
  let ticket = null;

  // 1. Authoritative Next.js Tickets API (bypasses RLS, saves store, triggers push)
  try {
    const res = await fetch(`${siteUrl}/api/whatsapp/tickets`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${DEFAULT_AUTH_TOKEN}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        customer_name: customerName,
        customer_phone: phone,
        subject: "פנייה מוואטסאפ",
        description: desc,
      }),
    });
    if (res.ok) {
      const json = await res.json();
      if (json.success && json.ticket) {
        ticket = json.ticket;
        console.log(`[WhatsApp Bot] Created support ticket #T-${ticket.ticket_number} via API!`);
      }
    }
  } catch (e) {
    console.error("[WhatsApp Bot] Error creating ticket via /api/whatsapp/tickets:", e.message);
  }

  // 2. Fallback to /api/admin/tickets
  if (!ticket) {
    try {
      const res = await fetch(`${siteUrl}/api/admin/tickets`, {
        method: "POST",
        headers: {
          Authorization: `Bearer ${DEFAULT_AUTH_TOKEN}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          action: "create",
          customer_name: customerName,
          customer_phone: phone,
          subject: "פנייה מוואטסאפ",
          description: desc,
        }),
      });
      if (res.ok) {
        const json = await res.json();
        if (json.success && json.ticket) {
          ticket = json.ticket;
          console.log(`[WhatsApp Bot] Created support ticket #T-${ticket.ticket_number} via /api/admin/tickets fallback!`);
        }
      }
    } catch (e) {}
  }

  const ticketNum = ticket?.ticket_number || "1001";
  const ticketId = ticket?.id || `tkt_${Date.now()}`;

  // 3. Confirm to customer with Closing Motto
  await sendMessage(
    phone,
    `פנייתך התקבלה בהצלחה! 🍋\nמספר פנייה: #T-${ticketNum}\n\nהפנייה נרשמה במערכת ונציג שירות ישיב לך בהקדם ישירות לכאן בוואטסאפ.\n\n${CLOSING_MOTTO}`
  );

  setSession(phone, { ageVerified: true, step: "MAIN_MENU" });
}

