// --- 2. Status Inquiry Flow (Sorted Oldest to Newest for Active Orders) ---
const ACTIVE_ORDER_STATUSES = ["pending", "paid", "processing", "shipped", "backorder_pending", "backorder_held"];

function formatOrdersStatusResponse(orders, siteUrl, headerNote = "") {
  if (!orders || orders.length === 0) return "";

  // 1. Separate active orders
  const activeOrders = orders.filter((o) => ACTIVE_ORDER_STATUSES.includes(o.status));

  // If there are active orders: sort from OLDEST to NEWEST (ascending order_number / created_at)
  if (activeOrders.length > 0) {
    const sorted = [...activeOrders].sort((a, b) => (a.order_number || 0) - (b.order_number || 0));

    if (sorted.length === 1) {
      const o = sorted[0];
      const statusHebrew = formatStatusHebrew(o.status);
      const receiptUrl = `${siteUrl}/receipt/${o.id}`;
      return `${headerNote ? headerNote + "\n\n" : ""}📦 נמצאה הזמנה פעילה במערכת:\n\n🔹 הזמנה #${o.order_number}:\n• סטטוס: ${statusHebrew}\n• סכום: ${o.total_price} ₪\n• אופן קבלה: ${o.pickup_method === "pickup" ? "איסוף עצמי" : "משלוח"}\n• לצפייה בפרטים וקבלה:\n${receiptUrl}\n\n${CLOSING_MOTTO}`;
    }

    let msg = `${headerNote ? headerNote + "\n\n" : ""}📦 נמצאו ${sorted.length} הזמנות פעילות במערכת (מוצגות מהישן לחדש):\n\n`;
    sorted.forEach((o, idx) => {
      const statusHebrew = formatStatusHebrew(o.status);
      const receiptUrl = `${siteUrl}/receipt/${o.id}`;
      msg += `${idx + 1}️⃣ הזמנה #${o.order_number}:\n• סטטוס: ${statusHebrew}\n• סכום: ${o.total_price} ₪\n• אופן קבלה: ${o.pickup_method === "pickup" ? "איסוף עצמי" : "משלוח"}\n• לצפייה וקבלה:\n${receiptUrl}\n\n`;
    });
    msg += `${CLOSING_MOTTO}`;
    return msg;
  }

  // 2. If NO active orders: show most recent past order(s)
  const sortedPast = [...orders].sort((a, b) => (b.order_number || 0) - (a.order_number || 0));
  const latest = sortedPast[0];
  const statusHebrew = formatStatusHebrew(latest.status);
  const receiptUrl = `${siteUrl}/receipt/${latest.id}`;
  return `${headerNote ? headerNote + "\n\n" : ""}📦 לא נמצאו הזמנות פעילות כרגע בהכנה או במשלוח.\nלהלן ההזמנה האחרונה שלך במערכת:\n\n🔹 הזמנה #${latest.order_number}:\n• סטטוס: ${statusHebrew}\n• סכום: ${latest.total_price} ₪\n• אופן קבלה: ${latest.pickup_method === "pickup" ? "איסוף עצמי" : "משלוח"}\n• לצפייה בפרטים וקבלה:\n${receiptUrl}\n\n${CLOSING_MOTTO}`;
}

async function handleStatusInquiry(phone) {
  const session = getSession(phone);
  const targetPhone = session?.realPhone || session?.userPhone || phone;
  const orders = await findOrdersByPhone(targetPhone, session?.pushName);

  if (!orders || orders.length === 0) {
    setSession(phone, { ageVerified: true, step: "LOOKUP_ORDER" });
    await sendMessage(
      phone,
      `לא נמצאו הזמנות קודמות המשויכות למספר הטלפון שלך (${targetPhone}) 🔍\nאם ביצעת הזמנה תחת מספר טלפון אחר או שיש ברשותך מספר הזמנה ספציפי, באפשרותך להקליד אותו:\n(להצגת התפריט הקלד 0)`
    );
    return;
  }

  const siteUrl = (process.env.SITE_URL || "https://www.morancello.com").replace(/\/$/, "");
  const responseMsg = formatOrdersStatusResponse(orders, siteUrl);

  await sendMessage(phone, responseMsg);
}

async function handleOrderLookupInput(phone, text) {
  const clean = text.trim();
  const digitsOnly = clean.replace(/\D/g, "");
  const siteUrl = (process.env.SITE_URL || "https://www.morancello.com").replace(/\/$/, "");

  // 1. If input looks like a phone number (>= 7 digits with 0/972, or >= 9 digits)
  if (digitsOnly.length >= 9 || (digitsOnly.length >= 7 && (digitsOnly.startsWith("0") || digitsOnly.startsWith("972")))) {
    const orders = await findOrdersByPhone(digitsOnly);
    if (orders && orders.length > 0) {
      setSession(phone, { ageVerified: true, userPhone: digitsOnly, step: "MAIN_MENU" });
      const responseMsg = formatOrdersStatusResponse(
        orders,
        siteUrl,
        `נמצאו הזמנות עבור מספר הטלפון ${digitsOnly}:`
      );
      await sendMessage(phone, responseMsg);
      return;
    } else {
      await sendMessage(
        phone,
        `לא נמצאו הזמנות במערכת עבור מספר הטלפון ${digitsOnly}.\n\nבאפשרותך להקליד מספר הזמנה (לדוגמה: 1), להקליד מספר טלפון אחר, או להקיש 0 לחזרה לתפריט:`
      );
      return;
    }
  }

  // 2. Otherwise treat as order number (e.g. 1, #1)
  const orderNum = parseInt(digitsOnly, 10);
  if (!orderNum) {
    await sendMessage(
      phone,
      `לא זיהינו מספר הזמנה או מספר טלפון תקין.\nאנא הקלד מספר טלפון מלא (למשל: 0541234567) או מספר הזמנה (למשל: 1), או 0 לתפריט:`
    );
    return;
  }

  const order = await findOrderByNumber(orderNum);

  if (!order) {
    await sendMessage(
      phone,
      `הזמנה #${orderNum} לא נמצאה במערכת.\n\nאנא ודא את מספר ההזמנה, או הקלד מספר טלפון לחיפוש (או 0 לחזרה לתפריט הראשי):`
    );
    return;
  }

  const statusHebrew = formatStatusHebrew(order.status);
  const receiptUrl = `${siteUrl}/receipt/${order.id}`;

  await sendMessage(
    phone,
    `📦 הזמנה #${order.order_number}:\nסטטוס: ${statusHebrew}\nסכום: ${order.total_price} ₪\nאופן קבלה: ${order.pickup_method === "pickup" ? "איסוף עצמי" : "משלוח"}\n\nלצפייה בפרטים:\n${receiptUrl}\n\n${CLOSING_MOTTO}`
  );
  setSession(phone, { ageVerified: true, step: "MAIN_MENU" });
}

// --- 3. Payment Completion Flow ---
async function handlePaymentCompletion(phone) {
  const session = getSession(phone);
  const targetPhone = session?.userPhone || phone;
  const orders = await findOrdersByPhone(targetPhone);
  const pendingOrders = (orders || []).filter((o) => o.status === "pending" || o.status === "backorder_held");

  if (pendingOrders.length === 0) {
    setSession(phone, { ageVerified: true, step: "PAYMENT_LOOKUP" });
    await sendMessage(
      phone,
      `לא נמצאו הזמנות הממתינות לתשלום המשויכות ישירות למספר זה.\n\nאנא הקלד את מספר הטלפון של ההזמנה או את מספר ההזמנה (או 0 לתפריט):`
    );
    return;
  }

  const sortedPending = [...pendingOrders].sort((a, b) => (a.order_number || 0) - (b.order_number || 0));
  const siteUrl = (process.env.SITE_URL || "https://www.morancello.com").replace(/\/$/, "");

  if (sortedPending.length === 1) {
    const target = sortedPending[0];
    const checkoutUrl = `${siteUrl}/checkout?orderId=${target.id}`;
    await sendMessage(
      phone,
      `נמצאה הזמנה #${target.order_number} הממתינה לתשלום בסך ${target.total_price} ₪.\n\nלהשלמת תשלום מאובטח ב-Bit / Apple Pay / אשראי:\n${checkoutUrl}\n\n${CLOSING_MOTTO}`
    );
  } else {
    let msg = `נמצאו ${sortedPending.length} הזמנות הממתינות לתשלום (מוצגות מהישן לחדש):\n\n`;
    sortedPending.forEach((target, idx) => {
      const checkoutUrl = `${siteUrl}/checkout?orderId=${target.id}`;
      msg += `${idx + 1}️⃣ הזמנה #${target.order_number} (סך: ${target.total_price} ₪):\nלהשלמת תשלום: ${checkoutUrl}\n\n`;
    });
    msg += `${CLOSING_MOTTO}`;
    await sendMessage(phone, msg);
  }
}

async function handlePaymentLookupInput(phone, text) {
  const digitsOnly = text.replace(/\D/g, "");
  let targetOrders = [];

  if (digitsOnly.length >= 9 || (digitsOnly.length >= 7 && digitsOnly.startsWith("0"))) {
    const orders = await findOrdersByPhone(digitsOnly);
    targetOrders = (orders || []).filter((o) => o.status === "pending" || o.status === "backorder_held");
  } else {
    const orderNum = parseInt(digitsOnly, 10);
    if (orderNum) {
      const order = await findOrderByNumber(orderNum);
      if (order && (order.status === "pending" || order.status === "backorder_held")) {
        targetOrders = [order];
      }
    }
  }

  if (targetOrders.length === 0) {
    await sendMessage(
      phone,
      `לא נמצאה הזמנה הממתינה לתשלום לפי הפרטים שהזנת.\nאנא נסה שוב (מספר טלפון או מספר הזמנה) או הקלד 0 לחזרה לתפריט:`
    );
    return;
  }

  const sortedPending = [...targetOrders].sort((a, b) => (a.order_number || 0) - (b.order_number || 0));
  const siteUrl = (process.env.SITE_URL || "https://www.morancello.com").replace(/\/$/, "");

  if (sortedPending.length === 1) {
    const target = sortedPending[0];
    const checkoutUrl = `${siteUrl}/checkout?orderId=${target.id}`;
    await sendMessage(
      phone,
      `נמצאה הזמנה #${target.order_number} הממתינה לתשלום בסך ${target.total_price} ₪.\n\nלהשלמת תשלום מאובטח:\n${checkoutUrl}\n\n${CLOSING_MOTTO}`
    );
  } else {
    let msg = `נמצאו ${sortedPending.length} הזמנות הממתינות לתשלום (מוצגות מהישן לחדש):\n\n`;
    sortedPending.forEach((target, idx) => {
      const checkoutUrl = `${siteUrl}/checkout?orderId=${target.id}`;
      msg += `${idx + 1}️⃣ הזמנה #${target.order_number} (סך: ${target.total_price} ₪):\nלהשלמת תשלום: ${checkoutUrl}\n\n`;
    });
    msg += `${CLOSING_MOTTO}`;
    await sendMessage(phone, msg);
  }
  setSession(phone, { ageVerified: true, step: "MAIN_MENU" });
}

