      `לא זיהינו מספר הזמנה או מספר טלפון תקין.\nאנא הקלד מספר טלפון מלא (למשל: 0541234567) או מספר הזמנה (למשל: 1), או 0 לתפריט:`
    );
    return;
  }

  const order = await findOrderByNumber(orderNum);

  if (!order) {
    await sendMessage(
      phone,
      `הזמנה #${orderNum} לא נמצאה במערכת.\n\nאנא ודא את מספר ההזמנה, או הקלד מספר טלפון לחיפוש (או 0 לחזרה לתפריט הראשי):`
    );
    return;
  }

  const statusHebrew = formatStatusHebrew(order.status);
  const siteUrl = (process.env.SITE_URL || "https://www.morancello.com").replace(/\/$/, "");
  const receiptUrl = `${siteUrl}/receipt/${order.id}`;

  await sendMessage(
    phone,
    `📦 הזמנה #${order.order_number}:\nסטטוס: ${statusHebrew}\nסכום: ${order.total_price} ₪\nאופן קבלה: ${order.pickup_method === "pickup" ? "איסוף עצמי" : "משלוח"}\n\nלצפייה בפרטים:\n${receiptUrl}\n\n${CLOSING_MOTTO}`
  );
  setSession(phone, { ageVerified: true, step: "MAIN_MENU" });
}

// --- 3. Payment Completion Flow ---
async function handlePaymentCompletion(phone) {
  const session = getSession(phone);
  const targetPhone = session?.userPhone || phone;
  const orders = await findOrdersByPhone(targetPhone);
  const pendingOrders = (orders || []).filter((o) => o.status === "pending" || o.status === "backorder_held");

  if (pendingOrders.length === 0) {
    setSession(phone, { ageVerified: true, step: "PAYMENT_LOOKUP" });
    await sendMessage(
      phone,
      `לא נמצאו הזמנות הממתינות לתשלום המשויכות ישירות למספר זה.\n\nאנא הקלד את מספר הטלפון של ההזמנה או את מספר ההזמנה (או 0 לתפריט):`
    );
    return;
  }

  const target = pendingOrders[0];
  const siteUrl = (process.env.SITE_URL || "https://www.morancello.com").replace(/\/$/, "");
  const checkoutUrl = `${siteUrl}/checkout?orderId=${target.id}`;

  await sendMessage(
    phone,
    `נמצאה הזמנה #${target.order_number} הממתינה לתשלום בסך ${target.total_price} ₪.\n\nלהשלמת תשלום מאובטח ב-Bit / Apple Pay / אשראי:\n${checkoutUrl}\n\n${CLOSING_MOTTO}`
  );
}

async function handlePaymentLookupInput(phone, text) {
  const digitsOnly = text.replace(/\D/g, "");
  let targetOrder = null;

  if (digitsOnly.length >= 9 || (digitsOnly.length >= 7 && digitsOnly.startsWith("0"))) {
    const orders = await findOrdersByPhone(digitsOnly);
    const pendings = (orders || []).filter((o) => o.status === "pending" || o.status === "backorder_held");
    if (pendings.length > 0) targetOrder = pendings[0];
  } else {
    const orderNum = parseInt(digitsOnly, 10);
    if (orderNum) {
      const order = await findOrderByNumber(orderNum);
      if (order && (order.status === "pending" || order.status === "backorder_held")) {
        targetOrder = order;
      }
    }
  }

  if (!targetOrder) {
    await sendMessage(
      phone,
      `לא נמצאה הזמנה הממתינה לתשלום לפי הפרטים שהזנת.\nאנא נסה שוב (מספר טלפון או מספר הזמנה) או הקלד 0 לחזרה לתפריט:`
    );
    return;
  }

  const siteUrl = (process.env.SITE_URL || "https://www.morancello.com").replace(/\/$/, "");
  const checkoutUrl = `${siteUrl}/checkout?orderId=${targetOrder.id}`;

  await sendMessage(
    phone,
    `נמצאה הזמנה #${targetOrder.order_number} הממתינה לתשלום בסך ${targetOrder.total_price} ₪.\n\nלהשלמת תשלום מאובטח:\n${checkoutUrl}\n\n${CLOSING_MOTTO}`
  );
  setSession(phone, { ageVerified: true, step: "MAIN_MENU" });
}

