124: export async function cancelUserOrder(orderId: string, identifier: string) {
125:   if (!orderId || !identifier) {
126:     return { success: false, error: "חסרים פרטי הזמנה" };
127:   }
128: 
129:   const clean = identifier.trim().toLowerCase();
130:   const cleanDigits = identifier.replace(/\D/g, "");
131: 
132:   // 1. Fetch order to verify ownership & status
133:   const { data: order, error: fetchErr } = await supabaseAdmin
134:     .from("orders")
135:     .select("*")
136:     .eq("id", orderId)
137:     .single();
138: 
139:   if (fetchErr || !order) {
140:     return { success: false, error: "ההזמנה לא נמצאה" };
141:   }
142: 
143:   let decEmail = order.customer_email;
144:   let decPhone = order.customer_phone;
145:   try { decEmail = decrypt(order.customer_email) || order.customer_email; } catch (e) {}
146:   try { decPhone = decrypt(order.customer_phone) || order.customer_phone; } catch (e) {}
147: 
148:   const emailMatch = decEmail && decEmail.trim().toLowerCase() === clean;
149:   const phoneDigits = (decPhone || "").replace(/\D/g, "");
150:   const phoneMatch = cleanDigits.length >= 7 && phoneDigits.endsWith(cleanDigits.slice(-7));
151: 
152:   if (!emailMatch && !phoneMatch) {
153:     return { success: false, error: "אין הרשאה לבטל הזמנה זו" };
154:   }
155: 
156:   if (order.status === "shipped" || order.status === "delivered") {
157:     return { 
158:       success: false, 
159:       error: "המשלוח שלך כבר נארז ויצא לדרך! במידה ותרצה לבצע שינוי, נשמח לסייע בשירות הלקוחות שלנו." 
160:     };
161:   }
162: 
163:   if (order.status === "cancelled") {
164:     return { success: false, error: "ההזמנה כבר מבוטלת" };
165:   }
166: 
167:   const { processOrderRefundAndCancellation } = await import("@/app/actions/refund");
168:   const refundResult = await processOrderRefundAndCancellation(orderId, {
169:     reason: "בוטל לבקשת המשתמש באזור האישי",
170:     sendEmail: true,
171:   });
172: 
173:   if (!refundResult.success) {
174:     return { success: false, error: refundResult.error || "אירעה שגיאה בביטול ההזמנה" };
175:   }
176: 
177:   return { success: true };
178: }
