110: export async function processOrderRefundAndCancellation(
111:   orderId: string,
112:   options?: { reason?: string; sendEmail?: boolean }
113: ): Promise<RefundResult> {
114:   try {
115:     const { data: order, error: fetchErr } = await supabaseAdmin
116:       .from("orders")
117:       .select("*")
118:       .eq("id", orderId)
119:       .maybeSingle();
120: 
121:     if (fetchErr || !order) {
122:       return { success: false, refunded: false, error: "ההזמנה לא נמצאה במערכת" };
123:     }
124: 
125:     if (order.status === "cancelled") {
126:       return { success: true, refunded: false, message: "ההזמנה כבר מבוטלת" };
127:     }
128: 
129:     const isPaid = order.status === "paid" || order.status === "shipped" || order.status === "delivered";
130:     const amountToRefund = order.total_price || 0;
131: 
132:     let refundNotes = "";
133:     let wasRefunded = false;
134: 
135:     const nowStr = new Date().toLocaleString("he-IL");
136: 
137:     if (isPaid && amountToRefund > 0) {
138:       const refundRes = await executeMeshulamRefund(orderId, amountToRefund, order.admin_notes || "");
139:       wasRefunded = refundRes.success;
140:       refundNotes = refundRes.notesAddition;
141:     } else {
142:       refundNotes = `שריון מבוטל והמלאי שוחרר למערכת בתאריך ${nowStr}`;
143:     }
144: 
145:     // Prepare updated admin notes
146:     const reasonText = options?.reason ? ` [סיבה: ${options.reason}]` : "";
147:     const updatedNotes = order.admin_notes
