import { NextResponse } from "next/server";
import { createClient } from "@supabase/supabase-js";
import { processOrderRefundAndCancellation } from "@/app/actions/refund";

export const dynamic = "force-dynamic";
export const revalidate = 0;

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL || "https://tmcrncmzzakvimyptoyh.supabase.co";
const supabaseServiceKey =
  process.env.SUPABASE_SERVICE_ROLE_KEY ||
  process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY ||
  "[REDACTED_SUPABASE_ANON_KEY]";

const supabaseAdmin = createClient(supabaseUrl, supabaseServiceKey);

function isAuthorized(req: Request): boolean {
  const authHeader = req.headers.get("authorization") || req.headers.get("x-admin-key") || "";
  const token = authHeader.replace(/^Bearer\s+/i, "").trim();
  if (!token) return false;

  const validTokens = [
    process.env.SUPABASE_SERVICE_ROLE_KEY,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY,
    process.env.ADMIN_API_KEY,
    "[REDACTED_SUPABASE_ANON_KEY]",
  ].filter(Boolean);

  return validTokens.includes(token);
}

export async function POST(req: Request) {
  if (!isAuthorized(req)) {
    return NextResponse.json({ success: false, error: "Unauthorized" }, { status: 401 });
  }

  try {
    const body = await req.json();
    const orderId = body.orderId || body.order_id;

    if (!orderId) {
      return NextResponse.json({ success: false, error: "Missing orderId" }, { status: 400 });
    }

    // 1. Fetch order details
    const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(String(orderId));
    let query = supabaseAdmin.from("orders").select("id, order_number, status, total_price");

    if (isUuid) {
      query = query.eq("id", orderId);
    } else {
      const num = parseInt(String(orderId), 10);
      if (!isNaN(num)) {
        query = query.eq("order_number", num);
      } else {
        query = query.eq("id", orderId);
      }
    }

    const { data: order, error: fetchErr } = await query.maybeSingle();

    if (fetchErr || !order) {
      return NextResponse.json({ success: false, error: "ההזמנה לא נמצאה במערכת" }, { status: 404 });
    }

    if (order.status === "shipped" || order.status === "delivered") {
      return NextResponse.json(
        { success: false, error: "ההזמנה כבר נארזה ויצאה לדרך ולא ניתן לבטלה אוטומטית" },
        { status: 400 }
      );
    }

    if (order.status === "cancelled") {
      return NextResponse.json(
        {
          success: true,
          message: "ההזמנה כבר מבוטלת",
          orderNumber: order.order_number,
          orderId: order.id,
          receiptUrl: `https://www.morancello.com/receipt/${order.id}`,
        },
        { status: 200 }
      );
    }

    // 2. Authoritative cancellation & refund processing
    const refundResult = await processOrderRefundAndCancellation(order.id, {
      reason: "בוטל לבקשת הלקוח בבוט הוואטסאפ",
      sendEmail: true,
    });

    if (!refundResult.success) {
      return NextResponse.json(
        { success: false, error: refundResult.error || "שגיאה בביצוע ביטול וזיכוי ההזמנה" },
        { status: 500 }
      );
    }

    const siteUrl = (process.env.NEXT_PUBLIC_SITE_URL || process.env.SITE_URL || "https://www.morancello.com").replace(
      /\/$/,
      ""
    );

    return NextResponse.json({
      success: true,
      orderNumber: order.order_number,
      orderId: order.id,
      receiptUrl: `${siteUrl}/receipt/${order.id}`,
      refunded: refundResult.refunded,
      refundAmount: refundResult.refundAmount || order.total_price || 0,
      message: refundResult.message,
    });
  } catch (err: any) {
    console.error("[WhatsApp Cancel Order API] Server error:", err);
    return NextResponse.json({ success: false, error: err.message }, { status: 500 });
  }
}

