// --- 4. Cancellation Flow ---
async function promptOrderCancellationList(phone, cancellableOrders) {
  // Sort oldest to newest (by created_at or order_number)
  const sorted = [...cancellableOrders].sort((a, b) => {
    const timeA = a.created_at ? new Date(a.created_at).getTime() : 0;
    const timeB = b.created_at ? new Date(b.created_at).getTime() : 0;
    if (timeA && timeB && timeA !== timeB) return timeA - timeB;
    return (a.order_number || 0) - (b.order_number || 0);
  });

  if (sorted.length === 1) {
    const single = sorted[0];
    setSession(phone, {
      ageVerified: true,
      step: "CANCEL_CONFIRM",
      cancelOrderId: single.id,
      cancelOrderNum: single.order_number,
      cancelOrderPrice: single.total_price,
    });
    await sendMessage(
      phone,
      `נמצאה הזמנה #${single.order_number} על סך ${single.total_price} ₪ (${formatStatusHebrew(single.status)}).\nהאם ברצונך לבטל אותה?\n\n1️⃣ כן, אשר ביטול\n2️⃣ לא, חזור לתפריט\n\nהשב 1 או 2:`
    );
    return;
  }

  // Multiple cancellable orders: list from oldest to newest with numbered emojis
  const numberEmojis = ["1️⃣", "2️⃣", "3️⃣", "4️⃣", "5️⃣", "6️⃣", "7️⃣", "8️⃣", "9️⃣", "🔟"];
  const lines = sorted.map((o, idx) => {
    const emoji = numberEmojis[idx] || `${idx + 1}.`;
    return `${emoji} הזמנה #${o.order_number} (${o.total_price} ₪) - ${formatStatusHebrew(o.status)}`;
  });

  setSession(phone, {
    ageVerified: true,
    step: "CANCEL_SELECT",
    cancellableOrders: sorted.map((o) => ({
      id: o.id,
      order_number: o.order_number,
      total_price: o.total_price,
      status: o.status,
    })),
  });

  const msg = `נמצאו ${sorted.length} הזמנות הניתנות לביטול (מהישנה לחדשה):\n\n${lines.join("\n")}\n\nהשב עם מספר האפשרות (למשל 1 או 2) או מספר ההזמנה שברצונך לבטל (או 0 לתפריט):`;
  await sendMessage(phone, msg);
}

async function handleCancellationInquiry(phone) {
  const session = getSession(phone);
  const targetPhone = session?.userPhone || phone;
  const orders = await findOrdersByPhone(targetPhone, session?.pushName);
  if (!orders || orders.length === 0) {
    setSession(phone, { ageVerified: true, step: "CANCEL_LOOKUP" });
    await sendMessage(
      phone,
      `לא נמצאה הזמנה פעילה המשויכת ישירות למספר זה.\n\nאנא הקלד את מספר הטלפון שאיתו ביצעת את ההזמנה או את מספר ההזמנה לביטול (או 0 לתפריט):`
    );
    return;
  }

  const cancellable = orders.filter(
    (o) => o.status !== "shipped" && o.status !== "delivered" && o.status !== "cancelled"
  );

  if (cancellable.length === 0) {
    const hasShipped = orders.some((o) => o.status === "shipped" || o.status === "delivered");
    if (hasShipped) {
      await sendMessage(
        phone,
        `ההזמנה שלך כבר נארזה ויצאה לדרך עם שליח ולא ניתן לבטלה אוטומטית.\nבאפשרותך לפתוח פנייה לשירות לקוחות (הקש 5 בתפריט).`
      );
    } else {
      await sendMessage(phone, `ההזמנה שלך כבר מבוטלת.\nהקש 0 לחזרה לתפריט.`);
    }
    setSession(phone, { ageVerified: true, step: "MAIN_MENU" });
    return;
  }

  await promptOrderCancellationList(phone, cancellable);
}

async function handleCancelSelectInput(phone, text, session) {
  if (text === "0" || text === "תפריט") {
    setSession(phone, { ageVerified: true, step: "MAIN_MENU" });
    await sendMainMenu(phone);
    return;
  }

  const list = session?.cancellableOrders || [];
  if (!list || list.length === 0) {
    await handleCancellationInquiry(phone);
    return;
  }

  const digits = text.replace(/\D/g, "");
  const index = parseInt(digits, 10);
  let selected = null;

  // Check if option index was picked (1..N)
  if (index >= 1 && index <= list.length) {
    selected = list[index - 1];
  } else if (digits) {
    // Check if order number was typed
    selected = list.find((o) => String(o.order_number) === digits || o.id === text.trim());
  }

  if (!selected) {
    await sendMessage(
      phone,
      `אפשרות לא זוהתה. אנא בחר מספר אפשרות (בין 1 ל-${list.length}) או מספר הזמנה לביטול (או 0 לתפריט):`
    );
    return;
  }

  setSession(phone, {
    ageVerified: true,
    step: "CANCEL_CONFIRM",
    cancelOrderId: selected.id,
    cancelOrderNum: selected.order_number,
    cancelOrderPrice: selected.total_price,
  });

  await sendMessage(
    phone,
    `בחרת לבטל את הזמנה #${selected.order_number} על סך ${selected.total_price} ₪.\nהאם אתה בטוח שברצונך לבטל אותה?\n\n1️⃣ כן, אשר ביטול\n2️⃣ לא, חזור לתפריט\n\nהשב 1 או 2:`
  );
}

async function handleCancelLookupInput(phone, text) {
  if (text === "0" || text === "תפריט") {
    setSession(phone, { ageVerified: true, step: "MAIN_MENU" });
    await sendMainMenu(phone);
    return;
  }

  const digitsOnly = text.replace(/\D/g, "");
  if (!digitsOnly) {
    await sendMessage(phone, `אנא הקלד מספר טלפון או מספר הזמנה (או 0 לתפריט):`);
    return;
  }

  // Check by phone
  if (digitsOnly.length >= 7) {
    const orders = await findOrdersByPhone(digitsOnly);
    if (orders && orders.length > 0) {
      const cancellable = orders.filter(
        (o) => o.status !== "shipped" && o.status !== "delivered" && o.status !== "cancelled"
      );
      if (cancellable.length > 0) {
        await promptOrderCancellationList(phone, cancellable);
        return;
      }
      const hasShipped = orders.some((o) => o.status === "shipped" || o.status === "delivered");
      if (hasShipped) {
        await sendMessage(
          phone,
          `ההזמנה שלך כבר נארזה ויצאה לדרך עם שליח ולא ניתן לבטלה אוטומטית.\nבאפשרותך לפתוח פנייה לשירות לקוחות (הקש 5 בתפריט).`
        );
      } else {
        await sendMessage(phone, `ההזמנה שלך כבר מבוטלת.\nהקש 0 לחזרה לתפריט.`);
      }
      setSession(phone, { ageVerified: true, step: "MAIN_MENU" });
      return;
    }
  }

  // Check by order number
  const orderNum = parseInt(digitsOnly, 10);
  if (orderNum) {
    const order = await findOrderByNumber(orderNum);
    if (order) {
      if (order.status === "shipped" || order.status === "delivered") {
        await sendMessage(
          phone,
          `הזמנה #${order.order_number} כבר נארזה ויצאה לדרך עם שליח ולא ניתן לבטלה אוטומטית.\nבאפשרותך לפתוח פנייה לשירות לקוחות (הקש 5 בתפריט).`
        );
        setSession(phone, { ageVerified: true, step: "MAIN_MENU" });
        return;
      }
      if (order.status === "cancelled") {
        await sendMessage(phone, `הזמנה #${order.order_number} כבר מבוטלת.\nהקש 0 לחזרה לתפריט.`);
        setSession(phone, { ageVerified: true, step: "MAIN_MENU" });
        return;
      }
      await promptOrderCancellationList(phone, [order]);
      return;
    }
  }

  await sendMessage(
    phone,
    `ההזמנה לא נמצאה במערכת. אנא ודא את מספר הטלפון או מספר ההזמנה, או הקש 0 לתפריט:`
  );
}

async function handleCancelConfirm(phone, text, session) {
  if (text === "1") {
    const orderId = session.cancelOrderId;
    const orderNum = session.cancelOrderNum;
    const siteUrl = (process.env.SITE_URL || "https://www.morancello.com").replace(/\/$/, "");
    let cancelData = null;

    // Call authoritative cancel-order API: handles status, Meshulam refund, inventory restoration, and backorder queue
    try {
