// --- 4. Cancellation Flow ---
async function handleCancellationInquiry(phone) {
  const session = getSession(phone);
  const targetPhone = session?.userPhone || phone;
  const orders = await findOrdersByPhone(targetPhone, session?.pushName);
  if (!orders || orders.length === 0) {
    setSession(phone, { ageVerified: true, step: "CANCEL_LOOKUP" });
    await sendMessage(
      phone,
      `לא נמצאה הזמנה פעילה המשויכת ישירות למספר זה.\n\nאנא הקלד את מספר הטלפון שאיתו ביצעת את ההזמנה או את מספר ההזמנה לביטול (או 0 לתפריט):`
    );
    return;
  }

  const latest = orders[0];
  if (latest.status === "shipped" || latest.status === "delivered") {
    await sendMessage(
      phone,
      `הזמנה #${latest.order_number} כבר נארזה ויצאה לדרך עם שליח ולא ניתן לבטלה אוטומטית.\nבאפשרותך לפתוח פנייה לשירות לקוחות (הקש 5 בתפריט).`
    );
    return;
  }

  if (latest.status === "cancelled") {
    await sendMessage(phone, `הזמנה #${latest.order_number} כבר מבוטלת.\nהקש 0 לחזרה לתפריט.`);
    return;
  }

  setSession(phone, {
    ageVerified: true,
    step: "CANCEL_CONFIRM",
    cancelOrderId: latest.id,
    cancelOrderNum: latest.order_number,
    cancelOrderPrice: latest.total_price,
  });

  await sendMessage(
    phone,
    `נמצאה הזמנה #${latest.order_number} על סך ${latest.total_price} ₪.\nהאם ברצונך לבטל אותה?\n\n1️⃣ כן, אשר ביטול\n2️⃣ לא, חזור לתפריט\n\nהשב 1 או 2:`
  );
}

async function handleCancelLookupInput(phone, text) {
  const digitsOnly = text.replace(/\D/g, "");
  let targetOrder = null;

  if (digitsOnly.length >= 9 || (digitsOnly.length >= 7 && digitsOnly.startsWith("0"))) {
    const orders = await findOrdersByPhone(digitsOnly);
    if (orders && orders.length > 0) targetOrder = orders[0];
  } else {
    const orderNum = parseInt(digitsOnly, 10);
    if (orderNum) {
      const order = await findOrderByNumber(orderNum);
      if (order) targetOrder = order;
    }
  }

  if (!targetOrder) {
    await sendMessage(
      phone,
      `ההזמנה לא נמצאה במערכת. אנא ודא את מספר הטלפון או מספר ההזמנה, או הקש 0 לתפריט:`
    );
    return;
  }

  if (targetOrder.status === "shipped" || targetOrder.status === "delivered") {
    await sendMessage(
      phone,
      `הזמנה #${targetOrder.order_number} כבר נארזה ויצאה לדרך ולא ניתן לבטלה אוטומטית.\nבאפשרותך לפתוח פנייה לשירות לקוחות (הקש 5 בתפריט).`
    );
    setSession(phone, { ageVerified: true, step: "MAIN_MENU" });
    return;
  }

  if (targetOrder.status === "cancelled") {
    await sendMessage(phone, `הזמנה #${targetOrder.order_number} כבר מבוטלת.\nהקש 0 לחזרה לתפריט.`);
    setSession(phone, { ageVerified: true, step: "MAIN_MENU" });
    return;
  }

  setSession(phone, {
    ageVerified: true,
    step: "CANCEL_CONFIRM",
    cancelOrderId: targetOrder.id,
    cancelOrderNum: targetOrder.order_number,
    cancelOrderPrice: targetOrder.total_price,
  });

  await sendMessage(
    phone,
    `נמצאה הזמנה #${targetOrder.order_number} על סך ${targetOrder.total_price} ₪.\nהאם ברצונך לבטל אותה?\n\n1️⃣ כן, אשר ביטול\n2️⃣ לא, חזור לתפריט\n\nהשב 1 או 2:`
  );
}

async function handleCancelConfirm(phone, text, session) {
  if (text === "1") {
    const orderId = session.cancelOrderId;
    const siteUrl = (process.env.SITE_URL || "https://www.morancello.com").replace(/\/$/, "");
    const token =
      process.env.SUPABASE_SERVICE_ROLE_KEY ||
      process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY ||
      "[REDACTED_SUPABASE_ANON_KEY]";

    try {
      const res = await fetch(`${siteUrl}/api/admin/orders`, {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          action: "update_status",
          orderId,
          status: "cancelled",
        }),
      });
      if (res.ok) {
        const json = await res.json();
        if (json.success) {
          await sendMessage(
            phone,
            `הזמנה #${session.cancelOrderNum} בוטלה בהצלחה.\n\n${CLOSING_MOTTO}`
          );
          setSession(phone, { ageVerified: true, step: "MAIN_MENU" });
          return;
        }
      }
    } catch (e) {
      console.error("[WhatsApp Bot] Error cancelling order via API:", e.message);
    }

    const nowStr = new Date().toLocaleString("he-IL");
    await supabase
      .from("orders")
      .update({
        status: "cancelled",
        admin_notes: `בוטל לבקשת הלקוח בוואטסאפ בתאריך ${nowStr}`,
      })
      .eq("id", orderId);

    await sendMessage(
      phone,
      `הזמנה #${session.cancelOrderNum} בוטלה בהצלחה.\n\n${CLOSING_MOTTO}`
    );
    setSession(phone, { ageVerified: true, step: "MAIN_MENU" });
  } else {
    await sendMessage(phone, `הביטול לא בוצע. חזרת לתפריט הראשי.`);
    setSession(phone, { ageVerified: true, step: "MAIN_MENU" });
    await sendMainMenu(phone);
  }
}

