import { createClient } from "@supabase/supabase-js";
import { encrypt } from "@/lib/encryption";
import { fetchSetting } from "@/app/actions/settings";

export const dynamic = "force-dynamic";
export const revalidate = 0;

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL || "https://tmcrncmzzakvimyptoyh.supabase.co";
const supabaseServiceKey =
  process.env.SUPABASE_SERVICE_ROLE_KEY ||
  process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY ||
  "[REDACTED_SUPABASE_ANON_KEY]";

const supabaseAdmin = createClient(supabaseUrl, supabaseServiceKey);

function isAuthorized(req: Request): boolean {
  const authHeader = req.headers.get("authorization") || req.headers.get("x-admin-key") || "";
  const token = authHeader.replace(/^Bearer\s+/i, "").trim();
  if (!token) return false;

  const validTokens = [
    process.env.SUPABASE_SERVICE_ROLE_KEY,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY,
    process.env.ADMIN_API_KEY,
    "[REDACTED_SUPABASE_ANON_KEY]",
  ].filter(Boolean);

  return validTokens.includes(token);
}

export async function POST(req: Request) {
  if (!isAuthorized(req)) {
    return NextResponse.json({ success: false, error: "Unauthorized" }, { status: 401 });
  }

  try {
    const body = await req.json();
    const {
      name,
      phone,
      email,
      quantity,
      pickup,
      address,
      shippingProvider,
      shippingCost = 0,
      totalPrice,
    } = body;

    const numQty = parseInt(String(quantity), 10) || 1;
    const cleanPhone = (phone || "").replace(/\D/g, "");

    if (!cleanPhone || numQty < 1) {
      return NextResponse.json(
        { success: false, error: "Missing required fields (phone, quantity)" },
        { status: 400 }
      );
    }

    // 1. Fetch active product and check live inventory
    const { data: product } = await supabaseAdmin
      .from("products")
      .select(`
        id,
        name,
        price,
        inventory (
          physical_quantity,
          reserved_quantity
        )
      `)
      .eq("is_active", true)
      .order("created_at", { ascending: true })
      .limit(1)
      .maybeSingle();

    const productId = product?.id || "00000000-0000-0000-0000-000000000001";
    const inv = Array.isArray(product?.inventory) ? product.inventory[0] : product?.inventory;
    const physicalQty = inv?.physical_quantity || 0;
    const reservedQty = inv?.reserved_quantity || 0;
    const availableStock = physicalQty - reservedQty;

    const isBackorder = availableStock < numQty;
    const initialStatus = isBackorder ? "backorder_pending" : "pending";

    const unitPrice = product?.price || 122;
    const calculatedTotal = totalPrice || numQty * unitPrice + (shippingCost || 0);

    // 2. Encrypt PII
    const customerName = name || "לקוח וואטסאפ";
    const customerEmail = email || `${cleanPhone}@whatsapp.morancello.com`;
    const encryptedName = encrypt(customerName);
    const encryptedPhone = encrypt(cleanPhone);
    const encryptedEmail = encrypt(customerEmail);
    const encryptedAddress = address ? encrypt(address) : null;

    // 3. Insert order
    const { data: newOrder, error: orderErr } = await supabaseAdmin
      .from("orders")
      .insert({
        customer_name: encryptedName,
        customer_phone: encryptedPhone,
        customer_email: encryptedEmail,
        pickup_method: pickup || "delivery",
        delivery_address: encryptedAddress,
        shipping_provider: shippingProvider || null,
        shipping_cost: shippingCost || 0,
        total_price: calculatedTotal,
        status: initialStatus,
        admin_notes: `נוצר דרך בוט WhatsApp בתאריך ${new Date().toLocaleDateString("he-IL")}${
          isBackorder ? " (הרשמה עתידית - ממתין למלאי)" : ""
        }`,
      })
      .select("id, order_number, status, total_price")
      .single();

    if (orderErr || !newOrder) {
      console.error("[WhatsApp Create Order API] Insert error:", orderErr);
      return NextResponse.json({ success: false, error: orderErr?.message || "Failed to create order" }, { status: 500 });
    }

    // 4. Insert order_items
    await supabaseAdmin.from("order_items").insert({
      order_id: newOrder.id,
      product_id: productId,
      quantity: numQty,
      price_at_purchase: unitPrice,
    });

    // 5. UPDATE INVENTORY ACCORDING TO POLICY:
    // Call recalculateReservedInventory to immediately reflect the new reservation
    try {
      const { recalculateReservedInventory } = await import("@/app/actions/adminInventory");
      await recalculateReservedInventory();
    } catch (invErr) {
      console.error("[WhatsApp Create Order API] Error recalculating reserved inventory:", invErr);
    }

    // Process backorder queue if applicable
    try {
      const { processBackorderQueue } = await import("@/app/actions/backorderQueue");
      await processBackorderQueue();
    } catch (qErr) {
      console.error("[WhatsApp Create Order API] Error processing backorder queue:", qErr);
    }

    // 6. Trigger Admin Mobile Push Notification
    try {
      const { sendAdminPushNotification } = await import("@/lib/pushNotifications");
      await sendAdminPushNotification({
        title: isBackorder
          ? `הזמנה עתידית חדשה #${newOrder.order_number} 📦`
          : `הזמנה חדשה #${newOrder.order_number} 🍋`,
        body: `${customerName}: ${numQty} בקבוקים (${calculatedTotal} ₪)`,
        data: { action: "WIDGET_RELOAD", orderId: newOrder.id },
      });
    } catch (e) {}

    // 7. Generate Checkout & Payment URL
    const siteUrl = (
      process.env.NEXT_PUBLIC_SITE_URL ||
      process.env.SITE_URL ||
      "https://www.morancello.com"
    ).replace(/\/$/, "");

    const checkoutUrl = `${siteUrl}/checkout?orderId=${newOrder.id}`;

    // Pre-create direct Meshulam payment URL if available
    let directPaymentUrl: string | null = null;
    try {
      const isSandboxSetting = await fetchSetting("meshulam_is_sandbox");
      const isSandbox = isSandboxSetting !== "false";
      const pageCode = await fetchSetting("meshulam_page_code");
      const apiKey = await fetchSetting("meshulam_api_key");

      if (pageCode && apiKey) {
        const baseUrl = isSandbox
          ? "https://sandbox.meshulam.co.il/api/light/server/1.0/createPaymentProcess"
          : "https://meshulam.co.il/api/light/server/1.0/createPaymentProcess";

        const params = new URLSearchParams();
        params.append("pageCode", pageCode);
        params.append("userId", apiKey);
        params.append("sum", String(calculatedTotal));
        params.append("successUrl", `${siteUrl}/api/meshulam/iframe-success?orderId=${newOrder.id}&payment=success`);
        params.append("cancelUrl", `${siteUrl}/api/meshulam/iframe-success?orderId=${newOrder.id}&payment=cancel`);
        params.append("notifyUrl", `${siteUrl}/api/meshulam/webhook`);
        params.append("description", `הזמנה ${newOrder.order_number} - מורנצ'לו`);
        params.append("cField1", newOrder.id);

        const mRes = await fetch(baseUrl, {
          method: "POST",
          headers: { "Content-Type": "application/x-www-form-urlencoded" },
          body: params.toString(),
        });
        const mText = await mRes.text();
        let mJson;
        try { mJson = JSON.parse(mText); } catch (e) {}

        if (mJson && mJson.status > 0) {
          directPaymentUrl = mJson.data?.url || mJson.url;
        }
      }
    } catch (mErr) {
      console.warn("[WhatsApp Create Order API] Meshulam pre-init warning:", mErr);
    }

    return NextResponse.json({
      success: true,
      order: {
        id: newOrder.id,
        order_number: newOrder.order_number,
        total_price: newOrder.total_price,
        status: newOrder.status,
      },
      checkoutUrl,
      paymentUrl: directPaymentUrl || checkoutUrl,
      isBackorder,
    });
  } catch (err: any) {
    console.error("[WhatsApp Create Order API] Exception:", err);
    return NextResponse.json({ success: false, error: err.message }, { status: 500 });
  }
}

