import React from "react";
import type { Metadata } from "next";
import Image from "next/image";
import Link from "next/link";
import { createClient } from "@supabase/supabase-js";
import { decrypt } from "@/lib/encryption";
import { fetchSetting } from "@/app/actions/settings";
import CheckoutPaymentClient from "./CheckoutPaymentClient";
import { ArrowRight, CheckCircle2, AlertCircle, FileText, Package, Truck, ShieldCheck } from "lucide-react";

export const dynamic = "force-dynamic";
export const revalidate = 0;

export const metadata: Metadata = {
  title: "השלמת תשלום | מורנצ׳לו",
  description: "השלמת תשלום מאובטח עבור הזמנת מורנצ׳לו - לזכרה של מורן וייס",
};

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL || "https://tmcrncmzzakvimyptoyh.supabase.co";
const supabaseServiceKey =
  process.env.SUPABASE_SERVICE_ROLE_KEY ||
  process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY ||
  "[REDACTED_SUPABASE_ANON_KEY]";

const supabaseAdmin = createClient(supabaseUrl, supabaseServiceKey);

export default async function CheckoutPage({
  searchParams,
}: {
  searchParams?: Promise<{ orderId?: string; order_id?: string; orderNumber?: string }>;
}) {
  const resolvedParams = searchParams ? await searchParams : {};
  const rawId = resolvedParams.orderId || resolvedParams.order_id || resolvedParams.orderNumber || "";

  if (!rawId) {
    return (
      <div className="min-h-screen bg-[#FDFBF7] py-12 px-4 flex flex-col items-center justify-center text-right font-sans" dir="rtl">
        <div className="max-w-md w-full bg-white p-8 rounded-3xl shadow-sm border border-amber-100 text-center space-y-4">
          <div className="w-16 h-16 mx-auto relative bg-amber-50 rounded-full p-2">
            <Image src="/moran-redrawn-v2.png" alt="Morancello" fill className="object-contain p-2" />
          </div>
          <h1 className="text-2xl font-bold text-gray-900 font-serif">השלמת תשלום להזמנה 🍋</h1>
          <p className="text-sm text-gray-500">
            לא צוין מספר הזמנה לתשלום. אנא לחצו על הקישור שקיבלתם בוואטסאפ או חזרו לדף הבית.
          </p>
          <div className="pt-2">
            <Link
              href="/"
              className="inline-flex items-center gap-2 px-6 py-3 bg-amber-600 hover:bg-amber-700 text-white font-bold rounded-xl text-sm transition-all shadow-md"
            >
              <ArrowRight size={16} /> מעבר לדף הבית
            </Link>
          </div>
        </div>
      </div>
    );
  }

  // Look up order by UUID or order_number
  const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(rawId);
  let query = supabaseAdmin
    .from("orders")
    .select(`
      id,
      order_number,
      customer_name,
      customer_phone,
      total_price,
      shipping_cost,
      pickup_method,
      delivery_address,
      status,
      created_at,
      order_items (
        quantity,
        price_at_purchase
      )
    `);

  if (isUuid) {
    query = query.eq("id", rawId);
  } else {
    const numId = parseInt(rawId.replace(/\D/g, ""), 10);
    if (!isNaN(numId) && numId > 0) {
      query = query.eq("order_number", numId);
    } else {
      query = query.eq("id", rawId);
    }
  }

  const { data: order, error } = await query.maybeSingle();

  if (error || !order) {
    return (
      <div className="min-h-screen bg-[#FDFBF7] py-12 px-4 flex flex-col items-center justify-center text-right font-sans" dir="rtl">
        <div className="max-w-md w-full bg-white p-8 rounded-3xl shadow-sm border border-amber-100 text-center space-y-4">
          <div className="w-16 h-16 mx-auto bg-red-50 text-red-500 rounded-full flex items-center justify-center">
            <AlertCircle size={32} />
          </div>
          <h1 className="text-xl font-bold text-gray-900 font-serif">ההזמנה לא נמצאה במערכת</h1>
          <p className="text-sm text-gray-500">
            לא הצלחנו למצוא הזמנה התואמת למספר שסופק. ודאו את הקישור או פנו לשירות הלקוחות שלנו.
          </p>
          <div className="pt-2">
            <Link
              href="/"
              className="inline-flex items-center gap-2 px-6 py-3 bg-amber-600 hover:bg-amber-700 text-white font-bold rounded-xl text-sm transition-all shadow-md"
            >
              <ArrowRight size={16} /> חזרה לדף הבית
            </Link>
          </div>
        </div>
      </div>
    );
  }

  // Decrypt customer name and delivery address
  let cleanName = order.customer_name || "";
  let cleanAddress = order.delivery_address || "";
  try { cleanName = decrypt(order.customer_name) || order.customer_name; } catch (e) {}
  try { cleanAddress = decrypt(order.delivery_address) || order.delivery_address; } catch (e) {}

  const totalQuantity =
    order.order_items?.reduce((sum: number, item: any) => sum + (item.quantity || 0), 0) || 1;

  const isPaid = ["paid", "shipped", "delivered"].includes(order.status);
