"use client";

import React, { useState, useEffect } from "react";
import { CreditCard, Loader2, Smartphone, ShieldCheck, ArrowRight, ExternalLink } from "lucide-react";

interface CheckoutPaymentClientProps {
  orderId: string;
  orderNumber?: number;
  totalPrice: number;
  paymentProvider: string;
  paymentPhoneNumber: string;
}

export default function CheckoutPaymentClient({
  orderId,
  orderNumber,
  totalPrice,
  paymentProvider,
  paymentPhoneNumber,
}: CheckoutPaymentClientProps) {
  const [meshulamUrl, setMeshulamUrl] = useState<string | null>(null);
  const [loading, setLoading] = useState<boolean>(false);
  const [errorMsg, setErrorMsg] = useState<string>("");
  const [selectedMethod, setSelectedMethod] = useState<"card" | "bit" | "paybox">("card");

  const initMeshulamPayment = async () => {
    setLoading(true);
    setErrorMsg("");
    try {
      const res = await fetch("/api/meshulam/create", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          orderId,
          amount: totalPrice,
          description: `הזמנה #${orderNumber || orderId.substring(0, 8)} - מורנצ׳לו`,
        }),
      });

      const data = await res.json();
      if (data.url) {
        setMeshulamUrl(data.url);
      } else {
        setErrorMsg(data.error || "לא ניתן היה ליצור דף סליקה מאובטח. ניתן לשלם דרך Bit או Paybox.");
      }
    } catch (e: any) {
      setErrorMsg("אירעה שגיאה בחיבור לשרת התשלומים. ניתן להשלים תשלום ב-Bit.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (paymentProvider === "meshulam") {
      initMeshulamPayment();
    }
  }, [orderId, paymentProvider]);

  return (
    <div className="space-y-4 pt-2 border-t border-gray-100">
      <div className="text-center space-y-1">
        <h3 className="font-bold text-base text-gray-900">בחר אמצעי תשלום להשלמת ההזמנה</h3>
        <p className="text-xs text-gray-500">
          המלאי עבור הזמנתך שוריין במערכת. אנא השלם את התשלום להבטחת ההזמנה.
        </p>
      </div>

      {/* Tabs */}
      <div className="grid grid-cols-2 gap-2 p-1 bg-gray-100 rounded-2xl">
        <button
          type="button"
          onClick={() => setSelectedMethod("card")}
          className={`py-2 px-3 rounded-xl text-xs font-bold transition-all flex items-center justify-center gap-2 ${
            selectedMethod === "card"
              ? "bg-white text-amber-700 shadow-sm"
              : "text-gray-600 hover:text-gray-900"
          }`}
        >
          <CreditCard size={15} />
          <span>אשראי / Bit / Apple Pay</span>
        </button>

        <button
          type="button"
          onClick={() => setSelectedMethod("bit")}
          className={`py-2 px-3 rounded-xl text-xs font-bold transition-all flex items-center justify-center gap-2 ${
            selectedMethod === "bit"
              ? "bg-white text-emerald-700 shadow-sm"
              : "text-gray-600 hover:text-gray-900"
          }`}
        >
          <Smartphone size={15} />
          <span>העברה ב-Bit ישיר</span>
        </button>
      </div>

      {/* 1. Meshulam iFrame / Payment Button */}
      {selectedMethod === "card" && (
        <div className="space-y-3">
          {loading && (
            <div className="py-12 flex flex-col items-center justify-center text-center space-y-3 bg-amber-50/50 rounded-2xl border border-amber-100">
              <Loader2 size={32} className="animate-spin text-amber-600" />
              <div className="text-xs font-semibold text-gray-700">טוען מסוף תשלום מאובטח...</div>
            </div>
          )}

          {errorMsg && (
            <div className="p-3 bg-red-50 border border-red-100 rounded-xl text-xs text-red-600 text-center">
              {errorMsg}
            </div>
          )}

          {meshulamUrl && !loading && (
            <div className="space-y-3">
              <div className="rounded-2xl overflow-hidden border border-gray-200 bg-white shadow-sm">
                <iframe
                  src={meshulamUrl}
                  className="w-full h-[580px] border-0"
                  title="מסוף תשלום מורנצ׳לו"
                  allow="payment"
                />
              </div>

              <div className="text-center">
                <a
                  href={meshulamUrl}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="inline-flex items-center gap-1.5 text-xs text-amber-700 font-semibold hover:underline"
                >
                  נפתח בחלון נפרד? לחץ כאן לפתיחה במסך מלא <ExternalLink size={13} />
                </a>
              </div>
            </div>
          )}

          {!meshulamUrl && !loading && !errorMsg && (
            <button
              onClick={initMeshulamPayment}
              className="w-full bg-amber-600 hover:bg-amber-700 text-white font-bold py-3.5 px-6 rounded-2xl transition-all shadow-md flex items-center justify-center gap-2 text-sm"
            >
              <CreditCard size={18} /> לחץ כאן לפתיחת מסוף תשלום ({totalPrice} ₪)
            </button>
          )}
        </div>
      )}

      {/* 2. Direct Bit / Manual Transfer */}
      {selectedMethod === "bit" && (
        <div className="p-5 bg-emerald-50/70 border border-emerald-200 rounded-2xl space-y-4 text-emerald-950">
          <div className="flex items-center gap-2 font-bold text-sm text-emerald-900">
            <Smartphone size={18} className="text-emerald-600" />
            תשלום ישיר ב-Bit לנייד
          </div>

          <div className="text-xs space-y-2 text-emerald-800">
            <p>1. שלח/י את הסכום המדויק: <strong>{totalPrice} ₪</strong></p>
            <p>2. מספר הנייד להעברה: <strong className="text-sm font-mono tracking-wider">{paymentPhoneNumber}</strong> (מורנצ׳לו 🍋)</p>
            <p>3. בצירוף הערה ב-Bit: <strong>הזמנה #{orderNumber || orderId.substring(0, 8)}</strong></p>
          </div>

          <div className="pt-2">
            <a
              href={`tel:${paymentPhoneNumber}`}
              className="w-full bg-emerald-600 hover:bg-emerald-700 text-white font-bold py-3 px-4 rounded-xl text-center block text-xs shadow-sm transition-all"
            >
              העתק / חייג למספר: {paymentPhoneNumber}
            </a>
          </div>

          <div className="text-[11px] text-gray-500 text-center italic">
            עם קבלת ההעברה ב-Bit, ההזמנה תסומן אוטומטית כשולמה ותישלח אליך חשבונית/קבלה בוואטסאפ ובמייל.
          </div>
        </div>
      )}
    </div>
  );
}

