if (action === "update_status") {
  const { ticketId, status } = body;
  const allTickets = await getTicketsFromStore();
  const ticket = allTickets.find((t) => t.id === ticketId || String(t.ticket_number) === String(ticketId));
  if (!ticket) {
    return NextResponse.json({ success: false, error: "Ticket not found" }, { status: 404 });
  }

  const nowIso = new Date().toISOString();
  ticket.status = status;
  ticket.updated_at = nowIso;

  try {
    await supabaseAdmin
      .from("support_tickets")
      .update({ status, updated_at: nowIso })
      .eq("id", ticket.id);
  } catch (e) {}

  await saveTicketsToStore(allTickets);
  return NextResponse.json({ success: true, ticket });
}

if (action === "delete") {
  const { ticketId } = body;
  if (!ticketId) {
    return NextResponse.json({ success: false, error: "Missing ticketId" }, { status: 400 });
  }

  try {
    await supabaseAdmin.from("ticket_messages").delete().eq("ticket_id", ticketId);
    await supabaseAdmin.from("support_tickets").delete().eq("id", ticketId);
  } catch (e) {}

  const allTickets = await getTicketsFromStore();
  const filtered = allTickets.filter((t) => t.id !== ticketId && String(t.ticket_number) !== String(ticketId));
  await saveTicketsToStore(filtered);

  return NextResponse.json({ success: true });
}

if (action === "cleanup_resolved") {
  const days = parseInt(body.days, 10);
  if (isNaN(days) || days <= 0) {
    return NextResponse.json({ success: true, count: 0, message: "No cleanup threshold specified" });
  }

  const cutoffMs = Date.now() - days * 24 * 60 * 60 * 1000;
  const cutoffDate = new Date(cutoffMs).toISOString();
  let deletedCount = 0;

  try {
    const { data: toDelete } = await supabaseAdmin
      .from("support_tickets")
      .select("id")
      .in("status", ["resolved", "closed"])
      .lte("updated_at", cutoffDate);

    if (toDelete && toDelete.length > 0) {
      const ids = toDelete.map((t: any) => t.id);
      await supabaseAdmin.from("ticket_messages").delete().in("ticket_id", ids);
      await supabaseAdmin.from("support_tickets").delete().in("id", ids);
      deletedCount = ids.length;
    }
  } catch (e) {}

  const allTickets = await getTicketsFromStore();
  const remaining = allTickets.filter((t) => {
    if (t.status === "resolved" || t.status === "closed") {
      const tTime = new Date(t.updated_at || t.created_at).getTime();
      if (tTime && tTime < cutoffMs) {
        deletedCount++;
        return false;
      }
    }
    return true;
  });
  await saveTicketsToStore(remaining);

  return NextResponse.json({ success: true, count: deletedCount });
}

return NextResponse.json({ success: false, error: "Unknown action" }, { status: 400 });

