export async function deleteSupportTicket(
  ticketId: string
): Promise<{ success: boolean; error?: string }> {
  try {
    const settings = await loadAppSettings();
    const serverUrl = settings.serverUrl || 'https://www.morancello.com';
    const apiUrl = `${serverUrl.replace(/\/$/, '')}/api/admin/tickets`;

    const res = await fetch(apiUrl, {
      method: 'POST',
      headers: getApiHeaders(settings),
      body: JSON.stringify({
        action: 'delete',
        ticketId,
      }),
    });

    const data = await res.json();
    return data;
  } catch (e: any) {
    logError('SUPPORT_TICKETS', 'Failed to delete ticket', e);
    return { success: false, error: e?.message || 'שגיאה במחיקת פנייה' };
  }
}

export async function cleanupResolvedTickets(
  days: number
): Promise<{ success: boolean; count?: number; error?: string }> {
  try {
    const settings = await loadAppSettings();
    const serverUrl = settings.serverUrl || 'https://www.morancello.com';
    const apiUrl = `${serverUrl.replace(/\/$/, '')}/api/admin/tickets`;

    const res = await fetch(apiUrl, {
      method: 'POST',
      headers: getApiHeaders(settings),
      body: JSON.stringify({
        action: 'cleanup_resolved',
        days,
      }),
    });

    const data = await res.json();
    return data;
  } catch (e: any) {
    logError('SUPPORT_TICKETS', 'Failed to cleanup resolved tickets', e);
    return { success: false, error: e?.message || 'שגיאה בניקוי פניות ישנות' };
  }
}

export async function getReadTicketIds(): Promise<string[]> {
  try {
    const val = await AsyncStorage.getItem(STORAGE_KEY_READ_TICKETS);
    if (val) {
      return JSON.parse(val);
    }
  } catch (e) {}
  return [];
}

export async function markTicketAsRead(ticketId: string): Promise<string[]> {
  try {
    const current = await getReadTicketIds();
    if (!current.includes(ticketId)) {
      const updated = [...current, ticketId];
      await AsyncStorage.setItem(STORAGE_KEY_READ_TICKETS, JSON.stringify(updated));
      return updated;
    }
    return current;
  } catch (e) {
    return [];
  }
}

export async function getAlertedTicketIds(): Promise<string[]> {
  try {
    const val = await AsyncStorage.getItem(STORAGE_KEY_ALERTED_TICKETS);
    if (val) {
      return JSON.parse(val);
    }
  } catch (e) {}
  return [];
}

export async function markTicketAsAlerted(ticketId: string): Promise<string[]> {
  try {
    const current = await getAlertedTicketIds();
    if (!current.includes(ticketId)) {
      const updated = [...current, ticketId];
      await AsyncStorage.setItem(STORAGE_KEY_ALERTED_TICKETS, JSON.stringify(updated));
      return updated;
    }
    return current;
  } catch (e) {
    return [];
  }
}

export async function createTicketReminder(data: {
  ticketId: string;
  ticketNumber: number | string;
  customerName?: string;
  customerPhone?: string;
  dueTimestamp: number;
  customReasonText?: string;
}) {
  return await createOrderReminder({
    ticketId: data.ticketId,
    ticketNumber: data.ticketNumber,
    targetType: 'ticket',
    customerName: data.customerName,
    customerPhone: data.customerPhone,
    reasonType: 'ticket_followup',
    customReasonText: data.customReasonText || `מענה לפנייה #T-${data.ticketNumber}`,
    dueTimestamp: data.dueTimestamp,
  });
}

