  TouchableWithoutFeedback,
  Platform,
} from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { SupportTicket } from '../services/supportTickets';

interface NewTicketAlertModalProps {
  visible: boolean;
  ticket: SupportTicket | null;
  onClose: () => void;
  onOpenTicket: (ticket: SupportTicket) => void;
}

export const NewTicketAlertModal: React.FC<NewTicketAlertModalProps> = ({
  visible,
  ticket,
  onClose,
  onOpenTicket,
}) => {
  if (!ticket) return null;

  return (
    <Modal
      visible={visible}
      transparent
      animationType="fade"
      onRequestClose={onClose}
