import React, { useRef, useEffect } from 'react';
import { View, Text, StyleSheet, TouchableOpacity, Animated } from 'react-native';
import { Ionicons } from '@expo/vector-icons';

interface HeaderProps {
  title: string;
  subtitle?: string;
  activeTab: 'home' | 'orders' | 'support' | 'settings';
  onTabChange: (tab: 'home' | 'orders' | 'support' | 'settings') => void;
  onRefresh?: () => void;
  dueRemindersCount?: number;
  onOpenRemindersModal?: () => void;
  hasUnreadTickets?: boolean;
  unreadTicketsCount?: number;
}

export const Header: React.FC<HeaderProps> = ({
  title,
  subtitle,
  activeTab,
  onTabChange,
  onRefresh,
  dueRemindersCount = 0,
  onOpenRemindersModal,
  hasUnreadTickets = false,
  unreadTicketsCount = 0,
}) => {
  const pulseAnim = useRef(new Animated.Value(0)).current;

  useEffect(() => {
    if (hasUnreadTickets) {
      const loop = Animated.loop(
        Animated.sequence([
          Animated.timing(pulseAnim, {
            toValue: 1,
            duration: 600,
            useNativeDriver: false,
          }),
          Animated.timing(pulseAnim, {
            toValue: 0,
            duration: 600,
            useNativeDriver: false,
          }),
        ])
      );
      loop.start();
      return () => loop.stop();
    } else {
      pulseAnim.setValue(0);
    }
  }, [hasUnreadTickets]);

  const animatedSupportBg = pulseAnim.interpolate({
    inputRange: [0, 1],
    outputRange: activeTab === 'support' ? ['#D97706', '#EF4444'] : ['#F9FAFB', '#FEE2E2'],
  });

  const animatedSupportBorder = pulseAnim.interpolate({
    inputRange: [0, 1],
    outputRange: ['rgba(239, 68, 68, 0)', 'rgba(239, 68, 68, 1)'],
  });

  const animatedScale = pulseAnim.interpolate({
    inputRange: [0, 0.5, 1],
    outputRange: [1, 1.06, 1],
  });

  const animatedDotOpacity = pulseAnim.interpolate({
    inputRange: [0, 0.5, 1],
    outputRange: [0.3, 1, 0.3],
  });

  return (
    <View style={styles.container}>
      <View style={styles.topRow}>
        <View style={styles.titleContainer}>
          <Text style={styles.brandTitle}>מורנצ׳לו 🍋</Text>
          <Text style={styles.subtitle}>{subtitle || 'אפליקציית ניהול מובייל'}</Text>
        </View>

        <View style={styles.topActionsRow}>
          {onOpenRemindersModal && (
            <TouchableOpacity onPress={onOpenRemindersModal} style={styles.bellButton}>
              <Ionicons
                name={dueRemindersCount > 0 ? 'notifications' : 'notifications-outline'}
                size={20}
                color={dueRemindersCount > 0 ? '#EF4444' : '#D97706'}
              />
              {dueRemindersCount > 0 && (
                <View style={styles.headerBadge}>
                  <Text style={styles.headerBadgeText}>
                    {dueRemindersCount > 9 ? '9+' : dueRemindersCount}
                  </Text>
                </View>
              )}
            </TouchableOpacity>
          )}

          {onRefresh && (
            <TouchableOpacity onPress={onRefresh} style={styles.refreshButton}>
              <Ionicons name="refresh-outline" size={20} color="#D97706" />
            </TouchableOpacity>
          )}
        </View>
      </View>

      <View style={styles.navRow}>
        <TouchableOpacity
