import {
  SupportTicket,
  fetchSupportTickets,
  replyToSupportTicket,
  updateSupportTicketStatus,
  createTicketReminder,
  deleteSupportTicket,
  getReadTicketIds,
  markTicketAsRead,
} from '../services/supportTickets';
import { openWhatsAppDirectChat } from '../services/whatsapp';
import { OrderReminder } from '../types/reminder';

interface SupportTicketsScreenProps {
  remindersMap?: Record<string, OrderReminder>;
  refreshTrigger?: number;
  targetTicketId?: string;
  onTicketRead?: (ticketId: string) => void;
}

export const SupportTicketsScreen: React.FC<SupportTicketsScreenProps> = ({
  remindersMap = {},
  refreshTrigger,
  targetTicketId,
  onTicketRead,
}) => {
  const [tickets, setTickets] = useState<SupportTicket[]>([]);
  const [readIds, setReadIds] = useState<string[]>([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedStatusFilter, setSelectedStatusFilter] = useState<'all' | 'open' | 'in_progress' | 'resolved'>('all');
  const [refreshing, setRefreshing] = useState(false);
  const [selectedTicket, setSelectedTicket] = useState<SupportTicket | null>(null);
  const [replyText, setReplyText] = useState('');
  const [sendingReply, setSendingReply] = useState(false);

  const insets = useSafeAreaInsets();
  const modalTopPadding = Math.max(insets.top, Platform.OS === 'android' ? (StatusBar.currentHeight || 28) : 44) + 12;
  const modalBottomPadding = Math.max(insets.bottom, Platform.OS === 'android' ? 28 : 12) + 10;

  const loadTicketsData = async () => {
    setRefreshing(true);
    const [data, storedReadIds] = await Promise.all([
      fetchSupportTickets(),
      getReadTicketIds(),
    ]);
    setTickets(data);
    setReadIds(storedReadIds);
    setRefreshing(false);
  };

  useEffect(() => {
    loadTicketsData();
  }, [refreshTrigger]);

  const handleOpenTicket = async (ticket: SupportTicket) => {
    setSelectedTicket(ticket);
    await markTicketAsRead(ticket.id);
    setReadIds((prev) => (prev.includes(ticket.id) ? prev : [...prev, ticket.id]));
    if (onTicketRead) {
      onTicketRead(ticket.id);
    }
  };

  useEffect(() => {
    if (targetTicketId && tickets.length > 0) {
      const match = tickets.find(
        (t) => t.id === targetTicketId || String(t.ticket_number) === String(targetTicketId)
      );
      if (match) {
        handleOpenTicket(match);
      }
    }
  }, [targetTicketId, tickets]);

  const handleDeleteTicket = (ticket: SupportTicket) => {
    Alert.alert(
      `מחיקת פנייה #T-${ticket.ticket_number}`,
      `האם אתה בטוח שברצונך למחוק את הפנייה לצמיתות?\nפעולה זו תמחק גם את היסטוריית ההודעות ולא ניתן לשחזרה.`,
      [
        { text: 'ביטול', style: 'cancel' },
        {
          text: 'מחק לצמיתות',
          style: 'destructive',
          onPress: async () => {
            const res = await deleteSupportTicket(ticket.id);
            if (res.success) {
              Alert.alert('הפנייה נמחקה', `פנייה #T-${ticket.ticket_number} הוסרה.`);
              if (selectedTicket?.id === ticket.id) {
                setSelectedTicket(null);
              }
              await loadTicketsData();
            } else {
              Alert.alert('שגיאה במחיקה', res.error || 'לא ניתן למחוק את הפנייה');
            }
          },
        },
      ]
    );
  };

