import { authenticateWithBiometrics } from '../services/biometrics';
import { shareLogFile, getLogFileSizeFormatted, clearLogs, logInfo } from '../services/logger';

import { AppConnectionModal } from '../components/AppConnectionModal';
import { PermissionWizardModal } from '../components/PermissionWizardModal';

import {
  checkCallerIdPermissions,
  requestPhonePermissions,
  testCallerIdOverlay,
  setWhatsAppCallerIdEnabled,
} from '../services/callerId';

interface SettingsScreenProps {
  onOpenInventoryModal?: () => void;
}

export const SettingsScreen: React.FC<SettingsScreenProps> = ({
  onOpenInventoryModal,
}) => {
  const [settings, setSettings] = useState<AppSettings | null>(null);
  const [serverUrl, setServerUrl] = useState('');
  const [supabaseUrl, setSupabaseUrl] = useState('');
  const [supabaseAnonKey, setSupabaseAnonKey] = useState('');
  const [testingConnection, setTestingConnection] = useState(false);
  const [showConnectionModal, setShowConnectionModal] = useState(false);
  const [showPermissionWizardModal, setShowPermissionWizardModal] = useState(false);
  const [shippingTemplate, setShippingTemplate] = useState('');
  const [holdReminderTemplate, setHoldReminderTemplate] = useState('');
  const [receiptTemplate, setReceiptTemplate] = useState('');
  const [maxLogSizeMb, setMaxLogSizeMb] = useState('1');
  const [logFileSize, setLogFileSize] = useState('0 KB');
  const [permStatus, setPermStatus] = useState<AndroidPermissionsStatus>({
    batteryIgnoring: true,
    canDrawOverlays: true,
    notificationListenerEnabled: true,
  });
  const [callerIdStatus, setCallerIdStatus] = useState({
    canDrawOverlays: true,
    hasPhoneStatePermission: true,
    hasCallLogPermission: true,
  });

  const refreshLogSize = async () => {
    const sizeStr = await getLogFileSizeFormatted();
    setLogFileSize(sizeStr);
    const [pStatus, cStatus] = await Promise.all([
      checkAndroidPermissionsStatus(),
      checkCallerIdPermissions(),
    ]);
    setPermStatus(pStatus);
    setCallerIdStatus(cStatus);
  };


  useEffect(() => {
    loadAppSettings().then((s) => {
      setSettings(s);
      setServerUrl(s.serverUrl);
      setSupabaseUrl(s.supabaseUrl);
      setSupabaseAnonKey(s.supabaseAnonKey);
      setShippingTemplate(s.whatsappTemplates.shipping);
      setHoldReminderTemplate(s.whatsappTemplates.holdReminder);
      setReceiptTemplate(s.whatsappTemplates.receipt);
      setMaxLogSizeMb(String(s.maxLogSizeMb || 1));
      refreshLogSize();
    });
  }, []);

  if (!settings) return null;

  const handleSaveSettings = async () => {
    const parsedMaxLog = Math.max(0.1, parseFloat(maxLogSizeMb) || 1);
    const updated = await saveAppSettings({
      serverUrl: serverUrl.trim(),
      supabaseUrl: supabaseUrl.trim(),
      supabaseAnonKey: supabaseAnonKey.trim(),
      maxLogSizeMb: parsedMaxLog,
      whatsappTemplates: {
        ...settings.whatsappTemplates,
        shipping: shippingTemplate,
        holdReminder: holdReminderTemplate,
        receipt: receiptTemplate,
      },
    });
    resetSupabaseClient();
    setSettings(updated);
    logInfo('SETTINGS', `Settings saved. Server URL: ${serverUrl}, Max Log: ${parsedMaxLog}MB`);
    Alert.alert('שמור', 'ההגדרות נשמרו בהצלחה!');
  };

