import { ActiveRemindersModal } from './src/components/ActiveRemindersModal';
import { PermissionWizardModal } from './src/components/PermissionWizardModal';
import { InventoryModal } from './src/components/InventoryModal';
import { WhatsAppDisconnectedModal } from './src/components/WhatsAppDisconnectedModal';
import { NewTicketAlertModal } from './src/components/NewTicketAlertModal';
import { Order } from './src/types/order';
import { OrderReminder } from './src/types/reminder';
import { getDueReminders, getActiveRemindersMap } from './src/services/reminders';
import { fetchWhatsAppBotStatus } from './src/services/whatsapp';
import { loadAppSettings } from './src/services/storage';
import { authenticateWithBiometrics } from './src/services/biometrics';
import { registerForPushNotificationsAsync } from './src/services/notifications';
import * as Notifications from 'expo-notifications';
import { hasMissingAndroidPermissions } from './src/services/androidPermissions';
import { syncWidgetData } from './src/services/widget';

import { fetchOrders } from './src/services/orders';
import { getPendingTargetOrderId } from './src/services/callerId';
import {
  SupportTicket,
  fetchSupportTickets,
  getReadTicketIds,
  markTicketAsRead,
  getAlertedTicketIds,
  markTicketAsAlerted,
  cleanupResolvedTickets,
} from './src/services/supportTickets';

export default function App() {
  const [activeTab, setActiveTab] = useState<'home' | 'orders' | 'support' | 'settings'>('home');
  const [selectedStatusFilter, setSelectedStatusFilter] = useState('all');
  const [targetOrderId, setTargetOrderId] = useState<string | undefined>(undefined);
  const [targetTicketId, setTargetTicketId] = useState<string | undefined>(undefined);
  const [alertTicket, setAlertTicket] = useState<SupportTicket | null>(null);
  const [hasUnreadTickets, setHasUnreadTickets] = useState(false);
  const [unreadTicketsCount, setUnreadTicketsCount] = useState(0);

  const [showCreateModal, setShowCreateModal] = useState(false);
  const [paymentModalOrder, setPaymentModalOrder] = useState<Order | null>(null);
  const [qrModalOrder, setQrModalOrder] = useState<Order | null>(null);
  const [reminderModalOrder, setReminderModalOrder] = useState<Order | null>(null);
  const [dueReminders, setDueReminders] = useState<OrderReminder[]>([]);
  const [remindersMap, setRemindersMap] = useState<Record<string, OrderReminder>>({});
  const [showActiveRemindersModal, setShowActiveRemindersModal] = useState(false);
  const [showPermissionWizard, setShowPermissionWizard] = useState(false);
  const [showInventoryModal, setShowInventoryModal] = useState(false);
  const [showWhatsAppDisconnectedModal, setShowWhatsAppDisconnectedModal] = useState(false);
  const hasCheckedWhatsAppRef = React.useRef(false);
  const [ordersRefreshKey, setOrdersRefreshKey] = useState(0);

  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [authChecking, setAuthChecking] = useState(true);

  const checkCallerIdTargetOrder = async () => {
    const pendingId = await getPendingTargetOrderId();
    if (pendingId) {
      setTargetOrderId(pendingId);
      setSelectedStatusFilter('all');
      setActiveTab('orders');
      try {
        const fetchedOrders = await fetchOrders();
        const match = fetchedOrders.find(
          (o: Order) => o.id === pendingId || String(o.order_number) === pendingId
        );
        if (match) {
          setPaymentModalOrder(match);
        }
      } catch (e) {
        console.error('Error auto-opening caller target order:', e);
      }
    }
  };

  const checkTicketsStatus = async (shouldAlertNew = true) => {
    try {
      const [ticketsList, readIds, alertedIds] = await Promise.all([
        fetchSupportTickets(),
        getReadTicketIds(),
        getAlertedTicketIds(),
      ]);

      const openTickets = ticketsList.filter(
        (t) => t.status === 'open' || t.status === 'in_progress'
      );
      const unread = openTickets.filter((t) => !readIds.includes(t.id));

      setHasUnreadTickets(unread.length > 0);
      setUnreadTicketsCount(unread.length);

      if (shouldAlertNew && unread.length > 0) {
        // Find newest unread ticket that hasn't been shown in alert modal yet
        const unalerted = unread.filter((t) => !alertedIds.includes(t.id));
        if (unalerted.length > 0) {
          const newest = unalerted[0];
          setAlertTicket(newest);
          await markTicketAsAlerted(newest.id);
        }
      }
    } catch (e) {
      console.error('Error checking tickets status:', e);
    }
  };

  useEffect(() => {
    initApp();

    // Check for due reminders & new tickets every 15 seconds while app is open
    const interval = setInterval(() => {
      refreshDueReminders(true);
      checkCallerIdTargetOrder();
      checkTicketsStatus(true);
    }, 15000);

    const checkWizard = async () => {
      const missing = await hasMissingAndroidPermissions();
      if (missing) {
        setShowPermissionWizard(true);
      }
    };

    const checkWhatsAppStatusOnce = async () => {
      if (!hasCheckedWhatsAppRef.current) {
        try {
          const status = await fetchWhatsAppBotStatus();
          if (status.status === 'disconnected') {
            setShowWhatsAppDisconnectedModal(true);
            hasCheckedWhatsAppRef.current = true;
          }
        } catch (e) {
          // ignore network failure
        }
      }
    };

    checkWhatsAppStatusOnce();

    // Listen for incoming notifications while app is in foreground
    const notificationListener = Notifications.addNotificationReceivedListener((notification) => {
      const data = notification.request?.content?.data as any;
      if (
        data?.action === 'NEW_SUPPORT_TICKET' ||
        data?.action === 'SUPPORT_TICKETS_RELOAD' ||
        notification.request?.content?.title?.includes('פנייה')
      ) {
        checkTicketsStatus(true);
      }
    });

    // Listen for notification responses (user tapping on notification)
    const subscription = Notifications.addNotificationResponseReceivedListener((response) => {
      refreshDueReminders(true);
      checkCallerIdTargetOrder();
      const data = response.notification?.request?.content?.data as any;
      if (
        data?.action === 'NEW_SUPPORT_TICKET' ||
        data?.action === 'SUPPORT_TICKETS_RELOAD' ||
        response.notification?.request?.content?.title?.includes('פנייה')
      ) {
        if (data?.ticketId) {
          setTargetTicketId(data.ticketId);
        }
        setActiveTab('support');
        checkTicketsStatus(false);
      }
    });

    // Listen for AppState changes (whenever user turns on/unlocks screen or returns to app)
    const appStateSubscription = AppState.addEventListener('change', (nextAppState) => {
      if (nextAppState === 'active') {
        refreshDueReminders(true);
        checkCallerIdTargetOrder();
        checkTicketsStatus(true);
        checkWizard();
        checkWhatsAppStatusOnce();
      }
    });

    return () => {
      clearInterval(interval);
      notificationListener.remove();
      subscription.remove();
      appStateSubscription.remove();
    };
  }, []);

  const refreshAllData = async () => {
    setOrdersRefreshKey((prev) => prev + 1);
    await Promise.all([
      refreshDueReminders(false),
      checkTicketsStatus(false),
    ]);
  };

