      if (!hasCheckedWhatsAppRef.current) {
        try {
          const status = await fetchWhatsAppBotStatus();
          if (status.status === 'disconnected') {
            setShowWhatsAppDisconnectedModal(true);
            hasCheckedWhatsAppRef.current = true;
          }
        } catch (e) {
          // ignore network failure
        }
      }
    };

    checkWhatsAppStatusOnce();

    // Listen for notification responses (user tapping on notification)
    const subscription = Notifications.addNotificationResponseReceivedListener(() => {
      refreshDueReminders(true);
      checkCallerIdTargetOrder();
    });

