import { NextResponse } from 'next/server';
import { createClient } from '@supabase/supabase-js';

// Create a Supabase client with the Service Role key to bypass RLS in the webhook
const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL || '';
const supabaseServiceKey = process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY || '';
const supabaseAdmin = createClient(supabaseUrl, supabaseServiceKey);

export const dynamic = 'force-dynamic';

export async function POST(request: Request) {
  try {
    const text = await request.text();
    let jsonData: any = null;
    try {
      jsonData = JSON.parse(text);
    } catch (e) {}

    const params = new URLSearchParams(text);

    // Helper to retrieve value from JSON (top-level or nested under 'data') or URLSearchParams
    const getVal = (key: string): string | null => {
      if (jsonData) {
        if (jsonData[key] !== undefined && jsonData[key] !== null) return String(jsonData[key]);
        if (jsonData.data && jsonData.data[key] !== undefined && jsonData.data[key] !== null) return String(jsonData.data[key]);
      }
      return params.get(key) || params.get(`data[${key}]`) || null;
    };

    // Extract fields
    const rawStatus = getVal('status');
    const isStatusSuccess = rawStatus === '1' || rawStatus === 'true' || rawStatus === 'success' || rawStatus === '000';

    const orderIdParam = getVal('cField1') || getVal('customField') || getVal('orderId') || getVal('order_id');
    const finalOrderId = orderIdParam;

    const transactionId = getVal('transactionId');
    const asmachta = getVal('asmachta'); // Approval number
    const paidSum = getVal('sum') || getVal('amount') || getVal('sumPaid');
    const paymentMethodParam = getVal('paymentMethod') || getVal('paymentType');
    const cardSuffix = getVal('cardSuffix') || getVal('last4');
    const cardBrand = getVal('cardBrand') || getVal('brand');
    const paymentsNum = getVal('paymentsNum') || getVal('payments');

    console.log('Received Meshulam Webhook:', { 
      rawStatus, 
      isStatusSuccess,
      finalOrderId, 
      transactionId, 
      asmachta, 
      paidSum, 
      paymentMethodParam,
      cardSuffix,
      cardBrand,
      fullText: text 
    });

    if (isStatusSuccess && finalOrderId) {
      // Determine exact payment method from clearing details
      let resolvedPaymentMethod = paymentMethodParam || 'כרטיס אשראי (Grow/משולם)';
      if (cardSuffix) {
        resolvedPaymentMethod = `כרטיס אשראי (${cardBrand ? cardBrand + ' ' : ''}****${cardSuffix})`;
      } else if (paymentMethodParam && paymentMethodParam.toLowerCase().includes('bit')) {
        resolvedPaymentMethod = 'ביט (Bit)';
      } else if (paymentMethodParam && paymentMethodParam.toLowerCase().includes('apple')) {
        resolvedPaymentMethod = 'Apple Pay';
      } else if (paymentMethodParam && paymentMethodParam.toLowerCase().includes('google')) {
        resolvedPaymentMethod = 'Google Pay';
      }

      // Format payment note
      const noteText = `שולם באמצעות ${resolvedPaymentMethod}. אסמכתא: ${asmachta || 'אין'}, תנועה: ${transactionId || 'אין'}${paymentsNum && parseInt(paymentsNum) > 1 ? `, תשלומים: ${paymentsNum}` : ''}`;

      const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(finalOrderId);

      let targetOrderUuid = isUuid ? finalOrderId : null;
      let matchedOrderNumber: number | null = null;

      if (!targetOrderUuid) {
        const { data: matchedOrder } = await supabaseAdmin
          .from('orders')
          .select('id, order_number')
          .eq('order_number', parseInt(finalOrderId) || 0)
          .maybeSingle();
        targetOrderUuid = matchedOrder?.id || null;
        matchedOrderNumber = matchedOrder?.order_number || null;
      }

      if (!targetOrderUuid) {
        console.error('Could not find matching order in database for finalOrderId:', finalOrderId);
        return new Response('Order not found', { status: 404 });
      }

      // Fetch existing order to preserve notes
      const { data: existingOrder } = await supabaseAdmin
        .from('orders')
        .select('id, order_number, status, admin_notes, customer_phone, customer_name, total_price, order_items(quantity)')
        .eq('id', targetOrderUuid)
        .single();

      const combinedNotes = existingOrder?.admin_notes
        ? `${existingOrder.admin_notes} | ${noteText}`
        : noteText;

      const updateData: any = { 
        status: 'paid',
        admin_notes: combinedNotes,
      };

      if (paidSum && parseFloat(paidSum) > 0) {
        updateData.total_price = parseFloat(paidSum);
      }

      const { error: updateError } = await supabaseAdmin
        .from('orders')
        .update(updateData)
        .eq('id', targetOrderUuid);

      if (updateError) {
        console.error('Error updating order status from webhook:', updateError);
        return new Response('Error updating database', { status: 500 });
      }

      console.log(`Order ${targetOrderUuid} (#${existingOrder?.order_number || matchedOrderNumber}) marked as paid via webhook.`);

      // 1. Recalculate reserved inventory
      try {
        const { recalculateReservedInventory } = await import('@/app/actions/adminInventory');
        await recalculateReservedInventory();
      } catch (invErr) {
        console.error('Error recalculating inventory in webhook:', invErr);
      }

      // 2. Process backorder queue
      try {
        const { processBackorderQueue } = await import('@/app/actions/backorderQueue');
        await processBackorderQueue();
      } catch (qErr) {}

      // 3. Trigger Admin Mobile Push Notification
      try {
        const { sendAdminPushNotification } = await import('@/lib/pushNotifications');
        const num = existingOrder?.order_number || matchedOrderNumber || targetOrderUuid.substring(0, 8);
        await sendAdminPushNotification({
          title: `הזמנה שולמה בהצלחה! 🍋`,
          body: `הזמנה #${num} שולמה בסך ${paidSum || existingOrder?.total_price || ''} ₪ (${resolvedPaymentMethod})`,
          data: { action: 'ORDERS_RELOAD', orderId: targetOrderUuid },
        });
      } catch (pushErr) {}

      // 4. Send invoice email
      try {
        const { sendInvoiceEmailForOrderAction } = await import('@/app/actions/userOrders');
        await sendInvoiceEmailForOrderAction({ 
          orderId: targetOrderUuid, 
          paymentMethodName: resolvedPaymentMethod 
        });
      } catch (emailErr) {
        console.error('Error sending invoice email in webhook:', emailErr);
      }

      // 5. Send receipt via WhatsApp Bot to customer
      try {
        const { sendWhatsAppMessageDirect } = await import('@/lib/whatsappBot');
        const { decrypt } = await import('@/lib/encryption');

        if (existingOrder?.customer_phone) {
          const rawPhone = decrypt(existingOrder.customer_phone) || existingOrder.customer_phone;
          const rawName = decrypt(existingOrder.customer_name) || existingOrder.customer_name || 'לקוח יקר';
          const cleanPhone = rawPhone.replace(/\D/g, '');

          if (cleanPhone && cleanPhone.length >= 9) {
            const siteUrl = (process.env.NEXT_PUBLIC_SITE_URL || process.env.SITE_URL || 'https://www.morancello.com').replace(/\/$/, '');
            const receiptUrl = `${siteUrl}/receipt/${targetOrderUuid}`;
            const totalBottles = existingOrder.order_items?.reduce((s: number, i: any) => s + (i.quantity || 0), 0) || 1;
            const displayNum = existingOrder.order_number || matchedOrderNumber || targetOrderUuid.substring(0, 8);
            const displayPrice = paidSum || existingOrder.total_price || 0;

            const waMsg = `שלום ${rawName} 🍋,\n\nתודה רבה! התשלום עבור הזמנה #${displayNum} בסך ${displayPrice} ₪ התקבל בהצלחה! המשקה שלך (${totalBottles} בקבוקים) נכנס להכנה ואריזה.\n\n📄 לצפייה והורדת החשבונית/קבלה הדיגיטלית:\n${receiptUrl}\n\nשותים לזכרה ולחייכם 🙏`;

            await sendWhatsAppMessageDirect(cleanPhone, waMsg);
            console.log(`[Meshulam Webhook] Successfully sent WhatsApp receipt to ${cleanPhone} for order #${displayNum}`);
          }
        }
      } catch (waErr) {
        console.error('[Meshulam Webhook] Error sending WhatsApp receipt:', waErr);
      }
    } else {
      console.log('Payment was not successful or missing orderId', { isStatusSuccess, finalOrderId });
    }

    // Must return 200 OK so Meshulam knows we received it
    return new Response('OK', { status: 200 });

  } catch (error: any) {
    console.error('Error processing Meshulam webhook:', error);
    return new Response('Server Error: ' + error.message, { status: 500 });
  }
}

