      const { data: order } = await query.maybeSingle();

      if (order && order.status !== 'paid' && order.status !== 'completed' && order.status !== 'delivered') {
        console.log(`[iframe-success] Order ${order.id} (#${order.order_number}) is ${order.status}. Updating to paid via iframe-success fail-safe.`);

        const noteText = `שולם בהצלחה (אושר במסוף סליקה Grow/משולם בתאריך ${new Date().toLocaleDateString('he-IL')})`;
        const combinedNotes = order.admin_notes ? `${order.admin_notes} | ${noteText}` : noteText;

        await supabaseAdmin
          .from('orders')
          .update({
            status: 'paid',
            admin_notes: combinedNotes,
          })
          .eq('id', order.id);

        // 1. Recalculate reserved inventory
        try {
          const { recalculateReservedInventory } = await import('@/app/actions/adminInventory');
          await recalculateReservedInventory();
        } catch (invErr) {
          console.error('[iframe-success] Error recalculating inventory:', invErr);
        }

        // 2. Trigger Admin Mobile Push Notification
        try {
          const { sendAdminPushNotification } = await import('@/lib/pushNotifications');
          await sendAdminPushNotification({
            title: `הזמנה שולמה בהצלחה! 🍋`,
            body: `הזמנה #${order.order_number} שולמה בסך ${order.total_price} ₪`,
            data: { action: 'ORDERS_RELOAD', orderId: order.id },
          });
        } catch (pushErr) {}

        // 3. Send invoice email
        try {
          const { sendInvoiceEmailForOrderAction } = await import('@/app/actions/userOrders');
          await sendInvoiceEmailForOrderAction({
            orderId: order.id,
            paymentMethodName: 'כרטיס אשראי (Grow / משולם)',
          });
        } catch (emailErr) {
          console.error('[iframe-success] Error sending invoice email:', emailErr);
        }

        // 4. Send receipt via WhatsApp Bot to customer
        try {
          const { sendWhatsAppMessageDirect } = await import('@/lib/whatsappBot');
          const { decrypt } = await import('@/lib/encryption');

          if (order.customer_phone) {
            const rawPhone = decrypt(order.customer_phone) || order.customer_phone;
            const rawName = decrypt(order.customer_name) || order.customer_name || 'לקוח יקר';
            const cleanPhone = rawPhone.replace(/\D/g, '');

            if (cleanPhone && cleanPhone.length >= 9) {
              const siteUrl = (process.env.NEXT_PUBLIC_SITE_URL || process.env.SITE_URL || 'https://www.morancello.com').replace(/\/$/, '');
              const receiptUrl = `${siteUrl}/receipt/${order.id}`;
              const totalBottles = order.order_items?.reduce((s: number, i: any) => s + (i.quantity || 0), 0) || 1;
              const displayNum = order.order_number || order.id.substring(0, 8);
              const displayPrice = order.total_price || 0;

              const waMsg = `שלום ${rawName} 🍋,\n\nתודה רבה! התשלום עבור הזמנה #${displayNum} בסך ${displayPrice} ₪ התקבל בהצלחה! המשקה שלך (${totalBottles} בקבוקים) נכנס להכנה ואריזה.\n\n📄 לצפייה והורדת החשבונית/קבלה הדיגיטלית:\n${receiptUrl}\n\nשותים לזכרה ולחייכם 🙏`;

              await sendWhatsAppMessageDirect(cleanPhone, waMsg);
              console.log(`[iframe-success] Successfully sent WhatsApp receipt to ${cleanPhone} for order #${displayNum}`);
            }
          }
        } catch (waErr) {
          console.error('[iframe-success] Error sending WhatsApp receipt:', waErr);
        }
      }
    } catch (dbErr) {
      console.error('[iframe-success] Error in fail-safe order check:', dbErr);
    }
  }

  const targetUrl = `/receipt/${orderId}?payment=${payment}`;

  const html = `
    <!DOCTYPE html>
    <html lang="he" dir="rtl">
    <head>
      <meta charset="UTF-8">
      <title>מעבד תשלום...</title>
      <style>
        body {
          display: flex;
          justify-content: center;
          align-items: center;
          height: 100vh;
          margin: 0;
          font-family: system-ui, -apple-system, sans-serif;
          background-color: #f9fafb;
          color: #374151;
        }
        .spinner {
          border: 4px solid rgba(0, 0, 0, 0.1);
          width: 40px;
          height: 40px;
          border-radius: 50%;
          border-left-color: #eab308;
          animation: spin 1s linear infinite;
          margin: 0 auto 16px;
        }
        @keyframes spin {
          0% { transform: rotate(0deg); }
          100% { transform: rotate(360deg); }
        }
        .container { text-align: center; }
      </style>
    </head>
    <body>
      <div class="container">
        <div class="spinner"></div>
        <h2>התשלום התקבל! מעביר אותך לסיכום ההזמנה...</h2>
      </div>
      <script>
        // Break out of iframe and redirect the parent window
        if (window.top !== window.self) {
          window.top.location.href = "${targetUrl}";
        } else {
          window.location.href = "${targetUrl}";
        }
      </script>
    </body>
    </html>
  `;

  return new NextResponse(html, {
    headers: {
      'Content-Type': 'text/html; charset=utf-8',
    },
  });
}

export async function GET(request: Request) {
  return handleSuccessOrCancel(request);
}

export async function POST(request: Request) {
  return handleSuccessOrCancel(request);
}

