const {
  name,
  phone,
  email,
  dedication,
  quantity,
  pickup,
  address,
  shippingProvider,
  shippingCost = 0,
  totalPrice,
} = body;

const numQty = parseInt(String(quantity), 10) || 1;
const cleanPhone = (phone || "").replace(/\D/g, "");

if (!cleanPhone || numQty < 1) {
  return NextResponse.json(
    { success: false, error: "Missing required fields (phone, quantity)" },
    { status: 400 }
  );
}

// Check system settings
const isOrdersEnabled = (await fetchSetting("is_orders_enabled")) !== "false";
if (!isOrdersEnabled) {
  return NextResponse.json(
    { success: false, error: "קבלת הזמנות חדשות מושהית זמנית במערכת" },
    { status: 400 }
  );
}

const isShippingEnabled = (await fetchSetting("is_shipping_enabled")) === "true";
if (pickup === "delivery" && !isShippingEnabled) {
  return NextResponse.json(
    { success: false, error: "משלוחים אינם פעילים כעת במערכת. ניתן לבצע איסוף עצמי בלבד" },
    { status: 400 }
  );
}

// 1. Fetch active product and check live inventory
const { data: product } = await supabaseAdmin
  .from("products")
  .select(`
    id,
    name,
    price,
    inventory (
      physical_quantity,
      reserved_quantity
    )
  `)
  .eq("is_active", true)
  .order("created_at", { ascending: true })
  .limit(1)
  .maybeSingle();

const productId = product?.id || "00000000-0000-0000-0000-000000000001";
const inv = Array.isArray(product?.inventory) ? product.inventory[0] : product?.inventory;
const physicalQty = inv?.physical_quantity || 0;
const reservedQty = inv?.reserved_quantity || 0;
const availableStock = physicalQty - reservedQty;

const isBackorder = availableStock < numQty;
const initialStatus = isBackorder ? "backorder_pending" : "pending";

const unitPrice = product?.price || 122;
const calculatedTotal = totalPrice || numQty * unitPrice + (shippingCost || 0);

// 2. Encrypt PII
const customerName = (name && name.trim()) || "לקוח וואטסאפ";
const customerEmail = (email && email.trim()) || `${cleanPhone}@whatsapp.morancello.com`;
const encryptedName = encrypt(customerName);
const encryptedPhone = encrypt(cleanPhone);
const encryptedEmail = encrypt(customerEmail);
const encryptedAddress = address ? encrypt(address) : null;
const encryptedDedication = dedication ? encrypt(dedication) : null;

// 3. Insert order
const { data: newOrder, error: orderErr } = await supabaseAdmin
  .from("orders")
  .insert({
    customer_name: encryptedName,
    customer_phone: encryptedPhone,
    customer_email: encryptedEmail,
    pickup_method: pickup || "pickup",
    delivery_address: encryptedAddress,
    shipping_provider: shippingProvider || null,
    shipping_cost: shippingCost || 0,
    dedication: encryptedDedication,
    total_price: calculatedTotal,
    status: initialStatus,
    admin_notes: `נוצר דרך בוט WhatsApp בתאריך ${new Date().toLocaleDateString("he-IL")}${
      isBackorder ? " (הרשמה עתידית - ממתין למלאי)" : ""
    }`,
  })
  .select("id, order_number, status, total_price")

