async function handleMainMenuChoice(phone, text) {
  if (text === "1") {
    const ordersEnabled = await getBotSetting("is_orders_enabled");
    if (ordersEnabled === "false") {
      await sendMessage(
        phone,
        `קבלת הזמנות חדשות מושהית זמנית במערכת 🍋\nלכל שאלה או בירור, נשמח לסייע באפשרות 5 (פתיחת פנייה לצוות).\n\n(הקלד 0 לתפריט הראשי)`
      );
      return;
    }
    setSession(phone, { ageVerified: true, step: "BUY_QTY", orderData: {} });
    await sendMessage(
      phone,
      `כמה בקבוקי מורנצ׳לו (500 מ״ל) תרצו להזמין? 🍋\n\n1️⃣ בקבוק אחד (122 ₪)\n2️⃣ שני בקבוקים (244 ₪)\n3️⃣ שלושה בקבוקים (366 ₪)\n4️⃣ מארז 4 בקבוקים (488 ₪)\n\nהשב עם הספרה 1-4 (או 0 לתפריט):`
    );
  } else if (text === "2") {
    await handleStatusInquiry(phone);
  } else if (text === "3") {
    await handlePaymentCompletion(phone);
  } else if (text === "4") {
    await handleCancellationInquiry(phone);
  } else if (text === "5") {
    setSession(phone, { ageVerified: true, step: "SUPPORT_NAME" });
    await sendMessage(phone, `נשמח לעזור! 😊\nאנא הקלד את שמך המלא:`);
  } else {
    await sendMessage(phone, `אפשרות לא זוהתה. אנא השב עם ספרה בין 1 ל-5:\n\n1️⃣ הזמנה\n2️⃣ סטטוס\n3️⃣ תשלום\n4️⃣ ביטול\n5️⃣ פנייה\n(או 0 לתפריט)`);
  }
}

// --- 1. Buy Flow (Aligned with Website Fields & Settings) ---
async function handleBuyQtyChoice(phone, text, session) {
  const qtyMap = { "1": 1, "2": 2, "3": 3, "4": 4 };
  const qty = qtyMap[text];
  if (!qty) {
    await sendMessage(phone, `אנא בחר ספרה בין 1 ל-4 עבור כמות הבקבוקים (או 0 לתפריט):`);
    return;
  }

  session.orderData = { quantity: qty, bottlePrice: 122 };
  session.step = "BUY_NAME";
  setSession(phone, session);

  await sendMessage(
    phone,
    `מעולה! 🍋\nאנא הקלד את שמך המלא (שם פרטי ומשפחה) שיופיע על גבי ההזמנה והקבלה:`
  );
}

async function handleBuyNameInput(phone, text, session) {
  const trimmedName = (text || "").trim();
  if (!trimmedName || trimmedName.length < 2) {
    await sendMessage(phone, `אנא הקלד שם מלא תקין (שם פרטי ומשפחה):`);
    return;
  }

  session.orderData.name = trimmedName;
  session.step = "BUY_EMAIL";
  setSession(phone, session);

  await sendMessage(
    phone,
    `תודה ${trimmedName}! 📝\n\nאנא הקלד את כתובת האימייל שלך (למשלוח החשבונית/קבלה ועדכוני הזמנה):\n(ניתן להשיב "0" או "דלג" להמשך ללא מייל)`
  );
}

async function handleBuyEmailInput(phone, text, session) {
  const rawEmail = (text || "").trim();
  const isSkip = rawEmail === "0" || rawEmail === "דלג" || rawEmail === "ללא" || rawEmail === "-";

  if (!isSkip) {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(rawEmail)) {
      await sendMessage(
        phone,
        `כתובת האימייל אינה תקינה. אנא הקלד כתובת אימייל תקינה (למשל: name@example.com)\nאו השב "0" / "דלג" להמשך:`
      );
      return;
    }
    session.orderData.email = rawEmail;
  } else {
    session.orderData.email = `${phone}@whatsapp.morancello.com`;
  }

  // Check shipping policy from settings (aligned with website)
  const isShippingEnabled = (await getBotSetting("is_shipping_enabled")) === "true";
  const originAddress = (await getBotSetting("shipping_origin_address")) || "באר יעקב";
  session.orderData.shippingOrigin = originAddress;

  if (!isShippingEnabled) {
    // Shipping is disabled on site! Only pickup is allowed.
    session.orderData.pickup = "pickup";
    session.orderData.shippingProvider = null;
    session.orderData.shippingCost = 0;
    session.orderData.address = `איסוף עצמי מ${originAddress}`;
    session.step = "BUY_DEDICATION";
    setSession(phone, session);

    await sendMessage(
      phone,
      `אופן אספקה:\n📍 כרגע ניתן לבצע איסוף עצמי בלבד (${originAddress} - ללא עלות נוספת).\n\nתרצו להוסיף הקדשה אישית / ברכה על הבקבוק, או הערות מיוחדות להזמנה? ✍️\n\nהשב עם תוכן ההקדשה (או השב "0" / "ללא" להמשך לתשלום):`
    );
  } else {
    // Shipping is enabled - present options
    session.step = "BUY_PICKUP";
    setSession(phone, session);

    await sendMessage(
      phone,
      `כיצד תרצו לקבל את ההזמנה? 🍋\n\n1️⃣ איסוף עצמי (${originAddress} - ללא עלות)\n2️⃣ משלוח עד הבית\n\nהשב 1 או 2 (או 0 לתפריט):`
    );
  }
}

async function handleBuyPickupChoice(phone, text, session) {
  const originAddress = session.orderData.shippingOrigin || "באר יעקב";

  if (text === "1") {
    // Self pickup
    session.orderData.pickup = "pickup";
    session.orderData.shippingProvider = null;
    session.orderData.shippingCost = 0;
    session.orderData.address = `איסוף עצמי מ${originAddress}`;
    session.step = "BUY_DEDICATION";
    setSession(phone, session);

    await sendMessage(
      phone,
      `נבחר איסוף עצמי מ${originAddress} (ללא עלות). 🍋\n\nתרצו להוסיף הקדשה אישית / ברכה על הבקבוק, או הערות מיוחדות להזמנה? ✍️\n\nהשב עם תוכן ההקדשה (או השב "0" / "ללא" להמשך לתשלום):`
    );
  } else if (text === "2") {
    // Delivery requested
    session.step = "BUY_ADDRESS";
    setSession(phone, session);

    await sendMessage(
      phone,
      `🚚 לאן לשלוח את המורנצ׳לו שלך?\n\nאנא הקלד כתובת מלאה (עיר, רחוב ומספר בית)\nאו שלח מיקום 📍 דרך כפתור הסיכה (Location):`
    );
  } else {
    await sendMessage(phone, `אנא השב 1 לאיסוף עצמי או 2 למשלוח עד הבית (או 0 לתפריט):`);
  }
}

async function handleBuyAddressInput(phone, text, location, session) {
  let address = text;
  if (location) {
    address = location.name || `${location.degreesLatitude}, ${location.degreesLongitude}`;
  }

  if (!address || address.length < 4) {
    await sendMessage(phone, `נא לציין כתובת מלאה כולל עיר, רחוב ומספר בית (לדוגמה: רוטשילד 15, תל אביב):`);
    return;
  }

  session.orderData.address = address;
  session.step = "BUY_SHIPPING";
  setSession(phone, session);

  await sendMessage(
    phone,
    `📍 כתובת למשלוח: ${address}\n\nאפשרויות השילוח הזמינות:\n1️⃣ שליח עד הבית (GetPackage) — 25 ₪\n2️⃣ נקודת חלוקה קרובה (צ'יטה) — 18 ₪\n3️⃣ שליח אקספרס מהיום להיום (Yango) — 38 ₪\n4️⃣ שינוי כתובת\n\nהשב עם הספרה המבוקשת (1-4):`
  );
}

async function handleBuyShippingChoice(phone, text, session) {
  if (text === "4") {
    session.step = "BUY_ADDRESS";
    setSession(phone, session);
    await sendMessage(phone, `אנא הקלד את הכתובת החדשה למשלוח:`);
    return;
  }

  const shippingOptions = {
    "1": { name: "שליח עד הבית (GetPackage)", provider: "getpackage", cost: 25 },
    "2": { name: "נקודת חלוקה (צ'יטה)", provider: "cheetah", cost: 18 },
    "3": { name: "שליח אקספרס מהיום להיום (Yango)", provider: "yango", cost: 38 },
  };

  const choice = shippingOptions[text];
  if (!choice) {
    await sendMessage(phone, `אנא בחר אפשרות שילוח בין 1 ל-4:`);
    return;
  }

  session.orderData.pickup = "delivery";
  session.orderData.shippingProvider = choice.provider;
  session.orderData.shippingProviderName = choice.name;
  session.orderData.shippingCost = choice.cost;
  session.step = "BUY_DEDICATION";
  setSession(phone, session);

  await sendMessage(
    phone,
    `מעולה, נבחר משלוח: ${choice.name} (${choice.cost} ₪).\n\nתרצו להוסיף הקדשה אישית / ברכה על הבקבוק, או הערות מיוחדות להזמנה? ✍️\n\nהשב עם תוכן ההקדשה (או השב "0" / "ללא" להמשך לתשלום):`
  );
}

async function handleBuyDedicationInput(phone, text, session) {
  const rawDedication = (text || "").trim();
  const isSkip = rawDedication === "0" || rawDedication === "ללא" || rawDedication === "דלג" || rawDedication === "-";

  session.orderData.dedication = isSkip ? null : rawDedication;

  await finalizeAndCreateBotOrder(phone, session);
}

async function finalizeAndCreateBotOrder(phone, session) {
  const {
    name,
    email,
    quantity,
    pickup,
    shippingProvider,
    shippingProviderName,
    shippingCost = 0,
    address,
    dedication,
  } = session.orderData;

  const totalPrice = quantity * 122 + (shippingCost || 0);

  const botRes = await createBotOrder({
    name,
    phone,
    email,
    quantity,
    pickup,
    shippingProvider,
    shippingCost,
    totalPrice,
    address,
    dedication,
  });

  const newOrder = botRes.order;
  const checkoutUrl = botRes.paymentUrl || botRes.checkoutUrl;

  const deliveryDesc = pickup === "delivery"
    ? `🚚 משלוח: ${shippingProviderName || "משלוח"} (${shippingCost} ₪)\n📍 כתובת: ${address}`
    : `📍 איסוף עצמי (${session.orderData.shippingOrigin || "באר יעקב"} - ללא עלות)`;

  const dedicationDesc = dedication ? `✍️ הקדשה/הערה: "${dedication}"\n` : "";

  await sendMessage(
    phone,
    `📋 סיכום ההזמנה שלך (#${newOrder.order_number}):\n👤 שם: ${name}\n🍾 כמות: ${quantity} בקבוקים (${quantity * 122} ₪)\n${deliveryDesc}\n${dedicationDesc}💰 סה״כ לתשלום: ${totalPrice} ₪\n\n💳 לתשלום מאובטח ב-Bit / Apple Pay / אשראי:\n${checkoutUrl}\n\n${CLOSING_MOTTO}`
  );

  setSession(phone, { ageVerified: true, step: "MAIN_MENU" });
}

// --- Helper: Insert Order via API / Supabase ---
async function createBotOrder({ name, phone, email, quantity, pickup, shippingProvider, shippingCost, totalPrice, address, dedication }) {
  const siteUrl = (process.env.SITE_URL || "https://www.morancello.com").replace(/\/$/, "");

  // 1. Authoritative Next.js API (checks stock, encrypts, updates inventory, triggers push, prepares checkout)
  try {
    const res = await fetch(`${siteUrl}/api/whatsapp/create-order`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${DEFAULT_AUTH_TOKEN}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        name,
        phone,
        email,
        dedication,
        quantity,
        pickup,
        shippingProvider,
        shippingCost,
        totalPrice,
        address,
      }),
    });
    if (res.ok) {
      const json = await res.json();
      if (json.success && json.order) {
        return {
          order: json.order,
          checkoutUrl: json.checkoutUrl,
          paymentUrl: json.paymentUrl,
          isBackorder: json.isBackorder,
        };
      }
    }
  } catch (err) {
    console.error("[WhatsApp Bot] Error creating order via /api/whatsapp/create-order:", err.message);
  }

  // 2. Direct Supabase Fallback (with policy-compliant inventory reservation)
  const encryptedPhone = encrypt(phone);
  const encryptedName = encrypt(name || "לקוח וואטסאפ");
  const encryptedEmail = encrypt(email || `${phone}@whatsapp.morancello.com`);
  const encryptedAddress = address ? encrypt(address) : null;
  const encryptedDedication = dedication ? encrypt(dedication) : null;

  const { data: newOrder, error } = await supabase
    .from("orders")
    .insert({
      customer_name: encryptedName,
      customer_phone: encryptedPhone,
      customer_email: encryptedEmail,
      pickup_method: pickup,
      delivery_address: encryptedAddress,
      shipping_provider: shippingProvider,
      shipping_cost: shippingCost,
      dedication: encryptedDedication,
      total_price: totalPrice,
      status: "pending",
      admin_notes: `נוצר דרך בוט WhatsApp בתאריך ${new Date().toLocaleDateString("he-IL")}`,
    })
    .select("id, order_number, total_price, status")
    .single();

  if (error || !newOrder) {
    throw new Error(error?.message || "Failed to create order");
  }

  await supabase.from("order_items").insert({
    order_id: newOrder.id,
