async function handleMainMenuChoice(phone, text) {
  if (text === "1") {
    setSession(phone, { ageVerified: true, step: "BUY_QTY", orderData: {} });
    await sendMessage(
      phone,
      `כמה בקבוקי מורנצ׳לו (500 מ״ל) תרצו להזמין? 🍋\n\n1️⃣ בקבוק אחד (122 ₪)\n2️⃣ שני בקבוקים (244 ₪)\n3️⃣ שלושה בקבוקים (366 ₪)\n4️⃣ מארז 4 בקבוקים (488 ₪)\n\nהשב עם הספרה 1-4 (או 0 לתפריט):`
    );
  } else if (text === "2") {
    await handleStatusInquiry(phone);
  } else if (text === "3") {
    await handlePaymentCompletion(phone);
  } else if (text === "4") {
    await handleCancellationInquiry(phone);
  } else if (text === "5") {
    setSession(phone, { ageVerified: true, step: "SUPPORT_NAME" });
    await sendMessage(phone, `נשמח לעזור! 😊\nאנא הקלד את שמך המלא:`);
  } else {
    await sendMessage(phone, `אפשרות לא זוהתה. אנא השב עם ספרה בין 1 ל-5:\n\n1️⃣ הזמנה\n2️⃣ סטטוס\n3️⃣ תשלום\n4️⃣ ביטול\n5️⃣ פנייה\n(או 0 לתפריט)`);
  }
}

// --- 1. Buy Flow ---
async function handleBuyQtyChoice(phone, text, session) {
  const qtyMap = { "1": 1, "2": 2, "3": 3, "4": 4 };
  const qty = qtyMap[text];
  if (!qty) {
    await sendMessage(phone, `אנא בחר ספרה בין 1 ל-4 עבור כמות הבקבוקים (או 0 לתפריט):`);
    return;
  }

  session.orderData = { quantity: qty, bottlePrice: 122 };
  session.step = "BUY_PICKUP";
  setSession(phone, session);

  await sendMessage(
    phone,
    `כיצד תרצו לקבל את ההזמנה? 🍋\n\n1️⃣ איסוף עצמי (באר יעקב - ללא עלות)\n2️⃣ משלוח עד הבית\n\nהשב 1 או 2 (או 0 לתפריט):`
  );
}

async function handleBuyPickupChoice(phone, text, session) {
  if (text === "1") {
    // Self pickup
    const qty = session.orderData.quantity;
    const totalPrice = qty * 122;

    const botRes = await createBotOrder({
      phone,
      quantity: qty,
      pickup: "pickup",
      shippingProvider: null,
      shippingCost: 0,
      totalPrice,
      address: "איסוף עצמי מבאר יעקב",
    });

    const newOrder = botRes.order;
    const checkoutUrl = botRes.paymentUrl || botRes.checkoutUrl;

    await sendMessage(
      phone,
      `ההזמנה שלך נקלטה בהצלחה! 🍋\nמספר הזמנה: #${newOrder.order_number}\nאיסוף עצמי מבאר יעקב\nסכום לתשלום: ${totalPrice} ₪\n\nלתשלום מאובטח ב-Bit / Apple Pay / אשראי:\n${checkoutUrl}\n\n${CLOSING_MOTTO}`
    );

    setSession(phone, { ageVerified: true, step: "MAIN_MENU" });
  } else if (text === "2") {
    // Delivery requested
    session.step = "BUY_ADDRESS";
    setSession(phone, session);

    await sendMessage(
      phone,
      `🚚 לאן לשלוח את המורנצ׳לו שלך?\n\nאנא הקלד כתובת מלאה (עיר, רחוב ומספר בית)\nאו שלח מיקום 📍 דרך כפתור הסיכה (Location):`
    );
  } else {
    await sendMessage(phone, `אנא השב 1 לאיסוף עצמי או 2 למשלוח עד הבית:`);
  }
}

async function handleBuyAddressInput(phone, text, location, session) {
  let address = text;
  if (location) {
    address = location.name || `${location.degreesLatitude}, ${location.degreesLongitude}`;
  }

  if (!address || address.length < 4) {
    await sendMessage(phone, `נא לציין כתובת מלאה כולל עיר, רחוב ומספר בית (לדוגמה: רוטשילד 15, תל אביב):`);
    return;
  }

  session.orderData.address = address;
  session.step = "BUY_SHIPPING";
  setSession(phone, session);

  await sendMessage(
    phone,
    `📍 כתובת למשלוח: ${address}\n\nאפשרויות השילוח הזמינות:\n1️⃣ שליח עד הבית (GetPackage) — 25 ₪\n2️⃣ נקודת חלוקה קרובה (צ'יטה) — 18 ₪\n3️⃣ שליח אקספרס מהיום להיום — 38 ₪\n4️⃣ שינוי כתובת\n\nהשב עם הספרה המבוקשת (1-4):`
  );
}

async function handleBuyShippingChoice(phone, text, session) {
  if (text === "4") {
    session.step = "BUY_ADDRESS";
    setSession(phone, session);
    await sendMessage(phone, `אנא הקלד את הכתובת החדשה למשלוח:`);
    return;
  }

  const shippingOptions = {
    "1": { name: "שליח עד הבית", provider: "getpackage", cost: 25 },
    "2": { name: "נקודת חלוקה (צ'יטה)", provider: "cheetah", cost: 18 },
    "3": { name: "שליח אקספרס", provider: "yango", cost: 38 },
  };

  const choice = shippingOptions[text];
  if (!choice) {
    await sendMessage(phone, `אנא בחר אפשרות שילוח בין 1 ל-4:`);
    return;
  }

  const qty = session.orderData.quantity;
  const totalPrice = qty * 122 + choice.cost;

  const botRes = await createBotOrder({
    phone,
    quantity: qty,
    pickup: "delivery",
    shippingProvider: choice.provider,
    shippingCost: choice.cost,
    totalPrice,
    address: session.orderData.address,
  });

  const newOrder = botRes.order;
  const checkoutUrl = botRes.paymentUrl || botRes.checkoutUrl;

  await sendMessage(
    phone,
    `📋 סיכום ההזמנה שלך (#${newOrder.order_number}):\n🍾 כמות: ${qty} בקבוקים (${qty * 122} ₪)\n🚚 משלוח: ${choice.name} (${choice.cost} ₪)\n💰 סה״כ לתשלום: ${totalPrice} ₪\n📍 כתובת: ${session.orderData.address}\n\nלתשלום מאובטח ב-Bit / Apple Pay / אשראי:\n${checkoutUrl}\n\n${CLOSING_MOTTO}`
  );

  setSession(phone, { ageVerified: true, step: "MAIN_MENU" });
}

// --- Helper: Insert Order via API / Supabase ---
async function createBotOrder({ phone, quantity, pickup, shippingProvider, shippingCost, totalPrice, address }) {
  const siteUrl = (process.env.SITE_URL || "https://www.morancello.com").replace(/\/$/, "");

  // 1. Authoritative Next.js API (checks stock, encrypts, updates inventory, triggers push, prepares checkout)
  try {
    const res = await fetch(`${siteUrl}/api/whatsapp/create-order`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${DEFAULT_AUTH_TOKEN}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        name: "לקוח וואטסאפ",
        phone,
        quantity,
        pickup,
        shippingProvider,
        shippingCost,
        totalPrice,
        address,
      }),
    });
    if (res.ok) {
      const json = await res.json();
      if (json.success && json.order) {
        return {
          order: json.order,
          checkoutUrl: json.checkoutUrl,
          paymentUrl: json.paymentUrl,
          isBackorder: json.isBackorder,
        };
      }
    }
  } catch (err) {
    console.error("[WhatsApp Bot] Error creating order via /api/whatsapp/create-order:", err.message);
  }

  // 2. Direct Supabase Fallback (with policy-compliant inventory reservation)
  const encryptedPhone = encrypt(phone);
  const encryptedName = encrypt("לקוח וואטסאפ");
  const encryptedAddress = address ? encrypt(address) : null;

  const { data: newOrder, error } = await supabase
    .from("orders")
    .insert({
      customer_name: encryptedName,
      customer_phone: encryptedPhone,
      customer_email: encrypt(`${phone}@whatsapp.morancello.com`),
      pickup_method: pickup,
      delivery_address: encryptedAddress,
      shipping_provider: shippingProvider,
      shipping_cost: shippingCost,
      total_price: totalPrice,
      status: "pending",
      admin_notes: `נוצר דרך בוט WhatsApp בתאריך ${new Date().toLocaleDateString("he-IL")}`,
    })
    .select("id, order_number, total_price, status")
    .single();

  if (error || !newOrder) {
    throw new Error(error?.message || "Failed to create order");
  }

  await supabase.from("order_items").insert({
    order_id: newOrder.id,
    product_id: "00000000-0000-0000-0000-000000000001",
    quantity,
    price_at_purchase: 122,
  });

  // Policy requirement: recalculate reserved inventory
  try {
    const { data: activeItems } = await supabase
      .from("order_items")
      .select("quantity, orders!inner(status)")
      .in("orders.status", ["pending", "paid", "processing", "backorder_held"]);
    const totalReserved = (activeItems || []).reduce((acc, i) => acc + (i.quantity || 0), 0);
    await supabase
      .from("inventory")
      .update({ reserved_quantity: totalReserved })
      .eq("product_id", "00000000-0000-0000-0000-000000000001");
  } catch (invErr) {
    console.error("[WhatsApp Bot] Fallback inventory update error:", invErr.message);
  }

  return {
    order: newOrder,
    checkoutUrl: `${siteUrl}/checkout?orderId=${newOrder.id}`,
    paymentUrl: `${siteUrl}/checkout?orderId=${newOrder.id}`,
    isBackorder: false,
  };
}

