async function finalizeAndCreateBotOrder(phone, session) {
  const {
    name,
    email,
    quantity,
    pickup,
    shippingProvider,
    shippingProviderName,
    shippingCost = 0,
    address,
    dedication,
  } = session.orderData;

  const isPickup = pickup !== "delivery";
  const originAddress = session.orderData.shippingOrigin || (await getBotSetting("shipping_origin_address")) || "באר יעקב";
  const finalAddress = isPickup
    ? `איסוף עצמי מכתובת העסק (${originAddress})`
    : address;

  const totalPrice = quantity * 122 + (isPickup ? 0 : (shippingCost || 0));

  const botRes = await createBotOrder({
    name,
    phone,
    email,
    quantity,
    pickup: isPickup ? "pickup" : "delivery",
    shippingProvider: isPickup ? null : shippingProvider,
    shippingCost: isPickup ? 0 : shippingCost,
    totalPrice,
    address: finalAddress,
    dedication,
  });

  const newOrder = botRes.order;
  const checkoutUrl = botRes.paymentUrl || botRes.checkoutUrl;

  const deliveryDesc = isPickup
    ? `📍 אופן אספקה: איסוף עצמי מכתובת העסק (${originAddress} - ללא עלות נוספת)`
    : `🚚 משלוח: ${shippingProviderName || "משלוח"} (${shippingCost} ₪)\n📍 כתובת למשלוח: ${address}`;

  const dedicationDesc = dedication ? `✍️ הקדשה/הערה: "${dedication}"\n` : "";

  await sendMessage(
    phone,
    `📋 סיכום ההזמנה שלך (#${newOrder.order_number}):\n👤 שם: ${name}\n🍾 כמות: ${quantity} בקבוקים (${quantity * 122} ₪)\n${deliveryDesc}\n${dedicationDesc}💰 סה״כ לתשלום: ${totalPrice} ₪\n\n💳 לתשלום מאובטח ב-Bit / Apple Pay / אשראי:\n${checkoutUrl}\n\n${CLOSING_MOTTO}`
  );

  setSession(phone, { ageVerified: true, step: "MAIN_MENU", orderData: {} });
}

