const { searchParams } = new URL(req.url);
const checkLatest = searchParams.get("checkLatest");
if (checkLatest) {
  const { data } = await supabaseAdmin.from("orders").select("id, order_number, customer_name, customer_phone, delivery_address, pickup_method, status, created_at, admin_notes").order("created_at", { ascending: false }).limit(5);
  const decrypted = (data || []).map((o: any) => ({
    ...o,
    dec_name: decrypt(o.customer_name),
    dec_phone: decrypt(o.customer_phone),
    dec_address: decrypt(o.delivery_address),
  }));
  return NextResponse.json({ success: true, latest: decrypted });
}

const checkSetting = searchParams.get("checkSetting");
if (checkSetting) {
  if (checkSetting === "ALL") {
    const { data } = await supabaseAdmin.from("settings").select("*");
    return NextResponse.json({ success: true, settings: data });
  }
  const { data } = await supabaseAdmin.from("settings").select("*").eq("id", checkSetting).maybeSingle();
  return NextResponse.json({ success: true, setting: data });
}

