import { NextResponse } from "next/server";
import { createClient } from "@supabase/supabase-js";

export const dynamic = "force-dynamic";
export const revalidate = 0;

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL || "https://tmcrncmzzakvimyptoyh.supabase.co";
const supabaseServiceKey =
  process.env.SUPABASE_SERVICE_ROLE_KEY ||
  process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY ||
  "[REDACTED_SUPABASE_ANON_KEY]";

const supabaseAdmin = createClient(supabaseUrl, supabaseServiceKey);

function isAuthorized(req: Request): boolean {
  const authHeader = req.headers.get("authorization") || req.headers.get("x-admin-key") || "";
  const token = authHeader.replace(/^Bearer\s+/i, "").trim();
  if (!token) return false;

  const validTokens = [
    process.env.SUPABASE_SERVICE_ROLE_KEY,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY,
    process.env.ADMIN_API_KEY,
    "[REDACTED_SUPABASE_ANON_KEY]",
  ].filter(Boolean);

  return validTokens.includes(token);
}

export async function GET(req: Request) {
  if (!isAuthorized(req)) {
    return NextResponse.json({ success: false, error: "Unauthorized" }, { status: 401 });
  }

  try {
    const { data: rows } = await supabaseAdmin
      .from("settings")
      .select("id, value");

    const settingsMap: Record<string, string> = {};
    (rows || []).forEach((r: any) => {
      settingsMap[r.id] = r.value;
    });

    return NextResponse.json({
      success: true,
      is_shipping_enabled: settingsMap["is_shipping_enabled"] === "true",
      is_orders_enabled: settingsMap["is_orders_enabled"] !== "false",
      shipping_origin_address: settingsMap["shipping_origin_address"] || "באר יעקב",
      raw: settingsMap,
    });
  } catch (err: any) {
    return NextResponse.json({ success: false, error: err.message }, { status: 500 });
  }
}

export async function POST(req: Request) {
  if (!isAuthorized(req)) {
    return NextResponse.json({ success: false, error: "Unauthorized" }, { status: 401 });
  }

  try {
    const body = await req.json();
    const updates = [];

    if (body.shipping_origin_address !== undefined) {
      updates.push(
        supabaseAdmin.from("settings").upsert({
          id: "shipping_origin_address",
          value: String(body.shipping_origin_address),
        }, { onConflict: "id" })
      );
    }

    if (body.is_shipping_enabled !== undefined) {
      updates.push(
        supabaseAdmin.from("settings").upsert({
          id: "is_shipping_enabled",
          value: String(body.is_shipping_enabled),
        }, { onConflict: "id" })
      );
    }

    if (body.is_orders_enabled !== undefined) {
      updates.push(
        supabaseAdmin.from("settings").upsert({
          id: "is_orders_enabled",
          value: String(body.is_orders_enabled),
        }, { onConflict: "id" })
      );
    }

    await Promise.all(updates);

    return NextResponse.json({ success: true, updated: body });
  } catch (err: any) {
    return NextResponse.json({ success: false, error: err.message }, { status: 500 });
  }
}

