// --- 1. Buy Flow (Aligned with Website Fields & Settings) ---
async function handleBuyQtyChoice(phone, text, session) {
  const qtyMap = { "1": 1, "2": 2, "3": 3, "4": 4 };
  const qty = qtyMap[text];
  if (!qty) {
    await sendMessage(phone, `אנא בחר ספרה בין 1 ל-4 עבור כמות הבקבוקים (או 0 לתפריט):`);
    return;
  }

  session.orderData = { quantity: qty, bottlePrice: 122 };
  session.step = "BUY_NAME";
  setSession(phone, session);

  await sendMessage(
    phone,
    `מעולה! 🍋\nאנא הקלד את שמך המלא (שם פרטי ומשפחה) שיופיע על גבי ההזמנה והקבלה:`
  );
}

async function handleBuyNameInput(phone, text, session) {
  const trimmedName = (text || "").trim();
  if (!trimmedName || trimmedName.length < 2) {
    await sendMessage(phone, `אנא הקלד שם מלא תקין (שם פרטי ומשפחה):`);
    return;
  }

  session.orderData.name = trimmedName;
  session.step = "BUY_EMAIL";
  setSession(phone, session);

  await sendMessage(
    phone,
    `תודה ${trimmedName}! 📝\n\nאנא הקלד את כתובת האימייל שלך (למשלוח החשבונית/קבלה ועדכוני הזמנה):\n(ניתן להשיב "9" או "דלג" להמשך ללא מייל, או "0" לתפריט הראשי)`
  );
}

async function handleBuyEmailInput(phone, text, session) {
  const rawEmail = (text || "").trim();
  const isSkip = rawEmail === "9" || rawEmail === "דלג" || rawEmail === "ללא" || rawEmail === "-";

  if (!isSkip) {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(rawEmail)) {
      await sendMessage(
        phone,
        `כתובת האימייל אינה תקינה. אנא הקלד כתובת אימייל תקינה (למשל: name@example.com)\nאו השב "9" / "דלג" להמשך (או "0" לתפריט הראשי):`
      );
      return;
    }
    session.orderData.email = rawEmail;
  } else {
    session.orderData.email = `${phone}@whatsapp.morancello.com`;
  }

  // Check shipping policy from settings (aligned with website)
  const settings = await getBotSettingsBundle();
  const isShippingEnabled = Boolean(settings.is_shipping_enabled);
  const originAddress = cleanOriginAddress(settings.shipping_origin_address);
  session.orderData.shippingOrigin = originAddress;

  if (!isShippingEnabled) {
    // Shipping is disabled on site! Only pickup from business origin address is allowed.
    session.orderData.pickup = "pickup";
    session.orderData.shippingProvider = null;
    session.orderData.shippingCost = 0;
    session.orderData.address = `איסוף עצמי מכתובת העסק (${originAddress})`;
    session.step = "BUY_DEDICATION";
    setSession(phone, session);

    await sendMessage(
      phone,
      `אופן אספקה:\n📍 איסוף עצמי מכתובת העסק: ${originAddress} (ללא עלות נוספת).\n\nתרצו להוסיף הקדשה אישית / ברכה על הבקבוק, או הערות מיוחדות להזמנה? ✍️\n\nהשב עם תוכן ההקדשה (או השב "9" / "ללא" / "דלג" להמשך לתשלום, או "0" לתפריט הראשי):`
    );
  } else {
    // Shipping is enabled - present options
    session.step = "BUY_PICKUP";
    setSession(phone, session);

    await sendMessage(
      phone,
      `כיצד תרצו לקבל את ההזמנה? 🍋\n\n1️⃣ איסוף עצמי מכתובת העסק (${originAddress} - ללא עלות)\n2️⃣ משלוח עד הבית\n\nהשב 1 או 2 (או 0 לתפריט):`
    );
  }
}

async function handleBuyPickupChoice(phone, text, session) {
  const originAddress = cleanOriginAddress(session.orderData.shippingOrigin);

  if (text === "1") {
    // Self pickup: strictly and only business origin address
    session.orderData.pickup = "pickup";
    session.orderData.shippingProvider = null;
    session.orderData.shippingCost = 0;
    session.orderData.address = `איסוף עצמי מכתובת העסק (${originAddress})`;
    session.step = "BUY_DEDICATION";
    setSession(phone, session);

    await sendMessage(
      phone,
      `נבחר איסוף עצמי מכתובת העסק: ${originAddress} (ללא עלות). 🍋\n\nתרצו להוסיף הקדשה אישית / ברכה על הבקבוק, או הערות מיוחדות להזמנה? ✍️\n\nהשב עם תוכן ההקדשה (או השב "9" / "ללא" / "דלג" להמשך לתשלום, או "0" לתפריט הראשי):`
    );
  } else if (text === "2") {
    // Delivery requested
    session.step = "BUY_ADDRESS";
    setSession(phone, session);

    await sendMessage(
      phone,
      `🚚 לאן לשלוח את המורנצ׳לו שלך?\n\nאנא הקלד כתובת מלאה (עיר, רחוב ומספר בית)\nאו שלח מיקום 📍 דרך כפתור הסיכה (Location):`
    );
  } else {
    await sendMessage(phone, `אנא השב 1 לאיסוף עצמי או 2 למשלוח עד הבית (או 0 לתפריט):`);
  }
}

async function handleBuyAddressInput(phone, text, location, session) {
  let address = text;
  if (location) {
    address = location.name || `${location.degreesLatitude}, ${location.degreesLongitude}`;
