    session.orderData.shippingCost = 0;
    session.orderData.address = `איסוף עצמי מכתובת העסק (${originAddress})`;
    session.step = "BUY_DEDICATION";
    setSession(phone, session);

    await sendMessage(
      phone,
      `נבחר איסוף עצמי מכתובת העסק: ${originAddress} (ללא עלות). 🍋\n\nתרצו להוסיף הקדשה אישית / ברכה על הבקבוק, או הערות מיוחדות להזמנה? ✍️\n\nהשב עם תוכן ההקדשה (או השב "0" / "ללא" להמשך לתשלום):`
    );
  } else if (text === "2") {
    // Delivery requested
    session.step = "BUY_ADDRESS";
    setSession(phone, session);

    await sendMessage(
      phone,
      `🚚 לאן לשלוח את המורנצ׳לו שלך?\n\nאנא הקלד כתובת מלאה (עיר, רחוב ומספר בית)\nאו שלח מיקום 📍 דרך כפתור הסיכה (Location):`
    );
  } else {
    await sendMessage(phone, `אנא השב 1 לאיסוף עצמי או 2 למשלוח עד הבית (או 0 לתפריט):`);
  }
}

async function handleBuyAddressInput(phone, text, location, session) {
  let address = text;
  if (location) {
    address = location.name || `${location.degreesLatitude}, ${location.degreesLongitude}`;
  }

  if (!address || address.length < 4) {
    await sendMessage(phone, `נא לציין כתובת מלאה כולל עיר, רחוב ומספר בית (לדוגמה: רוטשילד 15, תל אביב):`);
    return;
  }

  session.orderData.address = address;
  session.step = "BUY_SHIPPING";
  setSession(phone, session);

  await sendMessage(
    phone,
    `📍 כתובת למשלוח: ${address}\n\nאפשרויות השילוח הזמינות:\n1️⃣ שליח עד הבית (GetPackage) — 25 ₪\n2️⃣ נקודת חלוקה קרובה (צ'יטה) — 18 ₪\n3️⃣ שליח אקספרס מהיום להיום (Yango) — 38 ₪\n4️⃣ שינוי כתובת\n\nהשב עם הספרה המבוקשת (1-4):`
  );
}

async function handleBuyShippingChoice(phone, text, session) {
  if (text === "4") {
    session.step = "BUY_ADDRESS";
    setSession(phone, session);
    await sendMessage(phone, `אנא הקלד את הכתובת החדשה למשלוח:`);
    return;
  }

  const shippingOptions = {
    "1": { name: "שליח עד הבית (GetPackage)", provider: "getpackage", cost: 25 },
    "2": { name: "נקודת חלוקה (צ'יטה)", provider: "cheetah", cost: 18 },
    "3": { name: "שליח אקספרס מהיום להיום (Yango)", provider: "yango", cost: 38 },
  };

  const choice = shippingOptions[text];
  if (!choice) {
    await sendMessage(phone, `אנא בחר אפשרות שילוח בין 1 ל-4:`);
    return;
  }

  session.orderData.pickup = "delivery";
  session.orderData.shippingProvider = choice.provider;
  session.orderData.shippingProviderName = choice.name;
  session.orderData.shippingCost = choice.cost;
  session.step = "BUY_DEDICATION";
  setSession(phone, session);

  await sendMessage(
    phone,
    `מעולה, נבחר משלוח: ${choice.name} (${choice.cost} ₪).\n\nתרצו להוסיף הקדשה אישית / ברכה על הבקבוק, או הערות מיוחדות להזמנה? ✍️\n\nהשב עם תוכן ההקדשה (או השב "0" / "ללא" להמשך לתשלום):`
  );
}

async function handleBuyDedicationInput(phone, text, session) {
  const rawDedication = (text || "").trim();
  const isSkip = rawDedication === "0" || rawDedication === "ללא" || rawDedication === "דלג" || rawDedication === "-";

  session.orderData.dedication = isSkip ? null : rawDedication;

  await finalizeAndCreateBotOrder(phone, session);
}

async function finalizeAndCreateBotOrder(phone, session) {
  const {
    name,
    email,
    quantity,
    pickup,
    shippingProvider,
    shippingProviderName,
    shippingCost = 0,
    address,
    dedication,
  } = session.orderData;

  const isPickup = pickup !== "delivery";
  const originAddress = session.orderData.shippingOrigin || (await getBotSetting("shipping_origin_address")) || "באר יעקב";
  const finalAddress = isPickup
    ? `איסוף עצמי מכתובת העסק (${originAddress})`
    : address;

