fun fetchAndRefreshWidget(context: Context) {
    Thread {
        try {
            val defaultAuthToken = "[REDACTED_SUPABASE_ANON_KEY]"
            var physQty = -1
            var resQty = -1
            var backorderQty = 0

            // 1. Try Production API first (Orders & Inventory)
            try {
                val prodApiUrl = URL("https://morancello.com/api/admin/orders")
                val conn = prodApiUrl.openConnection() as HttpURLConnection
                conn.requestMethod = "GET"
                conn.setRequestProperty("Authorization", "Bearer $defaultAuthToken")
                conn.connectTimeout = 6000
                conn.readTimeout = 6000
                if (conn.responseCode == 200) {
                    val res = conn.inputStream.bufferedReader().use { it.readText() }
                    val json = JSONObject(res)
                    if (json.optBoolean("success", false) && json.has("inventory")) {
                        val inv = json.getJSONObject("inventory")
                        physQty = inv.optInt("physical", -1)
                        resQty = inv.optInt("reserved", -1)
                        backorderQty = inv.optInt("backorder_bottles", 0)
                    }
                }
            } catch (e: Exception) {
                e.printStackTrace()
            }

            // 2. Fetch Support Tickets from Production API
            var openTicketsCount = 0
            var unreadTicketsCount = 0
            var latestTicketText = ""
            try {
                val ticketsApiUrl = URL("https://morancello.com/api/admin/tickets")
                val tConn = ticketsApiUrl.openConnection() as HttpURLConnection
                tConn.requestMethod = "GET"
                tConn.setRequestProperty("Authorization", "Bearer $defaultAuthToken")
                tConn.connectTimeout = 6000
                tConn.readTimeout = 6000
                if (tConn.responseCode == 200) {
                    val res = tConn.inputStream.bufferedReader().use { it.readText() }
                    val json = JSONObject(res)
                    if (json.optBoolean("success", false) && json.has("tickets")) {
                        val ticketsArr = json.getJSONArray("tickets")
                        for (i in 0 until ticketsArr.length()) {
                            val tObj = ticketsArr.getJSONObject(i)
                            val status = tObj.optString("status", "open")
                            if (status != "resolved" && status != "closed") {
                                openTicketsCount++
                                if (status == "open") {
                                    unreadTicketsCount++
                                }
                                if (latestTicketText.isEmpty()) {
                                    val tNum = tObj.optInt("ticket_number", 0)
                                    val cName = tObj.optString("customer_name", "לקוח")
                                    latestTicketText = "#T-$tNum $cName"
                                }
                            }
                        }
                    }
                }
            } catch (e: Exception) {
                e.printStackTrace()
            }

            // 3. Direct Supabase Fallback for Inventory
            if (physQty < 0 || resQty < 0) {
                val supabaseUrl = "https://tmcrncmzzakvimyptoyh.supabase.co"
                val apiKey = defaultAuthToken

                val invUrl = URL("$supabaseUrl/rest/v1/products?select=inventory(physical_quantity,reserved_quantity)&is_active=eq.true&order=created_at.asc&limit=1")
                val invConn = invUrl.openConnection() as HttpURLConnection
                invConn.requestMethod = "GET"
                invConn.setRequestProperty("apikey", apiKey)
                invConn.setRequestProperty("Authorization", "Bearer $apiKey")
                invConn.connectTimeout = 6000
                invConn.readTimeout = 6000

                if (invConn.responseCode == 200) {
                    val response = invConn.inputStream.bufferedReader().use { it.readText() }
                    val jsonArr = JSONArray(response)
                    if (jsonArr.length() > 0) {
                        val prodObj = jsonArr.getJSONObject(0)
