fun fetchAndRefreshWidget(context: Context) {
    Thread {
        try {
            var physQty = -1
            var resQty = -1
            var backorderQty = 0

            // 1. Try Production API first
            try {
                val prodApiUrl = URL("https://morancello.com/api/admin/orders")
                val conn = prodApiUrl.openConnection() as HttpURLConnection
                conn.requestMethod = "GET"
                conn.connectTimeout = 5000
                conn.readTimeout = 5000
                if (conn.responseCode == 200) {
                    val res = conn.inputStream.bufferedReader().use { it.readText() }
                    val json = JSONObject(res)
                    if (json.optBoolean("success", false) && json.has("inventory")) {
                        val inv = json.getJSONObject("inventory")
                        physQty = inv.optInt("physical", -1)
                        resQty = inv.optInt("reserved", -1)
                        backorderQty = inv.optInt("backorder_bottles", 0)
                    }
                }
            } catch (e: Exception) {}

            // 2. Direct Supabase Fallback
            if (physQty < 0 || resQty < 0) {
                val supabaseUrl = "https://fivniyiuttzbfbxmxecl.supabase.co"
                val apiKey = "[REDACTED_SUPABASE_ANON_KEY]"

                val invUrl = URL("$supabaseUrl/rest/v1/products?select=inventory(physical_quantity,reserved_quantity)&is_active=eq.true&order=created_at.asc&limit=1")
                val invConn = invUrl.openConnection() as HttpURLConnection
                invConn.requestMethod = "GET"
                invConn.setRequestProperty("apikey", apiKey)
                invConn.setRequestProperty("Authorization", "Bearer $apiKey")
                invConn.connectTimeout = 5000
                invConn.readTimeout = 5000

                if (invConn.responseCode == 200) {
                    val response = invConn.inputStream.bufferedReader().use { it.readText() }
                    val jsonArr = JSONArray(response)
                    if (jsonArr.length() > 0) {
                        val prodObj = jsonArr.getJSONObject(0)
                        val invObj = if (prodObj.has("inventory")) {
                            val invArr = prodObj.optJSONArray("inventory")
                            if (invArr != null && invArr.length() > 0) invArr.getJSONObject(0) else prodObj.optJSONObject("inventory")
                        } else null
                        if (invObj != null) {
                            physQty = invObj.optInt("physical_quantity", 0)
                            resQty = invObj.optInt("reserved_quantity", 0)
                        }
                    }
                }
            }

            if (physQty >= 0 && resQty >= 0) {
                val availableBal = physQty - resQty
                val prefs = context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
                prefs.edit().apply {
                    putInt("physical_stock", physQty)
                    putInt("reserved_stock", resQty)
                    putInt("available_stock", availableBal)
                    putInt("backorders_stock", backorderQty)
                    apply()
                }
            }

            Handler(Looper.getMainLooper()).post {
                updateAllWidgets(context)
            }
        } catch (e: Exception) {
            e.printStackTrace()
        }
    }.start()
}

