import { NativeModules, Platform } from 'react-native';
import { loadAllReminders, getReasonLabel } from './reminders';
import { fetchInventoryStats } from './orders';
import { fetchSupportTickets, getReadTicketIds } from './supportTickets';
import { logInfo, logError } from './logger';

const { MorancelloWidgetModule } = NativeModules;

export async function syncWidgetData(): Promise<void> {
  if (Platform.OS !== 'android' || !MorancelloWidgetModule) {
    return;
  }

  try {
    const [inv, reminders, tickets, readTicketIds] = await Promise.all([
      fetchInventoryStats().catch(() => ({ available: 0, physical: 0, reserved: 0, backorder_bottles: 0, backorder_count: 0 })),
      loadAllReminders().catch(() => []),
      fetchSupportTickets().catch(() => []),
      getReadTicketIds().catch(() => []),
    ]);

    const activeReminders = reminders
      .filter((r) => !r.isCompleted)
      .sort((a, b) => a.dueTimestamp - b.dueTimestamp);

    let nextReminderText = '🔔 אין תזכורות קרובות';
    if (activeReminders.length > 0) {
      const next = activeReminders[0];
      const timeStr = new Date(next.dueTimestamp).toLocaleTimeString('he-IL', {
        hour: '2-digit',
        minute: '2-digit',
      });
      const reasonStr = getReasonLabel(next.reasonType, next.customReasonText);
      const name = next.customerName ? `${next.customerName} - ` : '';
      nextReminderText = `🔔 ${timeStr} ${name}${reasonStr}`;
    }

    const openTickets = tickets.filter(
      (t) => t.status !== 'resolved' && t.status !== 'closed'
    );
    const unreadTickets = openTickets.filter(
      (t) => !readTicketIds.includes(t.id)
    );

    let latestTicketText = '';
    if (openTickets.length > 0) {
      const latest = openTickets[0];
      const name = latest.customer_name ? `${latest.customer_name}` : 'לקוח';
      latestTicketText = `#T-${latest.ticket_number} ${name}`;
    }

    if (MorancelloWidgetModule.updateWidgetDataWithTickets) {
      MorancelloWidgetModule.updateWidgetDataWithTickets(
        inv.physical || 0,
        inv.reserved || 0,
        inv.backorder_bottles || 0,
        nextReminderText,
        openTickets.length,
        unreadTickets.length,
        latestTicketText
      );
    } else if (MorancelloWidgetModule.updateWidgetData) {
      MorancelloWidgetModule.updateWidgetData(
        inv.physical || 0,
        inv.reserved || 0,
        inv.backorder_bottles || 0,
        nextReminderText
      );
    }

    logInfo('WIDGET', 'Successfully updated Android Widget stock and tickets data', {
      physical: inv.physical,
      reserved: inv.reserved,
      available: inv.available,
      backorder_bottles: inv.backorder_bottles,
      nextReminderText,
      openTicketsCount: openTickets.length,
      unreadTicketsCount: unreadTickets.length,
      latestTicketText,
    });
  } catch (e) {
    logError('WIDGET', 'Failed to sync widget data', e);
  }
}

