import android.content.Context
import com.facebook.react.bridge.Promise
import com.facebook.react.bridge.ReactApplicationContext
import com.facebook.react.bridge.ReactContextBaseJavaModule
import com.facebook.react.bridge.ReactMethod

class MorancelloWidgetModule(reactContext: ReactApplicationContext) : ReactContextBaseJavaModule(reactContext) {

    override fun getName(): String = "MorancelloWidgetModule"

    @ReactMethod
    fun getInitialWidgetAction(promise: Promise) {
        try {
            val activity = currentActivity
            val action = activity?.intent?.action
            val route = when (action) {
                "com.anonymous.mobile.OPEN_TICKETS" -> "support"
                "com.anonymous.mobile.CREATE_ORDER" -> "create_order"
                else -> null
            }
            if (route != null) {
                activity?.intent?.action = null
            }
            promise.resolve(route)
        } catch (e: Exception) {
            promise.resolve(null)
        }
    }

    @ReactMethod
    fun updateWidgetData(physicalStock: Int, reservedStock: Int, backordersStock: Int, nextReminder: String) {
        updateWidgetDataWithTickets(physicalStock, reservedStock, backordersStock, nextReminder, 0, 0, "")
    }

    @ReactMethod
    fun updateWidgetDataWithTickets(
        physicalStock: Int,
        reservedStock: Int,
        backordersStock: Int,
        nextReminder: String,
        openTicketsCount: Int,
        unreadTicketsCount: Int,
        latestTicketText: String
    ) {
        val available = physicalStock - reservedStock
        val prefs = reactApplicationContext.getSharedPreferences(MorancelloWidgetProvider.PREFS_NAME, Context.MODE_PRIVATE)
        prefs.edit().apply {
            putInt("physical_stock", physicalStock)
            putInt("reserved_stock", reservedStock)
            putInt("available_stock", available)
            putInt("backorders_stock", backordersStock)
            putString("next_reminder", nextReminder)
            putInt("open_tickets_count", openTicketsCount)
            putInt("unread_tickets_count", unreadTicketsCount)
            putString("latest_ticket_text", latestTicketText)
            apply()
        }
        MorancelloWidgetProvider.updateAllWidgets(reactApplicationContext)
    }
}

