async function getBotSettingsBundle() {
  const siteUrl = (process.env.SITE_URL || "https://www.morancello.com").replace(/\/$/, "");
  const token = process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY || DEFAULT_AUTH_TOKEN;
  try {
    const res = await fetch(`${siteUrl}/api/whatsapp/settings`, {
      headers: {
        Authorization: `Bearer ${token}`,
      },
    });
    if (res.ok) {
      const data = await res.json();
      if (data && data.success) {
        return {
          is_shipping_enabled: Boolean(data.is_shipping_enabled),
          is_orders_enabled: data.is_orders_enabled !== false,
          shipping_origin_address: cleanOriginAddress(data.shipping_origin_address),
          bot_session_timeout_minutes: parseInt(data.bot_session_timeout_minutes, 10) || 30,
        };
      }
    }
  } catch (err) {
    console.error("[WhatsApp Bot] Error fetching settings bundle from API:", err.message);
  }

  // Fallback to direct Supabase query
  try {
    const shippingVal = await getBotSetting("is_shipping_enabled");
    const ordersVal = await getBotSetting("is_orders_enabled");
    const originVal = await getBotSetting("shipping_origin_address");
    const timeoutVal = await getBotSetting("bot_session_timeout_minutes");

    return {
      is_shipping_enabled: shippingVal === "true",
      is_orders_enabled: ordersVal !== "false",
      shipping_origin_address: cleanOriginAddress(originVal),
      bot_session_timeout_minutes: timeoutVal ? (parseInt(timeoutVal, 10) || 30) : 30,
    };
  } catch (e) {
    return {
      is_shipping_enabled: false,
      is_orders_enabled: true,
      shipping_origin_address: "באר יעקב",
      bot_session_timeout_minutes: 30,
    };
  }
}

