// --- Session Store (Memory with configurable TTL) ---
const userSessions = new Map();

let cachedSessionTimeoutMinutes = 30;
let lastSettingsFetch = 0;

async function refreshBotSettingsCache() {
  if (Date.now() - lastSettingsFetch < 20000) return; // 20s cache throttle
  try {
    const bundle = await getBotSettingsBundle();
    if (bundle && bundle.bot_session_timeout_minutes) {
      cachedSessionTimeoutMinutes = bundle.bot_session_timeout_minutes;
    }
    lastSettingsFetch = Date.now();
  } catch (e) {}
}

function getSession(phone) {
  const session = userSessions.get(phone);
  if (!session) return null;
  const timeoutMs = (cachedSessionTimeoutMinutes || 30) * 60 * 1000;
  if (Date.now() - session.lastActive > timeoutMs) {
    userSessions.delete(phone);
    return null;
  }
  return session;
}

