import React, { useState, useEffect } from "react";
import { MessageSquare, RefreshCw, CheckCircle2, AlertCircle, LogOut, Send, Smartphone, QrCode, Clock, Save } from "lucide-react";

interface BotStatus {
  status: "connected" | "qr_ready" | "disconnected";
  qr?: string | null;
  phone?: string | null;
  updatedAt?: string;
}

export function AdminWhatsAppBot() {
  const [statusData, setStatusData] = useState<BotStatus>({ status: "disconnected" });
  const [loading, setLoading] = useState(true);
  const [actionLoading, setActionLoading] = useState(false);
  const [testPhone, setTestPhone] = useState("");
  const [testMsgSent, setTestMsgSent] = useState(false);
  const [testError, setTestError] = useState("");

  const [sessionTimeoutMinutes, setSessionTimeoutMinutes] = useState(30);
  const [savingTimeout, setSavingTimeout] = useState(false);
  const [timeoutSavedMsg, setTimeoutSavedMsg] = useState("");

  const fetchStatus = async () => {
    try {
      const res = await fetch("/api/whatsapp/status", { cache: "no-store" });
      if (res.ok) {
        const data = await res.json();
        setStatusData(data);
      }
    } catch (e) {
      console.error("Error fetching whatsapp bot status:", e);
    } finally {
      setLoading(false);
    }
  };

  const fetchSettings = async () => {
    try {
      const res = await fetch("/api/whatsapp/settings", {
        headers: {
          Authorization: "Bearer [REDACTED_SUPABASE_ANON_KEY]",
