function isSessionExpired(session) {
  if (!session || !session.lastActive) return true;
  const timeoutMs = (cachedSessionTimeoutMinutes || 30) * 60 * 1000;
  return Date.now() - session.lastActive > timeoutMs;
}

function clearSession(phone) {
  if (!phone) return;
  const session = userSessions.get(phone);
  if (session) {
    if (session.replyJid && session.replyJid !== phone) {
      userSessions.delete(session.replyJid);
    }
    if (session.realPhone && session.realPhone !== phone) {
      userSessions.delete(session.realPhone);
    }
  }
  userSessions.delete(phone);
}

function getSession(phone) {
  if (!phone) return null;
  const session = userSessions.get(phone);
  if (!session) return null;
  if (isSessionExpired(session)) {
    clearSession(phone);
    return null;
  }
  return session;
}

function setSession(phone, data = {}) {
  if (!phone) return;
  // If the session was expired, getSession clears it and returns null
  const existing = getSession(phone) || {};
  const updated = {
    ...existing,
    ...data,
    lastActive: Date.now(),
  };
  userSessions.set(phone, updated);
  if (updated.replyJid && updated.replyJid !== phone) {
    userSessions.set(updated.replyJid, updated);
  }
  if (updated.realPhone && updated.realPhone !== phone) {
    userSessions.set(updated.realPhone, updated);
  }
  return updated;
}

// Background cleanup sweep for expired sessions (every 60 seconds)
