+  options?: { reason?: string; sendEmail?: boolean }
+): Promise<RefundResult> {
+  try {
+    const { data: order, error: fetchErr } = await supabaseAdmin
+      .from("orders")
+      .select("*")
+      .eq("id", orderId)
+      .maybeSingle();
+
+    if (fetchErr || !order) {
+      return { success: false, refunded: false, error: "ההזמנה לא נמצאה במערכת" };
+    }
+
+    if (order.status === "cancelled") {
+      return { success: true, refunded: false, message: "ההזמנה כבר מבוטלת" };
+    }
+
+    const isPaid = order.status === "paid" || order.status === "shipped" || order.status === "delivered";
+    const amountToRefund = order.total_price || 0;
+
+    let refundNotes = "";
+    let wasRefunded = false;
+
+    const nowStr = new Date().toLocaleString("he-IL");
+
+    if (isPaid && amountToRefund > 0) {
+      const refundRes = await executeMeshulamRefund(orderId, amountToRefund, order.admin_notes || "");
