+      : `${refundNotes}${reasonText}`;
+
+    // Update order status to 'cancelled'
+    const { error: updateErr } = await supabaseAdmin
+      .from("orders")
+      .update({
+        status: "cancelled",
+        admin_notes: updatedNotes,
+      })
+      .eq("id", orderId);
+
+    if (updateErr) {
+      console.error("Error updating order to cancelled:", updateErr);
+      return { success: false, refunded: false, error: updateErr.message };
+    }
+
+    // Recalculate inventory & advance queue
+    try {
+      await recalculateReservedInventory();
+      await processBackorderQueue();
+    } catch (e) {
+      console.error("Error updating queue after cancel:", e);
+    }
+
+    // Send cancellation email with credit receipt link if requested (default true)
+    if (options?.sendEmail !== false) {
+      try {
+        let decEmail = order.customer_email;
+        let decName = order.customer_name;
+        try { decEmail = decrypt(order.customer_email) || decEmail; } catch (e) {}
+        try { decName = decrypt(order.customer_name) || decName; } catch (e) {}
+
+        if (decEmail) {
+          await sendOrderCancelledEmail({
+            to: decEmail,
+            customerName: decName || "לקוח יקר",
+            orderNumber: order.order_number || order.id.substring(0, 8),
+          });
+        }
+      } catch (e) {
+        console.error("Error sending cancellation email:", e);
+      }
+    }
+
+    return {
+      success: true,
+      refunded: wasRefunded,
+      refundAmount: amountToRefund,
+      message: isPaid ? `ההזמנה בוטלה והרכישה בסך ${amountToRefund} ₪ זוכתה בהצלחה` : "ההזמנה והשריון בוטלו בהצלחה",
+    };
+  } catch (err: any) {
+    console.error("Error in processOrderRefundAndCancellation:", err);
+    return { success: false, refunded: false, error: err?.message || "שגיאה בביטול וזיכוי ההזמנה" };
+  }
+}

