// --- Session Store (Memory with configurable TTL) ---
const userSessions = new Map();

// --- Inbound Message Deduplication Cache ---
const processedMessageIds = new Map();

function isDuplicateMessage(msgId) {
  if (!msgId) return false;
  const now = Date.now();
  if (processedMessageIds.size > 2000) {
    for (const [id, time] of processedMessageIds.entries()) {
      if (now - time > 300000) processedMessageIds.delete(id);
    }
  }
  if (processedMessageIds.has(msgId)) {
    return true;
  }
  processedMessageIds.set(msgId, now);
  return false;
}

// --- Inbound Customer Messages Listener ---
sock.ev.on("messages.upsert", async ({ messages, type }) => {
  // Only process live notifications; ignore synced/appended history
  if (type !== "notify") return;

  // Keep settings cache fresh
  await refreshBotSettingsCache();

  for (const m of messages) {
    if (!m.message || m.key.fromMe) continue;
    const from = m.key.remoteJid;
    if (!from || from.includes("@g.us") || from.includes("status@broadcast")) continue;

    const msgId = m.key?.id;
    if (msgId && isDuplicateMessage(msgId)) {
      continue;
    }

    const text = extractMessageText(m.message);
    const location = extractMessageLocation(m.message);

    // Ignore empty messages, protocol messages, reaction stanzas
    if (!text && !location) continue;

    let senderPhone = await extractSenderPhoneNumber(m);
    const pushName = m.pushName || "";

    // Check if previous session expired before modifying anything
    const activeSession = getSession(senderPhone) || getSession(from);
    if (!activeSession) {
      clearSession(senderPhone);
      clearSession(from);
    }

    // Store replyJid and pushName in session
    setSession(senderPhone, { replyJid: from, realPhone: senderPhone, pushName });
    if (from !== senderPhone) {
      setSession(from, { replyJid: from, realPhone: senderPhone, pushName });
    }

    // Send read receipt and presence indicator
    try {
      await sock.readMessages([m.key]);
      await sock.sendPresenceUpdate("composing", from);
    } catch (e) {}

    console.log(`[WhatsApp Bot] Inbound message from ${senderPhone} (${from}): "${text.substring(0, 40)}"`);

